    edges = []
    for a in range(k):
        for b in range(k):
            for c in range(k):
                u = (a, b)
                v = (b, c)
                edges.append((vertex_to_idx[u], vertex_to_idx[v]))

    return vertices, edges

def has_cycle(edges, num_vertices):
    """Check if graph has any cycle using DFS"""
    adj = {i: [] for i in range(num_vertices)}
    for u, v in edges:
        adj[u].append(v)

    color = [0] * num_vertices  # 0=white, 1=gray, 2=black

    def dfs(node):
        color[node] = 1
        for neighbor in adj[node]:
            if color[neighbor] == 1:
                return True
            if color[neighbor] == 0 and dfs(neighbor):
                return True
        color[node] = 2
        return False

    for i in range(num_vertices):
        if color[i] == 0 and dfs(i):
            return True
    return False

def max_acyclic_subgraph(k):
    """Find maximum number of edges in an acyclic subgraph"""
    vertices, edges = build_debruijn_graph(k)
    num_edges = len(edges)
    num_vertices = len(vertices)

    max_edges = 0

    # Try all subsets
    for r in range(num_edges + 1):
        for subset in itertools.combinations(range(num_edges), r):
            kept_edges = [edges[i] for i in subset]
            if not has_cycle(kept_edges, num_vertices):
                max_edges = max(max_edges, r)

    return max_edges

def min_feedback_edge_set(k):
    """Minimum edges to remove to make graph acyclic"""
    vertices, edges = build_debruijn_graph(k)
    num_edges = len(edges)
    max_edges = max_acyclic_subgraph(k)
    return num_edges - max_edges

