def build_graph(k, m):
    """Build De Bruijn graph B(k,m) and return vertices and edges"""
    vertices = [tuple(s) for s in product(range(k), repeat=m)]
    vertex_to_idx = {v: i for i, v in enumerate(vertices)}

    edges = []
    for v in vertices:
        prefix = v[1:]
        for c in range(k):
            w = prefix + (c,)
            edges.append((v, w))

    return vertices, edges

def has_cycle(num_vertices, edge_list):
