"""
Bao-good numbers:
a is bao-good if there exist integers (s,l) such that:
1. For all positive b: a ∤ s^b - l (i.e., s^b ≢ l mod a)
2. For every proper divisor a' of a: ∃b such that a' | s^b - l

Let's test small values of a systematically.
"""

def is_bao_good(a):
    """Check if a is bao-good by searching for suitable (s,l)"""
    if a == 1:
        # No proper divisors, so condition 2 is vacuously true
        # But condition 1: need s^b ≢ 1 (mod 1), which is impossible since everything ≡ 0 (mod 1)
        return False, None

    # Search for s in range [1, a] and l in range [0, a-1]
    for s in range(1, a + 1):
        for l in range(0, a):
            # Check condition 1: s^b ≢ l (mod a) for all b
            condition1_ok = True
            for b in range(1, a + 1):
                if pow(s, b, a) == l % a:
                    condition1_ok = False
                    break
            if not condition1_ok:
                continue

            # Check condition 2: for each proper divisor a', ∃b such that s^b ≡ l (mod a')
            condition2_ok = True
            for a_prime in range(1, a):
                if a % a_prime == 0:
                    # a' is a proper divisor
                    found_b = False
                    for b in range(1, a + 1):
                        if pow(s, b, a_prime) == l % a_prime:
                            found_b = True
                            break
                    if not found_b:
                        condition2_ok = False
                        break

            if condition2_ok:
                return True, (s, l)

    return False, None

