from itertools import combinations
from collections import deque

def generate_subgroup(G, generators):
    """Generate subgroup from given generators in abelian group G"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = g + h
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def game_state_to_tuple(T, G):
    return tuple(sorted(T))

def get_valid_moves(T, G):
    """Get all valid moves from state T"""
    return [g for g in G if g not in T]

def simulate_game(G):
    """Determine who wins using memoized game theory"""
    # State is the set T
    memo = {}

    def can_win(T):
        if game_state_to_tuple(T, G) in memo:
            return memo[game_state_to_tuple(T, G)]

        valid_moves = get_valid_moves(T, G)
        if not valid_moves:
            memo[game_state_to_tuple(T, G)] = False  # Cannot move, lose
            return False

        for g in valid_moves:
            new_T = generate_subgroup(G, list(T) + [g])
            if not can_win(new_T):
                memo[game_state_to_tuple(T, G)] = True  # Can force opponent to lose
                return True
        memo[game_state_to_tuple(T, G)] = False
        return False

    # Start with T = {0}
    initial_T = {0}
    alice_can_win = can_win(initial_T)
    return "Alice" if alice_can_win else "Bob"

