        print(f"Z_{p}^n (order {p**n}): Grundy = {g}, {'Bob wins' if g == 0 else 'Alice wins'}")

"""
Game on finite abelian group G:
- T starts with {1_G}
- Players alternate adding an element g not in T
- When g is added, all of <T ∪ {g}> are moved into T
- Last player to move wins (normal play)
"""
from functools import lru_cache

def generate_subgroup(G, generators):
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = g + h
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def simulate_game(G):
    memo = {}

    def can_win(T):
        key = tuple(sorted(T))
        if key in memo:
            return memo[key]

        valid_moves = [g for g in G if g not in T]
        if not valid_moves:
            memo[key] = False
            return False

        for g in valid_moves:
            new_T = generate_subgroup(G, list(T) + [g])
            if not can_win(new_T):
                memo[key] = True
                return True
        memo[key] = False
        return False

    initial_T = {0}
    return "Alice" if can_win(initial_T) else "Bob"

def test_groups():
    results = {}
    for n in range(2, 21):
        G = list(range(n))
        winner = simulate_game(G)
        results[n] = winner
        print(f"|G|={n}: {winner}")
    return results

