# Use prime factorization approach
def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def generate_groups(max_order):
    """Generate all abelian groups by combining cyclic factors"""
    groups = []

    # Get all possible prime factorizations up to max_order
    def get_prime_powers(n):
        """Get all prime power factors of n"""
        result = []
        d = 2
        temp = n
        while d * d <= temp:
            if temp % d == 0:
                power = d
                while temp % d == 0:
                    power *= d
                    temp //= d
                result.append(power)
            d += 1
        if temp > 1:
            result.append(temp)
        return result

    # Generate all ways to partition prime powers into cyclic groups
    def generate_from_powers(powers, current):
        if not powers:
            groups.append(list(current))
            return

        power = powers[0]
        # Try all possible cyclic group orders that divide this power
        # Actually, we need to split power into factors
        # For power p^k, we can have C_{p^k}, or C_{p^a} x C_{p^b} where a+b=k

        # Find all divisors
        divisors = []
        d = 1
        while d * d <= power:
            if power % d == 0:
                divisors.append(d)
                if d * d != power:
                    divisors.append(power // d)
            d += 1

        for i in range(len(divisors)):
            # This is getting complex, let me simplify
            pass

    # Simpler approach: just generate all products
    def backtrack(current, remaining, min_factor):
        if remaining == 1:
            groups.append(list(current))
            return
        for f in range(min_factor, remaining + 1):
            if remaining % f == 0:
                current.append(f)
                backtrack(current, remaining // f, f)
                current.pop()

    backtrack([], max_order, 2)
    return groups

