from itertools import combinations, product
from math import gcd
from functools import lru_cache

def compute_grundy_Zn(n):
    """Compute Grundy for Z_n."""
    elements = list(range(n))

    def generate_subgroup(generators):
        d = n
        for g in generators:
            d = gcd(d, g)
        return set(range(0, n, d))

    divisors = sorted([d for d in range(1, n+1) if n % d == 0], reverse=True)
    subgroups = [frozenset(range(0, n, d)) for d in divisors]

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = subgroups[idx]
        next_grundies = []

        for g in elements:
            if g not in H:
                d = n
                for h in H:
                    d = gcd(d, h)
                d = gcd(d, g)
                new_H = frozenset(range(0, n, d))
                next_grundies.append(grundy(subgroups.index(new_H)))

        if not next_grundies:
            return 0

        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial_idx = subgroups.index(frozenset([0]))
    return grundy(trivial_idx)

def compute_grundy_Zp_n(n, p):
    """Compute Grundy for Z_p^n."""
    all_elements = list(product(range(p), repeat=n))
    identity = tuple([0] * n)

    def generate_subgroup(generators):
        subgroup = {identity}
        queue = [identity]
        changed = True

        while changed:
            changed = False
            for gen in generators:
                for base in list(subgroup):
                    for mult in range(p):
                        new_elem = tuple((base[i] + gen[i] * mult) % p for i in range(n))
                        if new_elem not in subgroup:
                            subgroup.add(new_elem)
                            queue.append(new_elem)
                            changed = True
        return subgroup

    all_subgroups = set()
    all_subgroups.add(frozenset([identity]))

    for r in range(1, n + 1):
        for gens in combinations(all_elements, r):
            H = generate_subgroup(list(gens))
            all_subgroups.add(frozenset(H))

    @lru_cache(maxsize=None)
    def grundy(H_tuple):
        H = set(H_tuple)
        next_grundies = []
        for g in all_elements:
            if g not in H:
                new_H = generate_subgroup(list(H) + [g])
                next_grundies.append(grundy(frozenset(new_H)))

        if not next_grundies:
            return 0

        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial = frozenset([identity])
    return grundy(trivial)

