from functools import lru_cache
import math
from collections import deque

def group_to_list(G):
    elements = [tuple()]
    for n in G:
        new_elements = []
        for e in elements:
            for i in range(n):
                new_elements.append(e + (i,))
        elements = new_elements
    return elements

def element_add(a, b):
    return tuple((x + y) % n for x, y, n in zip(a, b, G))

def subgroup_generated_by(elements, G):
    G_list = group_to_list(G)
    visited = set()
    queue = deque()

    zero = tuple(0 for _ in G)
    visited.add(zero)
    queue.append(zero)

    for e in elements:
        visited.add(e)
        queue.append(e)

    while queue:
        curr = queue.popleft()
        for gen in elements:
            for k in range(1, G[0] + 1):
                new_elem = tuple((k * g) % n for g, n in zip(gen, G))
                if new_elem not in visited:
                    visited.add(new_elem)
                    queue.append(new_elem)

            new_elem = element_add(curr, gen)
            if new_elem not in visited:
                visited.add(new_elem)
                queue.append(new_elem)

    return frozenset(visited)

def game_length(G):
    G_list = group_to_list(G)
    zero = tuple(0 for _ in G)
    full = frozenset(G_list)

    @lru_cache(None)
    def grundy(H):
        if H == full:
            return 0

        next_states = []
        for g in G_list:
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, G)
                next_states.append(grundy(new_H))

        if not next_states:
            return 0

        seen = set(next_states)
        mex = 0
        while mex in seen:
            mex += 1
        return mex

    return grundy(frozenset({zero}))

# Generate all abelian groups up to order 30 by listing them manually
# Abelian groups are classified by invariant factors
# For order n, list all partitions of prime powers

def get_abelian_groups(max_order):
    """Generate all abelian groups up to given order"""
    groups = []

    # Get all n <= max_order and their prime power decompositions
    for n in range(2, max_order + 1):
        # Get prime factorization
        factors = []
        temp = n
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                factors.append(d)
                temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)

        # Group consecutive same primes
        prime_powers = []
        if factors:
            curr = factors[0]
            power = 1
            for f in factors:
                power *= f
                if f != curr:
                    prime_powers.append(power)
                    curr = f
                    power = 1
            prime_powers.append(power)

        # Now generate all ways to partition each prime power
        # For p^k, we can have C_{p^k} or C_{p^a} x C_{p^b} x ... where product = p^k

        def partitions_of_power(p, k):
            """Get all ways to write p^k as product of cyclic orders"""
            if k == 0:
                return [[1]]
            if k == 1:
                return [[p]]

            result = []
            # Try first factor p^j for j from 1 to k
            for j in range(1, k + 1):
                remaining = k - j
                for rest in partitions_of_power(p, remaining):
                    result.append([p**j] + rest)
            return result

        # Combine all prime power partitions
        def combine_partitions(partitions):
            if not partitions:
                return [[]]
            result = []
            for p_part in partitions[0]:
                for rest in combine_partitions(partitions[1:]):
                    result.append(p_part + rest)
            return result

        partitions = [partitions_of_power(f, int(math.log(f, f))) for f in prime_powers]
        all_combinations = combine_partitions(partitions)

        for combo in all_combinations:
            groups.append(combo)

    return groups

