"""
Game: Alice and Bob take turns adding elements to a box T.
When an element g is added, all elements of <T U {g}> are added to T.
Alice moves first. Last player to move wins (normal play).
Find all G where Bob has a winning strategy.
Then, determine the sum of the 10 smallest possible values of |G|>1 such that Bob has a winning strategy.
"""

from functools import lru_cache

def generate_subgroup_Zn(generators, n):
    """Generate subgroup of Z_n from generators"""
    if not generators:
        return set([0])
    subgroup = set([0])
    changed = True
    while changed:
        changed = False
        for g in generators:
            for h in list(subgroup):
                new_elem = (g + h) % n
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
    return subgroup

def generate_subgroup_Zn1_Zn2(generators, n1, n2):
    """Generate subgroup of Z_n1 x Z_n2 from generators"""
    if not generators:
        return {(0, 0)}
    subgroup = {(0, 0)}
    changed = True
    while changed:
        changed = False
        for g in generators:
            for h in list(subgroup):
                new_elem = ((g[0] + h[0]) % n1, (g[1] + h[1]) % n2)
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
    return subgroup

def solve_game_Zn(n):
    """Solve game for Z_n"""
    @lru_cache(maxsize=None)
    def first_player_wins(T_tuple):
        T = set(T_tuple)
        if len(T) >= n:
            return False
        for g in range(n):
            if g not in T:
                generators = list(T) + [g]
                new_subgroup = generate_subgroup_Zn(generators, n)
                new_T = T | new_subgroup
                new_T_tuple = tuple(sorted(new_T))
                if not first_player_wins(new_T_tuple):
                    return True
        return False
    return first_player_wins(tuple(sorted([0])))

def solve_game_Zn1_Zn2(n1, n2):
    """Solve game for Z_n1 x Z_n2"""
    total_elements = n1 * n2

    @lru_cache(maxsize=None)
    def first_player_wins(T_tuple):
        T = set(T_tuple)
        if len(T) >= total_elements:
            return False
        for g in range(total_elements):
            x, y = divmod(g, n2)
            if (x, y) not in T:
                generators = list(T) + [(x, y)]
                new_subgroup = generate_subgroup_Zn1_Zn2(generators, n1, n2)
                new_T = T | new_subgroup
                new_T_tuple = tuple(sorted(new_T))
                if not first_player_wins(new_T_tuple):
                    return True
        return False

    initial_T = {(0, 0)}
    return first_player_wins(tuple(sorted(initial_T)))

