from functools import lru_cache
import math
from collections import deque, defaultdict

def group_to_list(G):
    elements = [tuple()]
    for n in G:
        new_elements = []
        for e in elements:
            for i in range(n):
                new_elements.append(e + (i,))
        elements = new_elements
    return elements

def element_add(a, b):
    return tuple((x + y) % n for x, y, n in zip(a, b, G))

def subgroup_generated_by(elements, G):
    G_list = group_to_list(G)
    visited = set()
    queue = deque()

    zero = tuple(0 for _ in G)
    visited.add(zero)
    queue.append(zero)

    for e in elements:
        visited.add(e)
        queue.append(e)

    while queue:
        curr = queue.popleft()
        for gen in elements:
            for k in range(1, G[0] + 1):
                new_elem = tuple((k * g) % n for g, n in zip(gen, G))
                if new_elem not in visited:
                    visited.add(new_elem)
                    queue.append(new_elem)

            new_elem = element_add(curr, gen)
            if new_elem not in visited:
                visited.add(new_elem)
                queue.append(new_elem)

    return frozenset(visited)

def game_length(G):
    G_list = group_to_list(G)
    zero = tuple(0 for _ in G)
    full = frozenset(G_list)

    @lru_cache(None)
    def grundy(H):
        if H == full:
            return 0

        next_states = []
        for g in G_list:
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, G)
                next_states.append(grundy(new_H))

        if not next_states:
            return 0

        seen = set(next_states)
        mex = 0
        while mex in seen:
            mex += 1
        return mex

    return grundy(frozenset({zero}))

def get_groups_by_order(max_order):
    """Generate all abelian groups up to given order, sorted and deduplicated"""
    groups = set()

    for n in range(2, max_order + 1):
        # Get prime factorization
        factors = []
        temp = n
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                factors.append(d)
                temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)

        # Group by prime
        prime_groups = defaultdict(list)
        for f in factors:
            prime_groups[f].append(f)

        # For each prime p with multiplicity k, generate all partitions
        def partitions_of_powers(powers):
            if not powers:
                return [[]]

            powers = sorted(powers, reverse=True)
            result = []
            p = powers[0]
            rest = partitions_of_powers(powers[1:])

            for r in rest:
                for i in range(len(r) + 1):
                    if i == 0 or r[i-1] >= p:
                        new_r = r[:i] + [p] + r[i:]
                        result.append(new_r)
            return result

        def combine_all(prime_partitions):
            if not prime_partitions:
                return [[]]
            result = []
            for p_part in prime_partitions[0]:
                for rest in combine_all(prime_partitions[1:]):
                    result.append(p_part + rest)
            return result

        prime_parts = []
        for p, powers in prime_groups.items():
            parts = partitions_of_powers(powers)
            prime_parts.append(parts)

        all_combos = combine_all(prime_parts)
        for combo in all_combos:
            groups.add(tuple(sorted(combo)))

    return sorted(groups)

# Find all groups with order <= 30 where Bob wins
