def compute_new_subgroup(current, g, m, k):
    new_sub = set(current)
    changed = True
    while changed:
        changed = False
        for h in list(new_sub):
            new_h = ((h[0] + g[0]) % m, (h[1] + g[1]) % k)
            if new_h not in new_sub:
                new_sub.add(new_h)
                changed = True
            neg_g = ((-g[0]) % m, (-g[1]) % k)
            new_h2 = ((h[0] + neg_g[0]) % m, (h[1] + neg_g[1]) % k)
            if new_h2 not in new_sub:
                new_sub.add(new_h2)
                changed = True
    return frozenset(new_sub)

