    for r in range(len(G) + 1):
        from itertools import combinations
        for subset in combinations(G, r):
            S = set(subset)
            if (0, 0) not in S:
                continue
            if all((-a[0] % m, -a[1] % k) in S for a in S):
                if all(((a[0] + b[0]) % m, (a[1] + b[1]) % k) in S for a in S for b in S):
                    key = frozenset(subset)
                    if key not in seen:
                        seen.add(key)
                        subgroups.append(key)

    @lru_cache(maxsize=None)
    def can_first_player_win(current_subgroup):
        full_group = frozenset(((a, b) for a in range(m) for b in range(k)))
