def compute_grundy_Zp_n(n, p):
    """Compute Grundy for Z_p^n."""
    all_elements = list(product(range(p), repeat=n))
    identity = tuple([0] * n)

    def generate_subgroup(generators):
        subgroup = {identity}
        queue = [identity]
        changed = True

        while changed:
            changed = False
            for gen in generators:
                for base in list(subgroup):
                    for mult in range(p):
                        new_elem = tuple((base[i] + gen[i] * mult) % p for i in range(n))
                        if new_elem not in subgroup:
                            subgroup.add(new_elem)
                            queue.append(new_elem)
                            changed = True
        return subgroup

    all_subgroups = set()
    all_subgroups.add(frozenset([identity]))

    for r in range(1, n + 1):
        for gens in combinations(all_elements, r):
            H = generate_subgroup(list(gens))
            all_subgroups.add(frozenset(H))

    @lru_cache(maxsize=None)
