"""
Test the conjecture: Bob wins iff the minimum number of generators is even.
For a finite abelian group G, the minimum number of generators is the maximum of the minimum generators for each p-primary component.

Actually, for direct products, it's the sum of minimum generators for each component.
"""
from math import gcd
from functools import lru_cache

def compute_new_subgroup(current, g, m, k):
    new_sub = set(current)
    changed = True
    while changed:
        changed = False
        for h in list(new_sub):
            new_h = ((h[0] + g[0]) % m, (h[1] + g[1]) % k)
            if new_h not in new_sub:
                new_sub.add(new_h)
                changed = True
            neg_g = ((-g[0]) % m, (-g[1]) % k)
            new_h2 = ((h[0] + neg_g[0]) % m, (h[1] + neg_g[1]) % k)
            if new_h2 not in new_sub:
                new_sub.add(new_h2)
                changed = True
    return frozenset(new_sub)

def solve_game_Z_mZ_k(m, k):
    G = [(a, b) for a in range(m) for b in range(k)]
    subgroups = []
    seen = set()
    for r_idx in range(len(G) + 1):
        for subset in combinations(G, r_idx):
            S = set(subset)
            if (0, 0) not in S:
                continue
            if all((-a[0] % m, -a[1] % k) in S for a in S):
                if all(((a[0] + b[0]) % m, (a[1] + b[1]) % k) in S for a in S for b in S):
                    key = frozenset(subset)
                    if key not in seen:
                        seen.add(key)
                        subgroups.append(key)

    @lru_cache(maxsize=None)
    def can_first_player_win(current_subgroup):
        full_group = frozenset(G)
        if current_subgroup == full_group:
            return False
        for g in G:
            if g not in current_subgroup:
                new_subgroup = compute_new_subgroup(current_subgroup, g, m, k)
                if not can_first_player_win(new_subgroup):
                    return True
        return False

    alice_can_win = can_first_player_win(frozenset({(0, 0)}))
    return not alice_can_win

