from functools import lru_cache
from collections import deque

def group_to_list(G):
    elements = [tuple()]
    for n in G:
        new_elements = []
        for e in elements:
            for i in range(n):
                new_elements.append(e + (i,))
        elements = new_elements
    return elements

def element_add(a, b):
    return tuple((x + y) % n for x, y, n in zip(a, b, G))

def subgroup_generated_by(elements, G):
    G_list = group_to_list(G)
    visited = set()
    queue = deque()
    zero = tuple(0 for _ in G)
    visited.add(zero)
    queue.append(zero)
    for e in elements:
        visited.add(e)
        queue.append(e)
    while queue:
        curr = queue.popleft()
        for gen in elements:
            for k in range(1, G[0] + 1):
                new_elem = tuple((k * g) % n for g, n in zip(gen, G))
                if new_elem not in visited:
                    visited.add(new_elem)
                    queue.append(new_elem)
            new_elem = element_add(curr, gen)
            if new_elem not in visited:
                visited.add(new_elem)
                queue.append(new_elem)
    return frozenset(visited)

def game_length(G):
    G_list = group_to_list(G)
    zero = tuple(0 for _ in G)
    full = frozenset(G_list)
    @lru_cache(None)
    def grundy(H):
        if H == full:
            return 0
        next_states = []
        for g in G_list:
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, G)
                next_states.append(grundy(new_H))
        if not next_states:
            return 0
        seen = set(next_states)
        mex = 0
        while mex in seen:
            mex += 1
        return mex
    return grundy(frozenset({zero}))

