    G = [(a,) for a in [0, 1]]
    for i in range(n):
        G = [(x + (1,)) if x[i] == 0 else x for x in G]

    # Proper tuple creation
    G = []
    for i in range(2**n):
        bits = [(i >> j) & 1 for j in range(n)]
        G.append(tuple(bits))

    memo = {}
    def can_win(T):
        key = tuple(sorted(T))
        if key in memo:
            return memo[key]
        valid = [g for g in G if g not in T]
        if not valid:
            memo[key] = False
            return False
        for g in valid:
            new_T = set(T)
            new_T.add(g)
            for h in list(new_T):
                for k in list(new_T):
                    s = tuple((h[i] + k[i]) % 2 for i in range(n))
                    if s not in new_T:
                        new_T.add(s)
            if not can_win(new_T):
                memo[key] = True
                return True
        memo[key] = False
        return False

    return "Alice" if can_win({(0,) * n}) else "Bob"

