from itertools import product

def generate_subgroup_module(generators_list, orders):
    num_dims = len(orders)
    identity = tuple(0 for _ in range(num_dims))
    non_id = [g for g in generators_list if g != identity]
    if not non_id:
        return [identity]
    subgroup = [identity]
    changed = True
    while changed:
        changed = False
        for g in non_id:
            for s in subgroup:
                new_g = tuple((g[i] + s[i]) % orders[i] for i in range(num_dims))
                if new_g not in subgroup:
                    subgroup.append(new_g)
                    changed = True
    return subgroup

def get_group_elements(orders):
    if len(orders) == 1:
        return [(i,) for i in range(orders[0])]
    return list(product(*(range(n) for n in orders)))

def solve_game_abelian(orders):
    all_elements = get_group_elements(orders)
    n = len(all_elements)

    def add(a, b):
        return tuple((a[i] + b[i]) % orders[i] for i in range(len(orders)))

    def gen_subgroup(generators_list):
        return generate_subgroup_module(generators_list, orders)

    def get_new_elements(current_T, new_element):
        new_generators = current_T + [new_element]
        new_subgroup = gen_subgroup(new_generators)
        return [x for x in new_subgroup if x not in current_T]

    def get_all_moves(T):
        current_set = set(T)
        return [x for x in all_elements if x not in current_set]

    memo = {}

    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]

        possible_moves = get_all_moves(T)

        if not possible_moves:
            memo[T_tuple] = False
            return False

        for move in possible_moves:
            new_T = T + get_new_elements(T, move)
            if not solve(new_T):
                memo[T_tuple] = True
                return True

        memo[T_tuple] = False
        return False

    identity = tuple(0 for _ in orders)
    initial_T = [identity]
    alice_wins = solve(initial_T)
    return alice_wins

