def can_be_period(outputs, p):
    """Check if p could be the period given outputs from consecutive inputs"""
    # For p to be valid, outputs[i] == outputs[i+p] whenever i+p < len(outputs)
    # Also f must be nonconstant, so not all outputs equal
    if len(outputs) < 2:
        return False
    if all(y == outputs[0] for y in outputs):
        return False  # f must be nonconstant
    for i in range(len(outputs) - p):
        if outputs[i] != outputs[i + p]:
            return False
    return True

def find_minimal_n():
    """Find smallest n where outputs uniquely determine p"""
    for n in range(2, 100):
        # Check if there exists an output pattern that's ambiguous
        # (could come from two different primes)
        ambiguous = False
        for p1 in primes:
            for p2 in primes:
                if p1 == p2:
                    continue
                # Can we construct outputs consistent with both p1 and p2?
                # For this, outputs must satisfy both periodicity constraints
                # And f must be nonconstant
                if len(primes) < 2:
                    continue
                # Build a candidate pattern that works for both
                # Try: make outputs periodic with LCM(p1, p2)
                from math import gcd
                lcm = p1 * p2 // gcd(p1, p2)
                if lcm >= 100:
                    # Can't have both periods with nonconstant f
                    continue
                # Try to construct outputs with period lcm
                pattern = []
                for i in range(lcm):
                    # Assign values, ensuring nonconstant
                    if i == 0:
                        pattern.append(0)
                    else:
                        pattern.append(0 if i < p1 else 1)
                # Check if this pattern works for both p1 and p2
                valid_p1 = True
                valid_p2 = True
                for i in range(len(pattern) - p1):
                    if pattern[i] != pattern[i + p1]:
                        valid_p1 = False
                for i in range(len(pattern) - p2):
                    if pattern[i] != pattern[i + p2]:
                        valid_p2 = False
                if valid_p1 and valid_p2:
                    ambiguous = True
                    break
            if ambiguous:
                break
        if not ambiguous:
            return n
    return 100

