def is_connected(n, p1, p2):
    """Check if constraint graph is connected (all positions in one component)"""
    same = {i: {i} for i in range(n)}
    for i in range(n - p1):
        same[i].add(i + p1)
        same[i + p1].add(i)
    for i in range(n - p2):
        same[i].add(i + p2)
        same[i + p2].add(i)

    visited = set()
    for i in range(n):
        if i not in visited:
            stack = [i]
            while stack:
                pos = stack.pop()
                if pos in visited:
                    continue
                visited.add(pos)
                for neighbor in same[pos]:
                    if neighbor not in visited:
                        stack.append(neighbor)
    return len(visited) == n

