def solve_with_backtracking(n):
    """Try to find a valid filling using backtracking."""
    if n <= 1:
        return None

    proper_divisors = [d for d in range(2, n) if n % d == 0]
    if not proper_divisors:
        return True  # No constraints

    # Try different initial patterns first
    patterns = [
        lambda n: [[i * n + j + 1 for j in range(n)] for i in range(n)],  # row-major
        lambda n: [[j + 1 + i * n for i in range(n)] for j in range(n)],  # col-major
        lambda n: [[(i + j) % n + 1 + i * n for j in range(n)] for i in range(n)],  # diagonal
        lambda n: [[(n - 1 - i) * n + j + 1 for j in range(n)] for i in range(n)],  # reverse row
