import random

def is_cool(n, trials=50000):
    """Check if n is cool."""
    divisors = [d for d in range(2, n) if n % d == 0]
    if not divisors:
        return True

    for _ in range(trials):
        board = [[0] * n for _ in range(n)]
        perm = list(range(1, n*n + 1))
        random.shuffle(perm)
        for k in range(n*n):
            r, c = k // n, k % n
            board[r][c] = perm[k]

        valid = True
        for d in divisors:
            for i in range(0, n, d):
                for j in range(0, n, d):
                    s = sum(board[r][c] for r in range(i, i+d) for c in range(j, j+d))
                    if s % d == 0:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break

        if valid:
            return True
    return False

