def solve():
    def find_list(n, x1):
        xn = x1 + 27
        target_sum = 8 * n

        # Check basic sum feasibility
        if n * x1 > target_sum or n * xn < target_sum:
            return None

        def dfs(idx, current_sum, counts, last_val):
            if idx == 0:
                val = x1
                return dfs(1, val, Counter({val: 1}), val)

            if idx == n - 1:
                val = xn
                if current_sum + val != target_sum:
                    return None
                new_counts = Counter({val: counts.get(val, 0) + 1})
                # Reconstruct list
                lst = []
                for v in range(x1, xn + 1):
                    lst.extend([v] * new_counts[v])
                # Check median
                if n % 2 == 1:
                    if lst[n // 2] != 13:
                        return None
                else:
                    if (lst[n // 2 - 1] + lst[n // 2]) / 2 != 13:
                        return None
                # Check mode
                max_freq = max(new_counts.values())
                modes = [k for k, v in new_counts.items() if v == max_freq]
                if 15 not in modes or len(modes) > 1:
                    return None
                return lst

            # Pruning
            remaining = n - 1 - idx
            min_rem = last_val * remaining
            max_rem = xn * remaining
            if current_sum + min_rem > target_sum:
                return None
            if current_sum + max_rem < target_sum:
                return None

            # Median constraint for odd n
            if n % 2 == 1:
                median_idx = n // 2
                if idx == median_idx:
                    if last_val > 13:
                        return None
                    # Try val = 13
                    new_sum = current_sum + 13
                    new_counts = Counter({13: counts.get(13, 0) + 1})
                    return dfs(idx + 1, new_sum, new_counts, 13)
                elif idx > median_idx:
                    if last_val < 13:
                        return None

            # Mode constraint: if 15 not in counts and last_val > 15, we can't place 15
            if 15 not in counts and last_val > 15:
                return None

            # Iterate values
            for val in range(last_val, xn + 1):
                if current_sum + val > target_sum:
                    break

                new_counts = Counter({val: counts.get(val, 0) + 1})

                # Check sum feasibility
                remaining = n - 1 - idx
                min_rem = val * remaining
                max_rem = xn * remaining
                if current_sum + val + min_rem > target_sum:
                    continue
                if current_sum + val + max_rem < target_sum:
                    continue

                res = dfs(idx + 1, current_sum + val, new_counts, val)
                if res is not None:
                    return res
            return None

        return dfs(0, 0, {}, 0)

    for n in range(1, 50):
        for x1 in range(1, 14):
            res = find_list(n, x1)
            if res is not None:
                print(f"n={n}, x1={x1}, list={res}")
                return n

