def brute(n, max_val_limit=30):
    target = 8 * n
    # Generate all combinations with sum = target
    # Use recursion

    def gen(current, min_val, remaining, current_sum):
        if remaining == 0:
            if current_sum == target:
                return [current[:]]
            return []
        results = []
        for v in range(min_val, max_val_limit):
            if current_sum + v * remaining <= target:
                current.append(v)
                results.extend(gen(current, v, remaining - 1, current_sum + v))
                current.pop()
        return results

    candidates = gen([], 1, n, 0)
    for lst in candidates:
        if check(lst):
            return lst
    return None

