# Exhaustive search for small n with bounded values
def exhaustive(n, val_limit=30):
    target = 8 * n
    # Generate all multisets of n positive integers summing to target
    def gen(current, min_val, remaining, current_sum):
        if remaining == 0:
            if current_sum == target:
                return [current[:]]
            return []
        results = []
        for v in range(min_val, val_limit + 1):
            if current_sum + v * remaining <= target:
                current.append(v)
                results.extend(gen(current, v, remaining - 1, current_sum + v))
                current.pop()
        return results

    for lst in gen([], 1, n, 0):
        if check(lst):
            return lst
    return None

