from itertools import permutations

def student_score(ranks):
    """
    ranks: list of n ranks (1-indexed) for n races
    score = max(a-b) where student is in top b at least a times
    """
    n = len(ranks)
    # Count how many times student is in top b for each b
    top_counts = [0] * (n + 1)
    for rank in ranks:
        for b in range(1, rank + 1):
            top_counts[b] += 1

    # Score is max(c_b - b) for b from 1 to n
    # But need a >= 1, so b must be at least 1 and c_b >= 1
    best = float('-inf')
    for b in range(1, n + 1):
        if top_counts[b] >= 1:
            best = max(best, top_counts[b] - b)
    return best

