"""
Problem: n students, n races, each race has a ranking.
Student score = max(a-b) where they are in top b places in at least a races.
Find maximum possible sum of all scores.

Answer: n*(n-1)/2

Verified by brute force for small n.
"""

import itertools

def compute_score(student_finishes):
    n = len(student_finishes)
    c = [0] * (n + 1)
    for pos in student_finishes:
        for b in range(pos, n + 1):
            c[b] += 1
    score = max(c[b] - b for b in range(1, n + 1))
    return score

def total_score(n, races):
    scores = [0] * n
    for i in range(n):
        positions = [races[j][i] for j in range(n)]
        scores[i] = compute_score(positions)
    return sum(scores)

def max_score_bruteforce(n):
    if n == 1:
        return 0
    if n == 2:
        perms = list(itertools.permutations([1, 2]))
        max_s = 0
        for r1 in perms:
            for r2 in perms:
                races = [r1, r2]
                s = total_score(2, races)
                if s > max_s:
                    max_s = s
        return max_s
    if n == 3:
        perms = list(itertools.permutations([1, 2, 3]))
        max_s = 0
        for r1 in perms:
            for r2 in perms:
                for r3 in perms:
                    races = [r1, r2, r3]
                    s = total_score(3, races)
                    if s > max_s:
                        max_s = s
        return max_s

# Verify formula n*(n-1)/2 matches brute force
assert max_score_bruteforce(1) == 1 * 0 // 2, "n=1 failed"
assert max_score_bruteforce(2) == 2 * 1 // 2, "n=2 failed"
assert max_score_bruteforce(3) == 3 * 2 // 2, "n=3 failed"

# Check that all-same-races achieves the formula for n=4,5,6
for n in range(4, 7):
    races = [[i+1 for i in range(n)] for _ in range(n)]
    actual = total_score(n, races)
    formula = n * (n - 1) // 2
    assert actual == formula, f"n={n} failed: {actual} != {formula}"

