        total += compute_score(rankings)
    return total

import itertools

def generate_latin_squares(n):
    """Generate all Latin squares of order n."""
    if n == 1:
        return [[1]]

    def backtrack(matrix, row, used_cols):
        if row == n:
            return [list(map(tuple, matrix))]

        results = []
        for perm in itertools.permutations(range(1, n+1)):
            # Check column constraints
            valid = True
            for col in range(n):
                if used_cols[col] == perm[col]:
                    valid = False
                    break
            if not valid:
                continue

            new_matrix = matrix + [list(perm)]
            new_used = used_cols[:]
            for col in range(n):
                new_used[col] = perm[col]
            results.extend(backtrack(new_matrix, row+1, new_used))
        return results

    # Fix first row to avoid duplicates (all Latin squares are equivalent under row permutation)
    first_row = list(range(1, n+1))
    return backtrack([first_row], 1, first_row)

