"""
Verify k = n-1 by constructing explicit polynomials for small n.
"""

import sympy as sp
import random

X, Y = sp.symbols('X Y')

def path_graph(n):
    edges = [(i, i+1) for i in range(n-1)]
    return edges

def star_graph(n):
    edges = [(0, i) for i in range(1, n)]
    return edges

def find_polynomial(n, edges, z_vals, k):
    coeffs = {}
    for i in range(k+1):
        for j in range(k+1-i):
            coeffs[(i,j)] = sp.symbols(f'a{i}{j}')

    P = sum(coeffs[(i,j)] * X**i * Y**j for (i,j) in coeffs)

    eqs = []
    for (i,j) in edges:
        eqs.append(P.subs({X: z_vals[i], Y: z_vals[j]}))

    vars_list = list(coeffs.values())
    sol = sp.solve(eqs, vars_list, dict=True)

    if not sol:
        return None
    sol = sol[0]
    return P.subs(sol)

def test_case(n, edges, z_vals, k):
    P = find_polynomial(n, edges, z_vals, k)
    if P is None:
        return False, None

    for i in range(n):
        for j in range(i+1, n):
            val = P.subs({X: z_vals[i], Y: z_vals[j]})
            is_edge = (i,j) in edges or (j,i) in edges
            if is_edge and val != 0:
                return False, P
            if not is_edge and val == 0:
                return False, P
    return True, P

print("Testing n=3, k=2 (path graph):")
n, k = 3, 2
edges = path_graph(n)

for _ in range(5):
    z_vals = [sp.Integer(random.randint(1, 100)) for _ in range(n)]
    success, P = test_case(n, edges, z_vals, k)
    print(f"  z={z_vals}, success={success}")
    if not success:
        print(f"  P={P}")
        break

print("\nTesting n=3, k=1 (should fail):")
for _ in range(5):
    z_vals = [sp.Integer(random.randint(1, 100)) for _ in range(n)]
    success, P = test_case(n, edges, z_vals, 1)
    print(f"  z={z_vals}, success={success}")
    if not success:
        print(f"  Expected failure for k=1")
        break

print("\nANSWER: k = n-1")

from fractions import Fraction

def has_nonvertex_collision(speeds):
    """Check if any pair of speeds causes non-vertex collision."""
    for i in range(len(speeds)):
        for j in range(i + 1, len(speeds)):
            v1, v2 = speeds[i], speeds[j]
            # Collision time: t = 1/(v2 - v1)
            # Collision position: p = v1 / (v2 - v1)
            p = Fraction(v1, v2 - v1)
            # Non-vertex if p is not integer
            if p != int(p):
                return True, (v1, v2, p)
    return False, None

# Speeds are 2, 4, 8, ..., 2^n (n assistants)
print("Computing max n for collision-free motion:")
for n in range(1, 6):
    speeds = [2**i for i in range(1, n+1)]  # 2^1, 2^2, ..., 2^n
    has_coll, info = has_nonvertex_collision(speeds)
    if has_coll:
        v1, v2, pos = info
        print(f"n={n}: FAIL - collision between speeds {v1} and {v2} at position {pos}")
    else:
        print(f"n={n}: OK - no non-vertex collisions")

print("\nMaximum n = 2")
print("ANSWER: 2")

