from collections import Counter

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_sq_sum_abc(a, b, c):
    return gcd(a*a + b*b + c*c, a*b*c)

# Find which small integers can appear
possible = set()
for a in range(1, 50):
    for b in range(1, 50):
        for c in range(1, 50):
            d = gcd_sq_sum_abc(a, b, c)
            possible.add(d)

# Check prime factors
def prime_factors(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

print("Checking prime factors of possible values:")
