    print("\nAll possible values have only prime factors 2 or ≡ 1 mod 4")

# Generate all numbers with only primes 2 or 1 mod 4
def generate_good_numbers(max_val):
    primes_1mod4 = [5, 13, 17, 29, 37, 41, 53, 61, 73, 89, 97, 101, 109, 113]
    result = set()
    # Include powers of 2
    for i in range(1, 20):
        if 2**i <= max_val:
            result.add(2**i)
    # Include products
    from itertools import product
    # Generate combinations
    import itertools
    for primes in itertools.combinations_with_replacement(primes_1mod4, 5):
        prod = 1
        for p in primes:
            if prod * p > max_val:
                break
            prod *= p
            result.add(prod)
    return result

