from math import gcd
from collections import Counter

def compute_gcd(a, b, c):
    return gcd(a*a + b*b + c*c, a*b*c)

def prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_representable(n):
    """Check if n can be gcd(a²+b²+c², abc) for some positive integers a,b,c"""
    pf = prime_factors(n)
    for p, e in pf.items():
        if p % 4 == 3 and e % 2 == 1:
            return False
    return True

