"""
Problem: Regular polygon with update rule x_i -> x_i + 1/x_{i+1}
N(n) = number of pairs (i,j) such that P_i >= P_j at some time for ALL positive initial values.
"""
import random
import math

def simulate(n, init_vals, steps=10):
    """Simulate the update process."""
    x = list(init_vals)
    history = [x[:]]
    for t in range(steps):
        new_x = [x[i] + 1/x[(i+1)%n] for i in range(n)]
        x = new_x
        history.append(x[:])
    return history

def check_pair(n, i, j, trials=50):
    """Check if P_i >= P_j at some time for random initial values."""
    for _ in range(trials):
        init = [10**(math.log10(0.1) + random.random()*3) for _ in range(n)]
        history = simulate(n, init, steps=20)
        found = False
        for h in history:
            if h[i] >= h[j]:
                found = True
                break
        if not found:
            return False
    return True

def compute_N(n, trials=30):
    """Compute N(n) by checking all pairs."""
    N = 0
    for i in range(n):
        for j in range(n):
            if check_pair(n, i, j, trials=trials):
                N += 1
    return N

# Test small values
for n in range(1, 11):
    N_n = compute_N(n, trials=20)
    print(f"N({n}) = {N_n}")

