    for t in range(steps):
        new_x = [x[i] + 1/x[(i+1)%n] for i in range(n)]
        x = new_x
        history.append(x[:])
    return history

def has_counterexample(n, i, j, trials=500):
    """Return True if there exists initial values where P_i < P_j forever."""
    for _ in range(trials):
        # Try various initial value configurations
        for exp in [-6, -3, 0, 3, 6]:
            for sign in [-1, 1]:
                base = 10**exp
                init = [base + sign * random.random() * base/2 for _ in range(n)]
                history = simulate(n, init, steps=50)
                # Check if P_i ever >= P_j
                always_less = True
                for h in history:
                    if h[i] >= h[j]:
                        always_less = False
                        break
                if always_less:
                    return True
    return False

def compute_N(n, trials=200):
    """Compute N(n) by checking all pairs."""
    N = 0
    for i in range(n):
        for j in range(n):
            if not has_counterexample(n, i, j, trials=trials):
                N += 1
    return N

