rad(4) = 2
rad(5) = 5
rad(6) = 6
rad(8) = 2
rad(9) = 3
rad(10) = 10
"""

import math

def rad(n):
    """Compute the radical of n (product of distinct prime factors)"""
    if n == 1:
        return 1
    result = 1
    p = 2
    while p * p <= n:
        if n % p == 0:
            result *= p
            while n % p == 0:
                n //= p
        p += 1
    if n > 1:
        result *= n
    return result

def test_function(f, name, limit=20):
    for m in range(1, limit+1):
        for n in range(1, limit+1):
            lhs = f(m*n)**2
            rhs = f(m**2) * f(f(n)) * f(m*f(n))
            coprime = math.gcd(m, n) == 1
            if coprime:
                if lhs != rhs:
                    return False, f"FAIL coprime m={m}, n={n}: {lhs} != {rhs}"
            else:
                if lhs == rhs:
                    return False, f"FAIL not-coprime m={m}, n={n}: {lhs} == {rhs}"
    return True, "OK"

