# Let me try f(n) = Euler's totient function phi(n)
def phi(n):
    if n == 1:
        return 1
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

result, msg = test_function(phi, "f(n) = Euler's totient")
print(f"phi(n): {msg}")

