import math

def rad(n):
    """Compute the radical of n (product of distinct prime factors)"""
    if n == 1:
        return 1
    result = 1
    p = 2
    while p * p <= n:
        if n % p == 0:
            result *= p
            while n % p == 0:
                n //= p
        p += 1
    if n > 1:
        result *= n
    return result

