- ...
- S_20 = {k in {1} : k < 20} = {1}

Sum = 0 + 1 + 1 + ... + 1 (19 times) = 19

But wait, let me double-check by computing it in code.
"""

def compute_answer(f_func):
    """Compute the answer given a function f"""
    range_f = set()
    for n in range(1, 21):
        val = f_func(n)
        range_f.add(val)

    total = 0
    for n in range(1, 21):
        for k in range_f:
            if k < n:
                total += k
    return total

