            lhs = f_dict[m*n]**2
            rhs = f_dict[m**2] * f_dict[f_dict[n]] * f_dict[m*f_dict[n]]
            should_hold = (gcd_val == 1)
            actually_holds = (lhs == rhs)
            if should_hold != actually_holds:
                errors.append((m, n, gcd_val, lhs, rhs))
    return errors

def radical(n):
    """Product of distinct prime factors"""
    result = 1
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            result *= d
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        result *= temp
    return result

def f_radical(n):
    return radical(n)

