"""
Game: Geoff and Ceri play with numbers 1, 2, ..., N.
Geoff goes first. Each move: choose k >= 0 and n on board, remove all s where 2^k | (n-s).
Player who erases the last integer loses (misère play).
Find smallest 20 values of N where Geoff can force a win.
"""

from functools import lru_cache
from itertools import combinations

# Simulate the game
def simulate_game(N, geoff_strategy=None):
    """
    Returns True if Geoff wins, False if Ceri wins.
    geoff_strategy: function that given board state, returns (k, n) to play
    """
    board = set(range(1, N + 1))

    while len(board) > 0:
        if len(board) == 1:
            # Player whose turn it is loses (erases last number)
            return False  # Current player loses, so Geoff loses if it's his turn
        if geoff_strategy is not None:
            if geoff_strategy.__name__ == 'geoff':
                k, n = geoff_strategy(board)
            else:
                k, n = geoff_strategy(board)
        else:
            # Random or optimal strategy
            pass
        # Find all s such that 2^k | (n - s)
        new_board = set()
        for s in board:
            if (n - s) % (2**k) != 0:
                new_board.add(s)
        board = new_board

    return True  # Board empty, last player to move lost

def remove_class(board, n, k):
    """Remove all s where 2^k | (n-s)"""
    new_board = set()
    for s in board:
        if (n - s) % (2**k) != 0:
            new_board.add(s)
    return new_board

def min_k_for_n(board, n):
    """Find minimum k such that 2^k | (n-s) for some s in board"""
    for k in range(20):
        for s in board:
            if (n - s) % (2**k) == 0:
                return k
    return 20

# Let's analyze the game using minimax with memoization
def can_geoff_win(N):
    """
    Determine if Geoff can win starting with board {1, 2, ..., N}
    """
    board = tuple(range(1, N + 1))

    # Memoization: state is sorted tuple of board
    memo = {}

    def can_current_win(state):
        if state == ():
            return False  # Last player to move lost, so current player wins (previous player lost)

        state = tuple(sorted(state))
        if state in memo:
            return memo[state]

        # Current player's turn
        # Try all possible moves
        board_set = set(state)
        for n in board_set:
            for k in range(20):
                new_board = remove_class(set(state), n, k)
                if len(new_board) == 0:
                    # Current player erased last number, they lose
                    # So this move is bad for current player
                    continue

                # Next player's turn with new_board
                if not can_current_win(tuple(sorted(new_board))):
                    # If next player cannot win from this state, current player wins
                    memo[state] = True
                    return True

        # No winning move found
        memo[state] = False
        return False

    result = can_current_win(board)
    del memo
    return result

