# Key insight: The game state can be represented more compactly
# For initial positions {1, 2, ..., N}, we can use a bitmask

def analyze(N):
    # State as bitmask: bit i set means number (i+1) is on board
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def win(mask):
        if mask == 0:
            return True  # Terminal

        # Try all moves
        for n in range(1, 32):  # Numbers up to 31
            if not (mask & (1 << (n-1))):
                continue
            for k in range(10):
                p = 2**k
                # Find all numbers s where s ≡ n (mod p)
                to_erase = []
                for s in range(1, 32):
                    if mask & (1 << (s-1)) and (n - s) % p == 0:
                        to_erase.append(s)
                if not to_erase:
                    continue
                # Create new mask
                new_mask = mask
                for s in to_erase:
                    new_mask &= ~(1 << (s-1))
                if new_mask == 0:
                    continue
                if not win(new_mask):
                    return True
        return False

    return win((1 << N) - 1)

