def eval_poly(coeffs, n):
    """Evaluate polynomial with given coefficients at n."""
    result = 0
    power = 1
    for c in coeffs:
        result += c * power
        power *= n
    return result

def poly_div_mod(poly, divisor):
    """
    Divide polynomial by divisor, return (quotient, remainder).
    Both are lists of coefficients [a0, a1, ..., an].
    """
    if len(divisor) == 1:
        return [], poly

    # Make divisor monic for easier division
    divisor_lead = divisor[-1]
    divisor_monic = [c / divisor_lead for c in divisor]

    # Pad poly with zeros if needed
    deg_div = len(divisor) - 1
    deg_poly = len(poly) - 1
    if deg_poly < deg_div:
        return [], poly

    # Perform polynomial division
    quotient = [0] * (len(poly) - len(divisor))
    remainder = poly[:]

    for i in range(len(quotient) - 1, -1, -1):
        if len(remainder) < len(divisor):
            break
        coef = remainder[-1] / divisor_monic[-1]
        quotient[i] = coef
        for j in range(len(divisor)):
            remainder[-(j+1)] -= coef * divisor_monic[j]

    # Clean up remainder
    while len(remainder) > 1 and abs(remainder[-1]) < 1e-9:
        remainder.pop()

    return quotient, remainder

def check_divisibility(coeffs_P, coeffs_Q, a, b, max_n=50):
    """Check if P(n) | Q(n)^2 + aQ(n) + 1 and Q(n) | P(n)^2 + bP(n) + 1 for all n up to max_n."""
    deg_P = len(coeffs_P) - 1
    deg_Q = len(coeffs_Q) - 1

    for n in range(1, max_n + 1):
        P_val = eval_poly(coeffs_P, n)
        Q_val = eval_poly(coeffs_Q, n)

        if P_val == 0:
            if Q_val**2 + a * Q_val + 1 != 0:
                return False, n, P_val, Q_val
        if Q_val == 0:
            if P_val**2 + b * P_val + 1 != 0:
