from sympy import Poly, symbols, gcd

def check_polynomial_divisibility(P_coeffs, Q_coeffs, a, b):
    """Check if P(n) | Q(n)^2 + aQ(n) + 1 and Q(n) | P(n)^2 + bP(n) + 1 for n=1..20"""
    P = sum(c * n**i for i, c in enumerate(P_coeffs))
    Q = sum(c * n**i for i, c in enumerate(Q_coeffs))

    for n in range(1, 21):
        if P == 0 or Q == 0:
            continue
        if (Q**2 + a*Q + 1) % P != 0:
            return False
        if (P**2 + b*P + 1) % Q != 0:
            return False
    return True

def find_solutions(max_deg=3, max_coeff=5):
    """Search for solutions with polynomials of given degree."""
    solutions = []

    for deg_p in range(1, max_deg + 1):
        for deg_q in range(1, max_deg + 1):
            # P and Q are monic, so leading coefficient is 1
            # P(x) = x^deg_p + p_{deg_p-1}*x^{deg_p-1} + ... + p_0
            # Q(x) = x^deg_q + q_{deg_q-1}*x^{deg_q-1} + ... + q_0

            # Generate all coefficient combinations
            from itertools import product

            p_coeffs = [1] + list(product(range(-max_coeff, max_coeff+1), repeat=deg_p))
            q_coeffs = [1] + list(product(range(-max_coeff, max_coeff+1), repeat=deg_q))

            for P_list in p_coeffs:
                for Q_list in q_coeffs:
                    # Check if P and Q are distinct (leading terms already same)
                    if P_list == Q_list:
                        continue

                    # Try various a and b values
                    for a in range(-10, 11):
                        if abs(a) < 3:
                            continue
                        for b in range(-10, 11):
                            if abs(b) < 3:
                                continue

                            if check_polynomial_divisibility(P_list, Q_list, a, b):
                                solutions.append((P_list, Q_list, a, b))
                                break
                    if any(s[2] == a and s[3] == b for s in solutions if len(solutions) > 0):
                        break
                    if any(s[2] == a for s in solutions):
                        break
            if solutions:
                break
        if solutions:
            break

    return solutions

