    print("Pattern 1: P(x) = x^2 + mx + m, Q(x) = x^2 + (m+1)x + (m+1)")
    for m in range(-50, 50):
        P = lambda n: n**2 + m*n + m
        Q = lambda n: n**2 + (m+1)*n + (m+1)

        # We expect a = -(m+3), b = m+4
        a = -(m + 3)
        b = m + 4

        if abs(a) < 3 or abs(b) < 3:
            continue

        # Verify
        valid = True
        for n in range(1, 31):
            Pn = P(n)
            Qn = Q(n)
            if Pn == 0 or Qn == 0:
                continue
            if (Qn**2 + a*Qn + 1) % Pn != 0:
                valid = False
                break
            if (Pn**2 + b*Pn + 1) % Qn != 0:
                valid = False
                break

        if valid:
            solutions.append((2, m, m, m+1, m+1, a, b))

    # Pattern 2: P(x) = x^2 + kx + 1, Q(x) = x^2 + (k+1)x + 1
