                        break
                    if (Pn**2 + b*Pn + 1) % Qn != 0:
                        valid = False
                        break

                if valid:
                    solutions.append((2, k, 1, k+1, 1, a, b))
                    break
        if solutions and len([s for s in solutions if s[6] == b]) > 100:
            break

    # Pattern 3: P(x) = x^2 + kx + c, Q(x) = x^2 + lx + c with same constant term
    print("\nPattern 3: P(x) = x^2 + kx + c, Q(x) = x^2 + lx + c")
