"""
Let me think about this problem from a theoretical perspective.

For the divisibility conditions to hold for ALL positive integers n, the polynomials must satisfy very specific algebraic relationships.

Key insight: If P(n) | R(n) for all n >= 1, where P and R are polynomials, then either:
1. P(x) divides R(x) as polynomials, or
2. P(x) is constant (but we're told P is non-constant)

Actually, this is not quite right. The correct statement is:
If P(n) | R(n) for all sufficiently large integers n, and deg(P) > 0, then P(x) divides R(x) as polynomials over the rationals.

Let me verify this and use it to search for solutions.
"""

import numpy as np
from itertools import product

def poly_multiply(coeffs1, coeffs2):
    """Multiply two polynomials given as coefficient lists [a0, a1, ...]."""
    result = [0] * (len(coeffs1) + len(coeffs2) - 1)
    for i, c1 in enumerate(coeffs1):
        for j, c2 in enumerate(coeffs2):
            result[i + j] += c1 * c2
    return result

def poly_add(coeffs1, coeffs2):
    """Add two polynomials."""
    max_len = max(len(coeffs1), len(coeffs2))
    result = [0] * max_len
    for i, c1 in enumerate(coeffs1):
        result[i] += c1
    for i, c2 in enumerate(coeffs2):
        result[i] += c2
    return result

def poly_subtract(coeffs1, coeffs2):
    """Subtract two polynomials."""
    max_len = max(len(coeffs1), len(coeffs2))
    result = [0] * max_len
    for i, c1 in enumerate(coeffs1):
        result[i] += c1
    for i, c2 in enumerate(coeffs2):
        result[i] -= c2
    return result

def poly_divide(coeffs_poly, coeffs_divisor):
    """
    Divide polynomial by divisor, return (quotient, remainder).
    """
    if len(coeffs_divisor) == 1:
        return [], coeffs_poly

    deg_div = len(coeffs_divisor) - 1
    deg_poly = len(coeffs_poly) - 1

    if deg_poly < deg_div:
        return [], coeffs_poly

    # Make divisor monic
    divisor_lead = coeffs_divisor[-1]
    divisor_monic = [c / divisor_lead for c in coeffs_divisor]

    quotient = [0] * (len(coeffs_poly) - len(coeffs_divisor))
    remainder = coeffs_poly[:]

    for i in range(len(quotient) - 1, -1, -1):
        if len(remainder) < len(coeffs_divisor):
            break
        coef = remainder[-1] / divisor_monic[-1]
        quotient[i] = coef
        for j in range(len(coeffs_divisor)):
            remainder[-(j+1)] -= coef * divisor_monic[j]

    # Clean up remainder
    while len(remainder) > 1 and abs(remainder[-1]) < 1e-9:
        remainder.pop()

    return quotient, remainder

def check_poly_divisibility(coeffs_P, coeffs_Q, a, b):
    """Check if P(x) | Q(x)^2 + aQ(x) + 1 and Q(x) | P(x)^2 + bP(x) + 1 as polynomials."""

    # Compute Q(x)^2 + aQ(x) + 1
    Q2 = poly_multiply(coeffs_Q, coeffs_Q)
    aQ = [a * c for c in coeffs_Q]
    Q2_plus_aQ_plus_1 = poly_add(poly_add(Q2, aQ), [1])

    # Check if P divides Q^2 + aQ + 1
    _, rem1 = poly_divide(Q2_plus_aQ_plus_1, coeffs_P)
    if len(rem1) > 1 or abs(rem1[-1]) > 1e-9:
        return False

    # Compute P(x)^2 + bP(x) + 1
    P2 = poly_multiply(coeffs_P, coeffs_P)
    bP = [b * c for c in coeffs_P]
    P2_plus_bP_plus_1 = poly_add(poly_add(P2, bP), [1])

    # Check if Q divides P^2 + bP + 1
    _, rem2 = poly_divide(P2_plus_bP_plus_1, coeffs_Q)
    if len(rem2) > 1 or abs(rem2[-1]) > 1e-9:
        return False

    return True

