import numpy as np
from itertools import product

def poly_multiply(coeffs1, coeffs2):
    result = [0] * (len(coeffs1) + len(coeffs2) - 1)
    for i, c1 in enumerate(coeffs1):
        for j, c2 in enumerate(coeffs2):
            result[i + j] += c1 * c2
    return result

def poly_add(coeffs1, coeffs2):
    max_len = max(len(coeffs1), len(coeffs2))
    result = [0] * max_len
    for i, c1 in enumerate(coeffs1):
        result[i] += c1
    for i, c2 in enumerate(coeffs2):
        result[i] += c2
    return result

def poly_divide(coeffs_poly, coeffs_divisor):
    if len(coeffs_divisor) == 1:
        return [], coeffs_poly

    divisor_lead = coeffs_divisor[-1]
    divisor_monic = [c / divisor_lead for c in coeffs_divisor]

    quotient = [0] * (len(coeffs_poly) - len(coeffs_divisor))
    remainder = coeffs_poly[:]

    for i in range(len(quotient) - 1, -1, -1):
        if len(remainder) < len(coeffs_divisor):
            break
        coef = remainder[-1] / divisor_monic[-1]
        quotient[i] = coef
        for j in range(len(coeffs_divisor)):
            remainder[-(j+1)] -= coef * divisor_monic[j]

    while len(remainder) > 1 and abs(remainder[-1]) < 1e-9:
        remainder.pop()

    return quotient, remainder

def check_poly_divisibility(coeffs_P, coeffs_Q, a, b):
    Q2 = poly_multiply(coeffs_Q, coeffs_Q)
    aQ = [a * c for c in coeffs_Q]
    Q2_plus_aQ_plus_1 = poly_add(poly_add(Q2, aQ), [1])

    _, rem1 = poly_divide(Q2_plus_aQ_plus_1, coeffs_P)
    if len(rem1) > 1 or abs(rem1[-1]) > 1e-9:
        return False

    P2 = poly_multiply(coeffs_P, coeffs_P)
    bP = [b * c for c in coeffs_P]
    P2_plus_bP_plus_1 = poly_add(poly_add(P2, bP), [1])

    _, rem2 = poly_divide(P2_plus_bP_plus_1, coeffs_Q)
    if len(rem2) > 1 or abs(rem2[-1]) > 1e-9:
        return False

    return True

