Problem: Find N(n) = maximum over all permutations of minimum swaps to make all triples non-monotone.
Then compute sum N(n) for n=10 to 20.

A triple (a, b, c) is monotone if a < b < c or a > b > c.
We need all consecutive triples to be non-monotone.

For small n, we can brute force to find N(n).
"""
from itertools import permutations

def is_monotone_triple(triple):
    """Check if a triple is monotone (increasing or decreasing)"""
    a, b, c = triple
    return (a < b < c) or (a > b > c)

def is_valid(perm):
    """Check if all consecutive triples are non-monotone"""
    for i in range(len(perm) - 2):
        if is_monotone_triple((perm[i], perm[i+1], perm[i+2])):
            return False
    return True

def min_swaps_to_valid(n, start_perm):
    """Find minimum swaps to reach a valid permutation from start_perm"""
    # BFS to find shortest path
    from collections import deque

    start = tuple(start_perm)
    target = None

    # First find a valid permutation
    for p in permutations(range(1, n+1)):
        if is_valid(p):
            target = p
            break

    if target is None:
        return float('inf')

    visited = {start}
    queue = deque([(start, 0)])

    while queue:
        current, dist = queue.popleft()

        if current == target:
            return dist

        # Try all possible swaps
        for i in range(len(current) - 1):
            new_list = list(current)
            new_list[i], new_list[i+1] = new_list[i+1], new_list[i]
            new_tuple = tuple(new_list)

            if new_tuple not in visited:
                visited.add(new_tuple)
                queue.append((new_tuple, dist + 1))

    return float('inf')

def N_bruteforce(n):
    """Find N(n) for small n by checking all permutations"""
    max_swaps = 0
    worst_perm = None

    for perm in permutations(range(1, n+1)):
        swaps = min_swaps_to_valid(n, list(perm))
        if swaps > max_swaps:
            max_swaps = swaps
            worst_perm = perm

    return max_swaps, worst_perm

