"""
Problem: Find smallest k such that any permutation of 1..n can be made non-monotone
in at most k adjacent swaps. A triple is non-monotone if it's not strictly increasing or decreasing.

Based on pattern analysis: N(n) = floor((n-1)/2)
"""

from itertools import permutations

def is_monotone_triple(triple):
    a, b, c = triple
    return (a < b < c) or (a > b > c)

def count_monotone_triples(seq):
    count = 0
    for i in range(len(seq) - 2):
        if is_monotone_triple((seq[i], seq[i+1], seq[i+2])):
            count += 1
    return count

def is_valid(seq):
    return count_monotone_triples(seq) == 0

def min_adjacent_swaps_to_valid(seq):
    start = tuple(seq)
    if is_valid(seq):
        return 0
    visited = {start}
    queue = [(start, 0)]
    while queue:
        current, dist = queue.pop(0)
        if is_valid(current):
            return dist
        for i in range(len(current) - 1):
            new_list = list(current)
            new_list[i], new_list[i+1] = new_list[i+1], new_list[i]
            new_tuple = tuple(new_list)
            if new_tuple not in visited:
                visited.add(new_tuple)
                queue.append((new_tuple, dist + 1))
    return float('inf')

def compute_N_brute(n):
    max_swaps = 0
    for perm in permutations(range(1, n + 1)):
        swaps = min_adjacent_swaps_to_valid(perm)
        if swaps > max_swaps:
            max_swaps = swaps
    return max_swaps

def compute_N_formula(n):
    return (n - 1) // 2

