"""
Find D(n) for more values to find the pattern.
"""

from itertools import product, combinations

def mex(values):
    s = set(values)
    i = 0
    while i in s:
        i += 1
    return i

def simulate(n, initial_values, edges):
    adj = {i: set() for i in range(n)}
    for i, j in edges:
        adj[i].add(j)
        adj[j].add(i)

    values = list(initial_values)
    day = 1

    for _ in range(200):
        new_values = []
        for i in range(n):
            neighbors = [values[j] for j in adj[i]]
            new_values.append(mex(neighbors))

        if new_values == values:
            return day

        values = new_values
        day += 1

    return -1

def find_max_days(n):
    """Find maximum days."""
    max_d = 0

    all_edges = list(combinations(range(n), 2))
    num_edges = len(all_edges)

    for edge_mask in range(1 << num_edges):
        edges = set()
        for i in range(num_edges):
            if edge_mask & (1 << i):
                edges.add(all_edges[i])

        best_for_edges = 0

        for initial in product(range(n + 3), repeat=n):
            d = simulate(n, list(initial), edges)
            if d > 0:
                best_for_edges = max(best_for_edges, d)

        max_d = max(max_d, best_for_edges)

    return max_d

# Compute for n=1 to 6
print("Computing D(n) for n=1 to 6...")
for n in range(1, 7):
    d = find_max_days(n)
    print(f"D({n}) = {d}")

