"""
Game theory problem:
- N pebbles, Alice starts
- Operation A: pick 1, 2, or 3 pebbles (unlimited)
- Operation B: pick 4 pebbles (at most 5 times per player)
- Last player to take wins

We need to count N in 1..2025 where Alice wins.
"""

from functools import lru_cache

def solve():
    # State: (n, alice_b_left, bob_b_left, turn)

    @lru_cache(maxsize=None)
    def can_win(n, alice_b_left, bob_b_left, turn):
        # Operation A: pick 1, 2, or 3 pebbles (unlimited)
        for pick in [1, 2, 3]:
            if n - pick >= 0:
                if n - pick == 0:
                    return True
                new_turn = 1 - turn
                if not can_win(n - pick, alice_b_left, bob_b_left, new_turn):
                    return True

        # Operation B: pick 4 pebbles
        if n - 4 >= 0:
            if turn == 0 and alice_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left - 1, bob_b_left, 1):
                    return True
            elif turn == 1 and bob_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left, bob_b_left - 1, 0):
                    return True

        return False

    # Check pattern for larger N to see when it stabilizes
    print("N=101..200:")
    losing = []
    for n in range(101, 201):
        result = can_win(n, 5, 5, 0)
        if not result:
            losing.append(n)
    print(f"Losing positions in 101..200: {losing}")

    # Check if losing positions follow pattern n ≡ 1 (mod 4)
    print("\nChecking mod 4 pattern for losing positions:")
    for n in losing:
        print(f"N={n}: n mod 4 = {n % 4}")

    # Count winning positions for n in 1..2025
    count = 0
    for n in range(1, 2026):
        if can_win(n, 5, 5, 0):
            count += 1

    return count

