"""
Alice and Bob game on a connected graph with 2n vertices.
Answer: n^2 (from complete bipartite graph K_{n,n})
"""

def simulate_game(n, edges):
    """
    Simulate the game to verify Alice can evade on K_{n,n}.
    Returns True if Alice can evade indefinitely (for small simulations).
    """
    num_vertices = 2 * n

    # Build adjacency list
    adj = {i: set() for i in range(num_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check if graph is bipartite
    color = {}
    try:
        for start in range(num_vertices):
            if start not in color:
                color[start] = 0
                stack = [start]
                while stack:
                    v = stack.pop()
                    for neighbor in adj[v]:
                        if neighbor not in color:
                            color[neighbor] = 1 - color[v]
                            stack.append(neighbor)
                        elif color[neighbor] == color[v]:
                            return False  # Not bipartite
        return True  # Bipartite
    except:
        return False

def count_edges(n):
    """Maximum edges for bipartite graph with 2n vertices."""
    return n * n

if __name__ == "__main__":
    # Verify K_{n,n} is bipartite and has n^2 edges
    for n in [2, 3, 4]:
        max_edges = count_edges(n)
        is_bipartite = simulate_game(n, [(i, j) for i in range(n) for j in range(n, 2*n)])
        print(f"n={n}: {max_edges} edges, bipartite={is_bipartite}")

    print("\nANSWER: n^2")

"""
Cop and Robber game: Alice chooses starting positions, Bob plays optimally.
"""

def can_alice_evade(n, edges):
    """Check if Alice can evade on a graph with 2n vertices."""
    num_vertices = 2 * n

    adj = {i: set() for i in range(num_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for a_start in range(num_vertices):
        for b_start in range(num_vertices):
