from itertools import combinations

def has_perfect_matching_bipartite(n, edges):
    """Check if bipartite graph has a perfect matching using Hall's condition."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)

    for r in range(n + 1):
        for S in combinations(range(n), r):
            neighbors = set()
            for s in S:
                neighbors.update(adj[s])
            if len(neighbors) < r:
                return False
    return True

def is_connected_bipartite(n, edges):
    """Check if the bipartite graph is connected."""
    adj = {i: set() for i in range(2*n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    visited = set()
    queue = [0]
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                queue.append(neighbor)

    return len(visited) == 2*n

