"""
Alice and Bob game on a connected graph with 2n vertices.

Key insight: On any bipartite graph, Alice can place A in one partition and B in the other.
After each full round, they end up in different partitions, so Bob can never catch Alice.

The maximum edges in a bipartite graph with 2n vertices is n^2 (complete bipartite K_{n,n}).
"""

import sympy

n = sympy.symbols('n')

def is_bipartite(num_vertices, edges):
    """Check if a graph is bipartite."""
    adj = {i: set() for i in range(num_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    color = {}
    for start in range(num_vertices):
        if start not in color:
            color[start] = 0
            stack = [start]
            while stack:
                v = stack.pop()
                for neighbor in adj[v]:
                    if neighbor not in color:
                        color[neighbor] = 1 - color[v]
                        stack.append(neighbor)
                    elif color[neighbor] == color[v]:
                        return False
    return True

def count_edges(n):
    """Maximum edges in bipartite graph with 2n vertices."""
    return n * n

if __name__ == "__main__":
    # Verify K_{n,n} is bipartite and has n^2 edges
    assert is_bipartite(4, [(i, j) for i in range(2) for j in range(2, 4)])  # K_{2,2}
    assert is_bipartite(6, [(i, j) for i in range(3) for j in range(3, 6)])  # K_{3,3}

    # Verify that adding an edge within a partition makes it non-bipartite
    # K_{2,2} plus edge (0, 1) within first partition
    assert not is_bipartite(4, [(i, j) for i in range(2) for j in range(2, 4)] + [(0, 1)])

    # Verify edge count
    assert count_edges(2) == 4
    assert count_edges(3) == 9
    assert count_edges(4) == 16

    # The answer is n^2
    result = count_edges(n)
    print(f"ANSWER: {result}")

