"""
Game theory problem: Alice and Bob on a connected graph with 2n vertices.
Alice chooses starting positions. Both play optimally.
Bob wants to catch Alice (same vertex). Alice wants to evade indefinitely.

Theorem: Alice can evade indefinitely iff the graph has no perfect matching.

For general connected graphs (not necessarily bipartite), find max edges without perfect matching.
"""

from itertools import combinations

def has_perfect_matching(n, edges):
    """Check if a graph has a perfect matching."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    matching = {}
    for start in range(n):
        if start not in matching:
            parent = {start: None}
            queue = [start]
            found = False
            while queue and not found:
                curr = queue.pop(0)
                for neighbor in adj[curr]:
                    if neighbor not in parent:
                        parent[neighbor] = curr
                        if neighbor not in matching:
                            path = []
                            node = neighbor
                            while parent[node] is not None:
                                path.append(node)
                                node = parent[node]
                            path.append(node)
                            for i in range(0, len(path), 2):
                                if path[i] in matching:
                                    del matching[path[i]]
                                if path[i+1] in matching:
                                    del matching[path[i+1]]
                                matching[path[i]] = path[i+1]
                            found = True
                            break
                        queue.append(neighbor)
            if not found:
                return False
    return True

def is_connected(n, edges):
    """Check if the graph is connected."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    visited = set()
    queue = [0]
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                queue.append(neighbor)
    return len(visited) == n

def max_edges_no_perfect_matching(n):
    """Find max edges in connected graph with no perfect matching."""
    all_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
    for k in range(len(all_edges), -1, -1):
        for edge_subset in combinations(all_edges, k):
            edges = set(edge_subset)
            if not has_perfect_matching(n, edges) and is_connected(n, edges):
                return k
    return 0

