"""
Game theory problem: Alice and Bob on a connected graph with 2n vertices.
Alice chooses starting positions. Both play optimally.
Bob wants to catch Alice (same vertex). Alice wants to evade indefinitely.

Theorem: Alice can evade indefinitely iff the graph has no perfect matching.

For general connected graphs on 2n vertices, find max edges without perfect matching.

Let me use a simpler matching algorithm.
"""

from itertools import combinations

def has_perfect_matching(n, edges):
    """Check if a graph has a perfect matching using brute force for small n."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Try all possible matchings
    def backtrack(match, used):
        if len(match) == n // 2:
            return True
        # Find first unused vertex
        start = None
        for i in range(n):
            if i not in used:
                start = i
                break
        if start is None:
            return True
        # Try to match start with any neighbor
        for neighbor in adj[start]:
            if neighbor not in used:
                used.add(start)
                used.add(neighbor)
                if backtrack(match | {(start, neighbor)}, used):
                    return True
                used.remove(start)
                used.remove(neighbor)
        return False

    return backtrack(set(), set())

def is_connected(n, edges):
    """Check if the graph is connected."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
