from itertools import combinations

def has_perfect_matching(num_vertices, edges):
    """Check if a graph has a perfect matching."""
    adj = {i: set() for i in range(num_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    def backtrack(match, used):
        if len(match) == num_vertices // 2:
            return True
        start = None
        for i in range(num_vertices):
            if i not in used:
                start = i
                break
        if start is None:
            return True
        for neighbor in adj[start]:
            if neighbor not in used:
                used.add(start)
                used.add(neighbor)
                if backtrack(match | {(start, neighbor)}, used):
                    return True
                used.remove(start)
                used.remove(neighbor)
        return False

    return backtrack(set(), set())

def is_connected(num_vertices, edges):
    """Check if the graph is connected."""
    adj = {i: set() for i in range(num_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    visited = set()
    queue = [0]
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                queue.append(neighbor)
    return len(visited) == num_vertices

