from itertools import combinations as comb

def has_perfect_matching(vertices, edges):
    """Check if graph has perfect matching."""
    n = vertices // 2
    adj = {i: set() for i in range(vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    existing_edges = list(edges)
    def can_match(start_idx, matched, edge_count):
        if edge_count == n:
            return True
        for i in range(start_idx, len(existing_edges)):
            u, v = existing_edges[i]
            if u not in matched and v not in matched:
                if can_match(i + 1, matched | {u, v}, edge_count + 1):
                    return True
        return False
    return can_match(0, set(), 0)

def max_edges_no_pm(n):
    """Find max edges for 2n vertices without perfect matching."""
    vertices = 2 * n
    all_possible = list(comb(range(vertices), 2))
    max_edges = 0
    for num_edges in range(len(all_possible) + 1):
        count = 0
        for edges in comb(all_possible, num_edges):
            if not has_perfect_matching(vertices, edges):
                count += 1
        if count > 0:
            max_edges = num_edges
        if num_edges >= max_edges + 5:
            break
    return max_edges

