        adj[u].add(v)
        adj[v].add(u)

    visited = set()
    queue = [0]
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                queue.append(neighbor)
    return len(visited) == 2*n

