"""
Edge coloring of K_n with 3 colors. Every triangle must be monochromatic or rainbow.
Find minimum max(n_X, n_Y, n_Z) for n=2025.
"""

n = 2025

def check_triangle_constraint(colors):
    """Check if coloring satisfies the constraint"""
    N = len(colors)
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                c1 = colors[(i,j)]
                c2 = colors[(j,k)]
                c3 = colors[(i,k)]
                # If two edges differ, third must be third color
                if c1 != c2:
                    if c3 not in (c1, c2):
                        return False
                if c2 != c3:
                    if c1 not in (c2, c3):
                        return False
                if c1 != c3:
                    if c2 not in (c1, c3):
                        return False
