"""

def check_structure(n1, n2, n3):
    n = n1 + n2 + n3

    def get_color(u, v):
        if u < n1:
            gu = 0
        elif u < n1 + n2:
            gu = 1
        else:
            gu = 2

        if v < n1:
            gv = 0
        elif v < n1 + n2:
            gv = 1
        else:
            gv = 2

        if gu == gv:
            return gu  # 0=X, 1=Y, 2=Z
        elif gu == 0 and gv == 1:
            return 2  # Z
        elif gu == 0 and gv == 2:
            return 1  # Y
        elif gu == 1 and gv == 2:
            return 0  # X
        else:
            return get_color(v, u)

    # Count colors
    colors = [0, 0, 0]
    for i in range(n):
        for j in range(i + 1, n):
            c = get_color(i, j)
            colors[c] += 1

    # Check constraint
    for A in range(n):
        for B in range(A + 1, n):
            for C in range(B + 1, n):
                AB = get_color(A, B)
                AC = get_color(A, C)
