from itertools import combinations, product

def is_valid_coloring(n, coloring):
    """Check if coloring satisfies the triangle property."""
    # coloring is a dict mapping (i,j) with i<j to color 0,1,2

    for triangle in combinations(range(n), 3):
        c1 = coloring[(min(triangle[0], triangle[1]), max(triangle[0], triangle[1]))]
        c2 = coloring[(min(triangle[0], triangle[2]), max(triangle[0], triangle[2]))]
        c3 = coloring[(min(triangle[1], triangle[2]), max(triangle[1], triangle[2]))]

        unique = set([c1, c2, c3])
        if len(unique) != 1 and len(unique) != 3:
            return False
    return True

def count_colors(coloring):
    counts = {0: 0, 1: 0, 2: 0}
    for c in coloring.values():
        counts[c] += 1
    return counts

def find_coloring(n):
    """Find a valid 3-coloring for K_n."""
    edges = list(combinations(range(n), 2))
    m = len(edges)

    # Try all possible colorings (3^m possibilities)
    # For small n only
    for colors in product(range(3), repeat=m):
        coloring = {edges[i]: colors[i] for i in range(m)}
        if is_valid_coloring(n, coloring):
            return coloring
    return None

