"""
Problem: n parallel lines, each with red and blue points.
Triangle conditions:
- 2 red vertices => blue point inside/on boundary (not vertex)
- 2 blue vertices => red point inside/on boundary (not vertex)
Find minimum n such that these guarantee infinitely many red and blue points.
"""

import itertools

def point_in_triangle(pt, a, b, c):
    """Check if pt is inside or on boundary of triangle abc (not a vertex)"""
    def sign(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

    d1 = sign(pt, a, b)
    d2 = sign(pt, b, c)
    d3 = sign(pt, c, a)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    is_vertex = (pt == a) or (pt == b) or (pt == c)

    return not (has_neg and has_pos) and not is_vertex

def check_config(points):
    """Check if configuration satisfies triangle conditions."""
    lines = {}
    for x, y, color in points:
        if y not in lines:
            lines[y] = []
        lines[y].append((x, color))

    for y, pts in lines.items():
        colors = set(p[1] for p in pts)
        if not ('R' in colors and 'B' in colors):
            return False, f"Line y={y} missing a color"

    ys = sorted(lines.keys())

    for i, y1 in enumerate(ys):
