import itertools

def point_in_triangle(pt, a, b, c):
    """Check if pt is inside or on boundary of triangle abc (not a vertex)"""
    # pt, a, b, c are tuples of (x, y, color)
    def sign(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

    d1 = sign(pt, a, b)
    d2 = sign(pt, b, c)
    d3 = sign(pt, c, a)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    is_vertex = (pt == a) or (pt == b) or (pt == c)

    return not (has_neg and has_pos) and not is_vertex

