def is_point_in_triangle(px, py, tx1, ty1, tx2, ty2, tx3, ty3):
    """Check if point (px, py) is inside or on boundary of triangle."""
    def sign(px, py, x1, y1, x2, y2):
        return (px - x1) * (y2 - y1) - (py - y1) * (x2 - x1)

    d1 = sign(px, py, tx1, ty1, tx2, ty2)
    d2 = sign(px, py, tx2, ty2, tx3, ty3)
    d3 = sign(px, py, tx3, ty3, tx1, ty1)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    return not (has_neg and has_pos)

def check_triangle_condition(points):
    """Check if the triangle condition is satisfied for 3 parallel lines."""
    # Group points by line
    points_by_line = {0: [], 1: [], 2: []}
    for x, y, color in points:
        points_by_line[x].append((y, color))

    # Generate all triangles (one point from each line)
    for y1, c1 in points_by_line[0]:
