                            break
                    if not found:
                        return False, f"Triangle {(y1,c1),(y2,c2),(y3,c3)} has 2R, no B inside"

                elif b_count == 2 and r_count == 1:
                    red_points = [(y, c) for x, y, c in points if c == 0 and (x, y, c) != (tx1, ty1, tc1) and (x, y, c) != (tx2, ty2, tc2) and (x, y, c) != (tx3, ty3, tc3)]
