    """Check if a, b, c form a non-degenerate triangle"""
    def sign(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

    return sign(a, b, c) != 0

