def check_compatible(p1, p2, n):
    """Check if primes p1, p2 are compatible on n consecutive queries."""
    # Build connected components of constraints
    visited = [False] * n
    components = 0

    for start in range(n):
        if visited[start]:
            continue
        components += 1
        stack = [start]
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            # Check edges (x, x+p1) and (x, x+p2)
            for shift in [p1, p2]:
                for other in [node + shift, node - shift]:
                    if 0 <= other < n and not visited[other]:
                        stack.append(other)

    return components >= 2

