def backtrack(n, idx, current, target_sum, min_val, max_val, counts):
    if idx == n:
        if sum(current) == target_sum:
            if check(current):
                return current
        return None

    remaining = n - idx
    current_sum = sum(current)
    needed = target_sum - current_sum
    min_remaining = min_val * remaining
    max_remaining = max_val * remaining

    if needed < min_remaining or needed > max_remaining:
        return None

    start = current[-1] if current else min_val
    for v in range(start, max_val + 1):
        new_counts = defaultdict(int)
        for k, cnt in counts.items():
            new_counts[k] = cnt
        new_counts[v] += 1

        # Prune: 15 must be able to be most frequent
        if new_counts[15] < new_counts[v]:
            continue

        new_current = current + [v]
        result = backtrack(n, idx + 1, new_current, target_sum, min_val, max_val, new_counts)
        if result:
            return result

    return None

