                # a*min + b*13 + c*15 + d*max = 8n
                # a*min + b*13 + c*15 + d*(min + 27) = 8n
                # (a + d)*min + b*13 + c*15 + 27*d = 8n
                # (a + d)*min = 8n - b*13 - c*15 - 27*d
                # min = (8n - b*13 - c*15 - 27*d) / (a + d)

