    #   So a elements are < 13, then b elements are 13, then c elements are 15, then e elements are large
    #   We need a <= n//2 and a + b > n//2 (so position n//2 falls in the 13s)

    for a in range(0, n):  # 0 to n-1 small elements
        for b in range(1, n - a + 1):  # at least one 13
