from itertools import combinations, product
from collections import defaultdict

def has_cycle(triples, m):
    """Check if graph of allowed transitions has a cycle."""
    # Build adjacency list for allowed transitions
    adj = defaultdict(set)
    for u in range(m):
        for v in range(m):
            for w in range(m):
                if (u, v, w) not in triples:
                    adj[(u, v)].add(w)

    # Check for cycles from each starting node
    for start in [(u, v) for u in range(m) for v in range(m)]:
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for w in adj[node]:
                next_node = (w, node[1])
                if next_node == node:
                    return True  # Self-loop
                if next_node in visited:
                    continue
                if next_node in adj:
                    stack.append(next_node)
    return False

def min_for_m(m):
    all_triples = list(product(range(m), repeat=3))
    n = len(all_triples)
    for k in range(n + 1):
        for combo in combinations(all_triples, k):
            if not has_cycle(set(combo), m):
                return k
    return -1

