def has_cycle_in_subset(triples_to_forbid, k):
    """Check if the graph of allowed transitions has a cycle."""
    adj = defaultdict(set)
    for u in range(k):
        for v in range(k):
            for w in range(k):
                if (u, v, w) not in triples_to_forbid:
                    adj[(u, v)].add(w)

    # Check for cycles using DFS from each node
    for start in [(u, v) for u in range(k) for v in range(k)]:
        visited = set()
        rec_stack = set()

        def dfs(node):
            visited.add(node)
            rec_stack.add(node)

            for w in adj[node]:
                next_node = (w, node[1])
                if next_node in rec_stack:
                    return True
                if next_node not in visited:
                    if dfs(next_node):
                        return True

            rec_stack.remove(node)
            return False

        if dfs(start):
            return True
    return False

