        best = []
        for seed in range(50000):
            shuffled = list(all_edges)
            import random
            random.seed(seed)
            random.shuffle(shuffled)

            kept = []
            for edge in shuffled:
                u, v = edge
                adj = {i: [] for i in range(num_vertices)}
                for eu, ev in kept:
                    adj[eu].append(ev)

                visited = set()
                queue = [v]
                can_reach = False
                while queue:
                    node = queue.pop(0)
                    if node == u:
                        can_reach = True
                        break
                    if node in visited:
                        continue
                    visited.add(node)
                    for neighbor in adj[node]:
                        queue.append(neighbor)

                if not can_reach:
                    kept.append(edge)

            if len(kept) > len(best):
                best = kept

        # Try to improve
        for edge in all_edges:
            if edge in best:
                continue
            test = best + [edge]
            if not has_cycle(test, num_vertices):
                best = test

        return len(best)

