import itertools

def build_graph(k):
    vertices = [(a, b) for a in range(k) for b in range(k)]
    vertex_to_idx = {v: i for i, v in enumerate(vertices)}

    edges = []
    for a in range(k):
        for b in range(k):
            for c in range(k):
                u = (a, b)
                v = (b, c)
                edges.append((vertex_to_idx[u], vertex_to_idx[v]))

    return len(vertices), edges

def has_cycle(edges, num_vertices):
    adj = {i: [] for i in range(num_vertices)}
    for u, v in edges:
        adj[u].append(v)

    color = [0] * num_vertices

    def dfs(node):
        color[node] = 1
        for neighbor in adj[node]:
            if color[neighbor] == 1:
                return True
            if color[neighbor] == 0 and dfs(neighbor):
                return True
        color[node] = 2
        return False

    for i in range(num_vertices):
        if color[i] == 0 and dfs(i):
            return True
    return False

