"""
Cool numbers - find even cool numbers.

Key insight: n is cool if there exists an arrangement of 1..n² such that for each d|n with 1<d<n,
each d×d block in the d-division has sum not divisible by d.

For d=2: We need (n/2)² blocks with odd sums.
- If n ≡ 2 (mod 4): (n/2)² is odd, sum of odd # of odds = odd.
  But total sum n²(n²+1)/2 is even for even n. CONTRADICTION.
- If n ≡ 0 (mod 4): (n/2)² is even, sum of even # of odds = even. ✓

So n must be ≡ 0 (mod 4) or n=2.

Now let's check specific values and try to construct arrangements.
"""

def check_arrangement(n, board):
    """Check if a given board arrangement works for all d|n with 1<d<n."""
    for d in range(2, n):
        if n % d == 0:
            # Check d-division
            for block_r in range(n // d):
                for block_c in range(n // d):
                    block_sum = 0
                    for dr in range(d):
                        for dc in range(d):
                            idx = (block_r * d + dr) * n + (block_c * d + dc)
                            block_sum += board[idx]
                    if block_sum % d == 0:
                        return False
    return True

def try_constructions(n):
    """Try various constructions to find a valid arrangement."""
    # Construction 1: Row-major (1,2,...,n²)
    board = list(range(1, n*n + 1))
    if check_arrangement(n, board):
        return True, "row"

    # Construction 2: Column-major
    board = [n*i + j + 1 for i in range(n) for j in range(n)]
    if check_arrangement(n, board):
        return True, "col"

    # Construction 3: Snake pattern
    board = []
    for i in range(n):
        for j in range(n):
            if i % 2 == 0:
                board.append(i*n + j + 1)
            else:
                board.append(i*n + (n-1-j) + 1)
    if check_arrangement(n, board):
        return True, "snake"

    # Construction 4: Block transposition
    # For n divisible by 2, swap rows in pairs
    board = list(range(1, n*n + 1))
    for i in range(0, n-1, 2):
        for j in range(n):
            board[i*n + j], board[(i+1)*n + j] = board[(i+1)*n + j], board[i*n + j]
    if check_arrangement(n, board):
        return True, "block_swap"

    return False, None

# Check even numbers divisible by 4
even_cool = []
n = 2
while len(even_cool) < 20:
    if n % 4 == 0:
        works, method = try_constructions(n)
