import random

def check_arrangement(n, board):
    """Check if arrangement works for all d|n with 1<d<n."""
    for d in range(2, n):
        if n % d == 0:
            for block_r in range(n // d):
                for block_c in range(n // d):
                    block_sum = 0
                    for dr in range(d):
                        for dc in range(d):
                            idx = (block_r * d + dr) * n + (block_c * d + dc)
                            block_sum += board[idx]
                    if block_sum % d == 0:
                        return False
    return True

def hill_climb(n, max_iter=500000):
    """Find valid arrangement using hill climbing."""
    # Start with row-major
    board = list(range(1, n*n + 1))

    divisors = [d for d in range(2, n) if n % d == 0]
    if not divisors:
        return True

    for iteration in range(max_iter):
        # Pick two random positions to swap
        i1, j1 = random.randint(0, n*n - 1), random.randint(0, n*n - 1)
        i2, j2 = random.randint(0, n*n - 1), random.randint(0, n*n - 1)
        if i1 == i2 and j1 == j2:
            continue

        # Swap
        board[i1], board[i2] = board[i2], board[i1]

        # Check
        if check_arrangement(n, board):
            return True

        # Revert
        board[i1], board[i2] = board[i2], board[i1]

    return False

