"""
Combinatorial game on subgroups of finite abelian group G.

Game: Start with T = {1}. Players alternate adding elements from G\T.
When adding g, T becomes <T ∪ {g}>, and all new elements are moved in.
Player who cannot move loses (normal play).

This is an impartial game. We can compute Grundy numbers (nimbers).
Key insight: The game ends when T = G.

For elementary abelian p-groups (Z_p)^n, this is equivalent to:
- Start with dimension 0, end with dimension n
- A move increases dimension by at least 1
- But we can jump by more than 1!

Let's analyze small cases systematically.
"""
import sympy as sp
from itertools import combinations, product

def group_elements(n, p):
    """Return elements of Z_p^n as tuples."""
    return list(product(range(p), repeat=n))

def subgroup_generated_by(generators, p, n):
    """Generate subgroup of Z_p^n from given generators."""
    elements = set()
    elements.add(tuple([0]*n))

    def add_and_multiply(g, mult):
        result = [0]*n
        for i in range(n):
            result[i] = (g[i] * mult) % p
        return tuple(result)

    # Add all linear combinations
    changed = True
    while changed:
        changed = False
        for g1 in generators:
            for g2 in list(elements):
                for c in range(1, p):
                    new_g = [(g1[i] * c + g2[i]) % p for i in range(n)]
                    new_g = tuple(new_g)
                    if new_g not in elements:
                        elements.add(new_g)
                        changed = True

    return elements

def all_subgroups_Zp_n(n, p):
    """Find all subgroups of Z_p^n."""
    elements = group_elements(n, p)
    subgroups = set()
    subgroups.add(frozenset([tuple([0]*n)]))

    # Try all possible generating sets
    for r in range(1, n+1):
        for gens in combinations(elements, r):
            H = subgroup_generated_by(gens, p, n)
            subgroups.add(frozenset(H))

    # Include the whole group
    subgroups.add(frozenset(elements))

    return sorted(subgroups, key=len)

def game_grundy(n, p):
    """Compute Grundy number for game on Z_p^n."""
    elements = group_elements(n, p)
    all_subgroups = all_subgroups_Zp_n(n, p)
    subgroup_dict = {frozenset(s): i for i, s in enumerate(all_subgroups)}

    # Memoization
    grundy_cache = {}

    def grundy_of(H):
        if H in grundy_cache:
            return grundy_cache[H]

        # Find all possible next states
        H_set = set(H)
        next_states = set()

        for g in elements:
            if g not in H_set:
                # Add g to generate new subgroup
                new_H = subgroup_generated_by(list(H) + [g], p, n)
                new_H_set = frozenset(new_H)
                next_states.add(new_H_set)

        # Compute mex
        if not next_states:
            result = 0
        else:
            mex = 0
            while mex in [grundy_of(s) for s in next_states]:
                mex += 1
            result = mex

        grundy_cache[H] = result
        return result

    # Start from trivial subgroup
    trivial = frozenset([tuple([0]*n)])
    return grundy_of(trivial)

def is_bob_wins(n, p):
    """Bob wins if Grundy number is 0."""
    return game_grundy(n, p) == 0

