    n = G[0]
    subgroups = {}
    for d in range(1, n+1):
        if n % d == 0:
            # Subgroup of order d is generated by n/d
            subgroup = tuple(range(0, d, d))
            subgroups[d] = set(subgroup)
    return subgroups

def subgroup_generated_by(elements, n):
