    # For cyclic group, subgroup is determined by gcd of elements with n
    import math
    g = n
    for x in elements:
        g = math.gcd(g, x)
    # Subgroup of order n/g, generated by g
    if g == 0:
        return set(range(n))
    order = n // g
    return set(range(0, n, g))

def game_length(G):
    """Compute game length for cyclic group G = Z/nZ"""
    n = G[0]

    @lru_cache(None)
    def solve(H):
        # H is frozenset of current subgroup elements
        if H == set(range(n)):
            return 0  # No moves possible

        # Find all valid moves
        moves = []
        for g in range(n):
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, n)
                moves.append(new_H)

        if not moves:
            return float('inf')

        # Min-max: we want to know if current player can force win
        # Actually for this game, all paths lead to same length?
        # Let's check if all moves lead to same remaining length

        lengths = []
        for new_H in moves:
