"""
Game on finite abelian groups:
- T starts with {1_G}
- Players alternate adding an element g not in T
- When g is added, all of <T ∪ {g}> \ T are added to T
- Last player to move wins (normal play)
- Find all G where Bob wins (second player)
"""
from functools import lru_cache

def generate_subgroup_cyclic(generators, order):
    """Generate subgroup of Z_n from given generators (integers)"""
    # Subgroup is generated by gcd of all generators with n
    g = 0
    for x in generators:
        g = gcd(g, x, order)
    return list(range(0, order, g))

def gcd(a, b, n):
    """Compute gcd of a and b modulo n"""
    a, b = a % n, b % n
    while b:
        a, b = b, a % b
    return a

def generate_subgroup_general(generators, order):
    """Generate subgroup from generators as tuples (for Z_n^k)"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % order for i in range(len(g)))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def get_new_elements_cyclic(current_T, new_element, order):
    """Return elements added when new_element is added to current_T (cyclic)"""
    new_T = current_T + [new_element]
    subgroup = generate_subgroup_cyclic(new_T, order)
    return [x for x in subgroup if x not in current_T]

def get_new_elements_general(current_T, new_element, order):
    """Return elements added when new_element is added to current_T (general)"""
    new_T = current_T + [new_element]
    subgroup = generate_subgroup_general(new_T, order)
    return [x for x in subgroup if x not in current_T]

def get_all_moves_cyclic(T, order):
    """Get all possible moves from state T (cyclic)"""
    return [x for x in range(order) if x not in T]

def get_all_moves_general(T, order):
    """Get all possible moves from state T (general)"""
    all_elements = set()
    for g in T:
        for i in range(len(g)):
            all_elements.add(g[i])
    all_elements = set(range(order))
    current = set(T)
    return [x for x in all_elements if x not in current]

def solve_game_cyclic(order):
    """Solve the game for cyclic group Z_order"""
    memo = {}

    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]

        possible_moves = get_all_moves_cyclic(T, order)

        if not possible_moves:
            memo[T_tuple] = False
            return False

        for move in possible_moves:
            new_T = T + get_new_elements_cyclic(T, move, order)
            if not solve(new_T):
                memo[T_tuple] = True
                return True

        memo[T_tuple] = False
        return False

    return solve([0])

def solve_game_general(order, generators):
    """Solve the game for Z_n^k where generators define the group structure"""
    memo = {}

    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]

        possible_moves = get_all_moves_general(T, order)

        if not possible_moves:
            memo[T_tuple] = False
            return False

        for move in possible_moves:
            new_T = T + get_new_elements_general(T, move, order)
            if not solve(new_T):
                memo[T_tuple] = True
                return True

        memo[T_tuple] = False
        return False

    return solve([tuple([0]*len(generators))])

