"""
Game on finite abelian groups - using Grundy numbers (Nim-values).
For an impartial game, position is losing iff Grundy number = 0.
Grundy(G) = mex({Grundy(next state) for all possible moves})
"""

from itertools import combinations, product
from functools import lru_cache

def solve_elementary_abelian(n, p):
    """
    Solve game for elementary abelian p-group Z_p^n.
    Returns True if Alice wins (Grundy != 0), False if Bob wins (Grundy == 0).
    """
    all_elements = list(product(range(p), repeat=n))
    identity = tuple([0] * n)

    def generate_subgroup(generators):
        """Generate subgroup from given generators"""
        subgroup = {identity}
        queue = [identity]
        changed = True

        while changed:
            changed = False
            for gen in generators:
                for base in list(subgroup):
                    for mult in range(p):
                        new_elem = tuple((base[i] + gen[i] * mult) % p for i in range(n))
                        if new_elem not in subgroup:
                            subgroup.add(new_elem)
                            queue.append(new_elem)
                            changed = True
        return subgroup

    @lru_cache(maxsize=None)
    def grundy(H_tuple):
        H = set(H_tuple)
        next_grundies = []

        for g in all_elements:
            if g not in H:
                new_H = generate_subgroup(list(H) + [g])
                next_grundies.append(grundy(frozenset(new_H)))

        if not next_grundies:
            return 0

        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial = frozenset([identity])
    grundy_val = grundy(trivial)
    return grundy_val != 0  # Alice wins if Grundy != 0

def solve_cyclic(n):
    """Solve for cyclic group Z_n"""
    all_elements = list(range(n))
    identity = 0

    def generate_subgroup(generators):
        g = 0
        for x in generators:
            g = gcd(g, x)
        return list(range(0, n, g))

    def get_new_elements(T, new_elem):
        new_T = T + [new_elem]
        subgroup = generate_subgroup(new_T)
        return [x for x in subgroup if x not in T]

    @lru_cache(maxsize=None)
    def grundy(T_tuple):
        T = set(T_tuple)
        next_grundies = []

        for g in all_elements:
            if g not in T:
                new_T = T + get_new_elements(T, g)
                next_grundies.append(grundy(tuple(sorted(new_T))))

        if not next_grundies:
            return 0

        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    grundy_val = grundy(tuple([identity]))
    return grundy_val != 0

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

