    memo = {}
    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]
        possible_moves = get_all_moves_cyclic(T, order)
        if not possible_moves:
            memo[T_tuple] = False
            return False
        for move in possible_moves:
            new_T = T + get_new_elements_cyclic(T, move, order)
            if not solve(new_T):
                memo[T_tuple] = True
                return True
        memo[T_tuple] = False
        return False
    return solve([0])

