# Actually, let me use a different approach for generating groups
def get_prime_power_factorization(n):
    """Get prime power factorization of n"""
    result = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            result[d] = result.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        result[n] = result.get(n, 0) + 1
    return result

def generate_groups_by_factorization(max_order):
    """Generate abelian groups by their invariant factors"""
    groups = []

    # For each order, get prime factorization
    for order in range(2, max_order + 1):
        fac = get_prime_power_factorization(order)

        # For each prime p with exponent e, there are p^e possible cyclic factors
        # Groupings: e.g., p^e can be (p^e) or (p^(e-1), p) or (p^(e-2), p^2), etc.
        # This is partitions of e

        def partitions(n, min_val=1):
            """Generate partitions of n"""
            if n == 0:
                yield []
                return
            for i in range(min_val, n + 1):
                for rest in partitions(n - i, i):
                    yield [i] + rest

        # Combine partitions for each prime
        prime_partitions = []
        for p, e in sorted(fac.items()):
            prime_partitions.append([(p**exp) for exp in part] for part in partitions(e))

        # Cartesian product of partitions
        import itertools
        for combo in itertools.product(*prime_partitions):
            # Combine all cyclic factors
            factors = []
            for p_factors in combo:
                for pf in p_factors:
                    factors.append(pf)
            groups.append(tuple(sorted(factors)))

    return groups

