        queue = [identity]
        changed = True
        while changed:
            changed = False
            for gen in generators:
                for base in list(subgroup):
                    for mult in range(p):
                        new_elem = tuple((base[i] + gen[i] * mult) % p for i in range(n))
                        if new_elem not in subgroup:
                            subgroup.add(new_elem)
                            queue.append(new_elem)
                            changed = True
        return subgroup

    @lru_cache(maxsize=None)
    def grundy(H_tuple):
        H = set(H_tuple)
        next_grundies = []

        for g in all_elements:
            if g not in H:
                new_H = generate_subgroup(list(H) + [g])
                next_grundies.append(grundy(frozenset(new_H)))

        if not next_grundies:
            return 0

        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial = frozenset([identity])
    grundy_val = grundy(trivial)
    return grundy_val != 0

def solve_cyclic(n):
    """Solve for cyclic group Z_n using direct game solving."""
    all_elements = list(range(n))
    identity = 0

    def generate_subgroup(generators):
        g = 0
        for x in generators:
            g = gcd(g, x)
        return list(range(0, n, g))

    def get_new_elements(T, new_elem):
        new_T = list(T) + [new_elem]
        subgroup = generate_subgroup(new_T)
        return [x for x in subgroup if x not in T]

    memo = {}

    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]

        next_grundies = []
        for g in all_elements:
            if g not in T:
                new_T = T + get_new_elements(T, g)
                next_grundies.append(solve(new_T))

        if not next_grundies:
            memo[T_tuple] = False  # Current player loses
            return False

        mex = 0
        while mex in next_grundies:
            mex += 1
        memo[T_tuple] = mex != 0  # Current player wins iff mex != 0
        return mex != 0

    grundy_val = solve([identity])
    return grundy_val

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

