"""
Game on finite abelian groups - Sprague-Grundy analysis.
Bob wins iff Grundy value of starting position is 0.
"""
from functools import lru_cache
from math import gcd

def generate_subgroup_cyclic(generators, order):
    """Generate subgroup of Z_n from generators"""
    d = order
    for g in generators:
        d = gcd(d, g)
    return set(range(0, order, d))

def generate_subgroup_general(generators, order):
    """Generate subgroup of Z_order^k from tuple generators"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % order for i in range(len(g)))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def get_next_subgroups_cyclic(order, current_subgroup):
    """Get all possible next subgroups from current subgroup"""
    # Current subgroup H, we can pick any g not in H
    # New subgroup is <H ∪ {g}>
    H = list(current_subgroup)
    next_subs = set()
    for g in range(order):
        if g not in H:
            new_sub = generate_subgroup_cyclic(H + [g], order)
            next_subs.add(frozenset(new_sub))
    return next_subs

def get_next_subgroups_general(order, dim, current_subgroup):
    """Get all possible next subgroups from current subgroup"""
    H = list(current_subgroup)
    next_subs = set()
    for g in range(order):
        if g not in current_subgroup:
            # g is an integer, need to interpret it properly
            # For Z_n^k, element g means we add (g, 0, ..., 0)
            new_gen = tuple([g] + [0]*(dim-1))
            new_sub = generate_subgroup_general(H + [new_gen], order)
            next_subs.add(frozenset(new_sub))
    return next_subs

def compute_grundy_cyclic(order):
    """Compute Grundy value for Z_order starting from {0}"""
    # All subgroups by their generator d (subgroup = {0, d, 2d, ...})
    divisors = sorted([d for d in range(1, order+1) if order % d == 0], reverse=True)
    subgroups = [frozenset(range(0, order, d)) for d in divisors]
    sub_dict = {subgroups[i]: i for i in range(len(subgroups))}

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = subgroups[idx]
        next_grundies = []
        for g in range(order):
            if g not in H:
                d = order
                for h in H:
                    d = gcd(d, h)
                d = gcd(d, g)
                new_H = frozenset(range(0, order, d))
                next_grundies.append(grundy(sub_dict[new_H]))
        if not next_grundies:
            return 0
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial_idx = sub_dict[frozenset([0])]
    return grundy(trivial_idx)

def compute_grundy_general(order, dim):
    """Compute Grundy for Z_order^dim starting from {(0,...,0)}"""
    # All subgroups
    all_subs = []
    seen = set()

    def collect_subgroups(current_sub):
        current_sub = frozenset(current_sub)
        if current_sub in seen:
            return
        seen.add(current_sub)
        all_subs.append(current_sub)
        next_subs = get_next_subgroups_general(order, dim, current_sub)
        for next_sub in next_subs:
            collect_subgroups(list(next_sub))

    collect_subgroups([tuple([0]*dim)])

    sub_dict = {s: i for i, s in enumerate(all_subs)}

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = all_subs[idx]
        next_grundies = []
        for g in range(order):
            if g not in H:
                new_gen = tuple([g] + [0]*(dim-1))
                new_sub = frozenset(generate_subgroup_general(list(H) + [new_gen], order))
                next_grundies.append(grundy(sub_dict[new_sub]))
        if not next_grundies:
            return 0
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial_idx = sub_dict[frozenset([tuple([0]*dim)])]
    return grundy(trivial_idx)

def main():
    print("Cyclic groups:")
    for n in range(1, 13):
        g = compute_grundy_cyclic(n)
        winner = "Bob" if g == 0 else "Alice"
        print(f"Z_{n}: Grundy={g}, {winner} wins")

    print("\nZ_2 x Z_2:")
    g = compute_grundy_general(2, 2)
    print(f"Grundy={g}, {'Bob' if g == 0 else 'Alice'} wins")

    print("\nZ_2 x Z_3:")
    g = compute_grundy_general(6, 2)
    print(f"Grundy={g}, {'Bob' if g == 0 else 'Alice'} wins")

    print("\nZ_2 x Z_4:")
    g = compute_grundy_general(4, 2)
    print(f"Grundy={g}, {'Bob' if g == 0 else 'Alice'} wins")

    print("\nZ_3 x Z_3:")
    g = compute_grundy_general(3, 2)
    print(f"Grundy={g}, {'Bob' if g == 0 else 'Alice'} wins")

if __name__ == "__main__":
    main()

"""
Find all abelian groups where Bob wins.
Pattern: For elementary abelian p-groups C_p^r, Bob wins iff r is even.
For general abelian groups, need to analyze by primary decomposition.
"""

from functools import lru_cache
import math
from collections import deque

def group_to_list(G):
    elements = [tuple()]
    for n in G:
        new_elements = []
        for e in elements:
            for i in range(n):
                new_elements.append(e + (i,))
        elements = new_elements
    return elements

def element_add(a, b):
    return tuple((x + y) % n for x, y, n in zip(a, b, G))

def subgroup_generated_by(elements, G):
    G_list = group_to_list(G)
    visited = set()
    queue = deque()

    zero = tuple(0 for _ in G)
    visited.add(zero)
    queue.append(zero)

    for e in elements:
        visited.add(e)
        queue.append(e)

    while queue:
        curr = queue.popleft()
        for gen in elements:
            for k in range(1, G[0] + 1):
                new_elem = tuple((k * g) % n for g, n in zip(gen, G))
                if new_elem not in visited:
                    visited.add(new_elem)
                    queue.append(new_elem)

            new_elem = element_add(curr, gen)
            if new_elem not in visited:
                visited.add(new_elem)
                queue.append(new_elem)

    return frozenset(visited)

def game_length(G):
    G_list = group_to_list(G)
    zero = tuple(0 for _ in G)
    full = frozenset(G_list)

    @lru_cache(None)
    def grundy(H):
        if H == full:
            return 0

        next_states = []
        for g in G_list:
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, G)
                next_states.append(grundy(new_H))

        if not next_states:
            return 0

        seen = set(next_states)
        mex = 0
        while mex in seen:
            mex += 1
        return mex

    return grundy(frozenset({zero}))

