from functools import lru_cache
from math import gcd

def generate_subgroup_cyclic(generators, order):
    """Generate subgroup of Z_n from generators"""
    d = order
    for g in generators:
        d = gcd(d, g)
    return set(range(0, order, d))

def generate_subgroup_general(generators, order):
    """Generate subgroup of Z_order^k from tuple generators"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % order for i in range(len(g)))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def compute_grundy_cyclic(order):
    """Compute Grundy value for Z_order starting from {0}"""
    divisors = sorted([d for d in range(1, order+1) if order % d == 0], reverse=True)
    subgroups = [frozenset(range(0, order, d)) for d in divisors]
    sub_dict = {subgroups[i]: i for i in range(len(subgroups))}

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = subgroups[idx]
        next_grundies = []
        for g in range(order):
            if g not in H:
                d = order
                for h in H:
                    d = gcd(d, h)
                d = gcd(d, g)
                new_H = frozenset(range(0, order, d))
                next_grundies.append(grundy(sub_dict[new_H]))
        if not next_grundies:
            return 0
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial_idx = sub_dict[frozenset([0])]
    return grundy(trivial_idx)

def compute_grundy_general(order, dim):
    """Compute Grundy for Z_order^dim starting from {(0,...,0)}"""
    # Enumerate all subgroups by BFS from trivial
    subgroups = []
    seen = set()

    def bfs(start):
        queue = [start]
        while queue:
            current = queue.pop(0)
            current_frozen = frozenset(current)
            if current_frozen in seen:
                continue
            seen.add(current_frozen)
            subgroups.append(current_frozen)
            next_subs = get_next_subgroups(order, dim, current_frozen)
            for next_sub in next_subs:
                if next_sub not in seen:
                    queue.append(list(next_sub))

    bfs([tuple([0]*dim)])

    sub_dict = {s: i for i, s in enumerate(subgroups)}

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = subgroups[idx]
        next_grundies = []
        for g in range(order):
            if g not in H:
                new_gen = tuple([g] + [0]*(dim-1))
                new_sub = frozenset(generate_subgroup_general(list(H) + [new_gen], order))
                next_grundies.append(grundy(sub_dict[new_sub]))
        if not next_grundies:
            return 0
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    trivial_idx = sub_dict[frozenset([tuple([0]*dim)])]
    return grundy(trivial_idx)

def get_next_subgroups(order, dim, current_sub):
    """Get all next subgroups from current subgroup"""
    next_subs = set()
    for g in range(order):
        if g not in current_sub:
            new_gen = tuple([g] + [0]*(dim-1))
            new_sub = frozenset(generate_subgroup_general(list(current_sub) + [new_gen], order))
            next_subs.add(new_sub)
