def solve_group(all_elements, identity, group_add):
    """Solve the game for a group given its elements and addition operation."""
    n = len(all_elements)

    def gen_sub(gens):
        """Generate subgroup from generators"""
        sub = {identity}
        q = [identity]
        changed = True
        while changed:
            changed = False
            for g in gens:
                for b in list(sub):
                    for m in range(2):  # For Z_2^k, coefficients are 0 or 1
                        ne = group_add(b, g * m)
                        if ne not in sub:
                            sub.add(ne)
                            q.append(ne)
                            changed = True
        return sub

    @lru_cache(maxsize=None)
    def solve(H):
        H = frozenset(H)
        next_g = []
        for g in all_elements:
            if g not in H:
                new_H = gen_sub(list(H) + [g])
                next_g.append(solve(new_H))

        if not next_g:
            return False  # Current player loses
        mex = 0
        while mex in next_g:
            mex += 1
        return mex != 0  # Current player wins iff mex != 0

    return solve({identity})

def test_z2k(k):
    """Test Z_2^k"""
    n, p = k, 2
    all_elements = list(product(range(p), repeat=n))
    identity = tuple([0] * n)

    def add(a, b):
        return tuple((a[i] + b[i]) % p for i in range(n))

    alice_wins = solve_group(all_elements, identity, add)
    print(f"Z_2^{k} (order {2**k}): Alice={alice_wins}, Bob={not alice_wins}")
    return alice_wins

def test_zpk(k, p):
    """Test Z_{p^k}"""
    n = p**k
    all_elements = list(range(n))
    identity = 0

    def add(a, b):
        return (a + b) % n

    # This is cyclic, use different approach
    memo = {}

    def gen_sub(gens):
        g = 0
        for x in gens:
            g = gcd(g, x)
        return list(range(0, n, g))

    def get_new(T, new_elem):
        new_T = list(T) + [new_elem]
        sub = gen_sub(new_T)
        return [x for x in sub if x not in T]

    @lru_cache(maxsize=None)
    def solve(T):
        T = tuple(sorted(T))
        if T in memo:
            return memo[T]

        next_g = []
        for g in all_elements:
            if g not in T:
                new_T = T + get_new(T, g)
                next_g.append(solve(tuple(sorted(new_T))))

        if not next_g:
            memo[T] = False
            return False
        mex = 0
        while mex in next_g:
            mex += 1
        memo[T] = mex != 0
        return mex != 0

    alice_wins = solve([identity])
    print(f"Z_{p**k}: Alice={alice_wins}, Bob={not alice_wins}")
    return alice_wins

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

