def solve_group(all_elements, identity, group_add):
    """Solve the game for a group given its elements and addition operation."""
    n = len(all_elements)

    def gen_sub(gens):
        """Generate subgroup from generators"""
        sub = {identity}
        q = [identity]
        changed = True
        while changed:
            changed = False
            for g in gens:
                for b in list(sub):
                    for m in range(2):  # For Z_2^k, coefficients are 0 or 1
                        ne = group_add(b, g * m)
                        if ne not in sub:
                            sub.add(ne)
                            q.append(ne)
                            changed = True
        return sub

    @lru_cache(maxsize=None)
    def solve(H_tuple):
        H = set(H_tuple)
        next_g = []
        for g in all_elements:
            if g not in H:
                new_H = gen_sub(list(H) + [g])
                next_g.append(solve(frozenset(new_H)))

        if not next_g:
            return False  # Current player loses
        mex = 0
        while mex in next_g:
            mex += 1
        return mex != 0  # Current player wins iff mex != 0

    return solve(frozenset([identity]))

