"""
Game: Add elements to box T, when adding g, T becomes <T U {g}>.
Last player to move wins. Find G where Bob wins.

Hypothesis: Bob wins iff G is elementary abelian p-group Z_p^n with n even.
This means |G| = p^n where n is even, i.e., |G| = (p^(n/2))^2.

So Bob wins for orders that are squares of prime powers: 2^2, 3^2, 2^4, 5^2, 7^2, 2^6, 3^4, ...

Let me verify this pattern and compute the sum.
"""
from itertools import combinations, product
from functools import lru_cache

def compute_grundy_elementary(n, p):
    """Compute Grundy for Z_p^n."""
    all_elements = list(product(range(p), repeat=n))
    identity = tuple([0] * n)

    def generate_subgroup(generators):
        subgroup = {identity}
        queue = [identity]
        changed = True
        while changed:
            changed = False
            for gen in generators:
                for base in list(subgroup):
                    for mult in range(p):
                        new_elem = tuple((base[i] + gen[i] * mult) % p for i in range(n))
                        if new_elem not in subgroup:
                            subgroup.add(new_elem)
                            queue.append(new_elem)
                            changed = True
        return subgroup

    all_subgroups = set()
    all_subgroups.add(frozenset([identity]))
    for r in range(1, n + 1):
        for gens in combinations(all_elements, r):
            all_subgroups.add(frozenset(generate_subgroup(list(gens))))

    subgroups = sorted(all_subgroups, key=len)
    subgroup_dict = {frozenset(s): i for i, s in enumerate(subgroups)}

    @lru_cache(maxsize=None)
    def grundy(idx):
        H = subgroups[idx]
        next_grundies = []
        for g in all_elements:
            if g not in H:
                new_H = generate_subgroup(list(H) + [g])
                next_grundies.append(grundy(subgroup_dict[frozenset(new_H)]))
        if not next_grundies:
            return 0
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    return grundy(subgroup_dict[frozenset([identity])])

