def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_powers_squares(limit=10000):
    """Generate p^(2k) for primes p and k >= 1, sorted."""
    results = []
    for p in range(2, limit + 1):
        if not is_prime(p):
            continue
        k = 1
        while True:
            val = p ** (2 * k)
            if val > limit:
                break
            results.append(val)
            k += 1
    results.sort()
    return results

