"""
Find all sizes |G| where Bob has a winning strategy.

Based on analysis:
- Cyclic groups Z_n (n > 1): Alice wins (any non-zero element generates everything)
- Direct products Z_d^m where m is even: Bob wins
- Other structures: Alice wins

So Bob wins for G ≅ Z_d^m where m is even (2, 4, 6, ...)
Sizes = d^m for m even.

But d^m = (d^(m/2))^2, so all such sizes are perfect squares!
d^2, (d^3)^2, (d^5)^2, etc. are all covered by just d^2.

The smallest sizes where Bob wins are: 2^2, 3^2, 4^2, 5^2, 6^2, ...
= 4, 9, 16, 25, 36, 49, 64, 81, 100, 121, ...

Sum of 10 smallest = 4+9+16+25+36+49+64+81+100+121 = 505

Let me verify with more tests first.
"""

from functools import lru_cache
from itertools import product

def generate_subgroup(G, elements):
    if not elements:
        return {G.identity}

    subgroup = {G.identity}
    changed = True
    while changed:
        changed = False
        for a in list(subgroup):
            for b in list(elements):
                new_elem = G.add(a, b)
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
        for a in list(subgroup):
            for b in list(elements):
                new_elem = G.add(G.invert(a), b)
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
    return subgroup

def make_group(name, elements, add_func, invert_func):
    class Group:
        def __init__(self):
            self.name = name
            self.elements = elements
            self.identity = elements[0]
            self.add = add_func
            self.invert = invert_func
        def __repr__(self):
            return self.name
        def __len__(self):
            return len(self.elements)
    return Group()

def analyze_game(G):
    elements = list(G.elements)
    identity = G.identity
    n = len(elements)

    memo = {}

    def can_win(state):
        state_frozen = frozenset(state)
        if state_frozen in memo:
            return memo[state_frozen]

        remaining = set(elements) - state
        if not remaining:
            memo[state_frozen] = False
            return False

        for g in remaining:
            new_state = generate_subgroup(G, list(state) + [g])
            if not can_win(new_state):
                memo[state_frozen] = True
                return True

        memo[state_frozen] = False
        return False

    alice_wins = can_win({identity})
    return alice_wins

def create_direct_product(*groups):
    all_elements = [g.elements for g in groups]
    elements = list(product(*all_elements))
    moduli = [len(g.elements) for g in groups]

    def add(a, b):
        return tuple((x + y) % m for x, y, m in zip(a, b, moduli))

    def invert(a):
        return tuple((-x) % m for x, m in zip(a, moduli))

    name = " × ".join([g.name for g in groups])
    return make_group(name, elements, add, invert)

def test_zn(n):
    elements = list(range(n))
    def add(a, b): return (a + b) % n
    def inv(a): return (-a) % n
