def generate_subgroup_Zn(elements, n):
    """Generate subgroup of Z_n given a set of elements"""
    if not elements:
        return {0}
    g = 0
    for x in elements:
        g = gcd(g, x)
    return set(range(0, n, g))

def solve_cyclic(n):
    """Solve game for Z_n. Returns True if Alice (first player) wins."""
    if n == 1:
        return False

    @lru_cache(maxsize=None)
    def can_win(state_tuple):
        state = set(state_tuple)
        if len(state) == n:
            return False

        for g in range(n):
            if g not in state:
                new_state = generate_subgroup_Zn(state | {g}, n)
                if not can_win(tuple(sorted(new_state))):
                    return True
        return False

    return can_win((0,))

