# Generate all abelian groups of order up to 100
# An abelian group is determined by its invariant factors
# We'll enumerate partitions of prime powers

def get_abelian_groups(n):
    """Generate all abelian groups of order n as lists of invariant factors"""
    groups = []

    # Find prime factorization
    factors = {}
    temp = n
    p = 2
    while p * p <= temp:
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p
        p += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # For each prime power p^k, enumerate partitions of k
    def prime_partitions(k, max_part):
        if k == 0:
            yield []
            return
        for i in range(min(k, max_part), 0, -1):
            for rest in prime_partitions(k - i, i):
                yield [i] + rest

    def generate_groups(factors, idx, current):
        if idx == len(factors):
            groups.append(tuple(current))
            return

