Hypothesis: Bob wins for G iff G has even "rank" in some sense.
- For Z_n (cyclic): rank 1, Alice wins
- For Z_n × Z_n: rank 2, Bob wins
- For F_p^r: rank r, Bob wins iff r even

Let's test Z_2 × Z_4 (order 8, rank 2, not Z_n × Z_n).
"""

from math import gcd
from functools import lru_cache

def generate_subgroups_Z_nZ_m(n, m):
    """Generate all subgroups of Z_n × Z_m."""
    G = [(a, b) for a in range(n) for b in range(m)]

    subgroups = []

    # For small groups, enumerate all subsets and check subgroup property
    from itertools import combinations

    def is_subgroup(subset):
        S = set(subset)
        if (0, 0) not in S:
            return False
        for a in S:
            if (-a[0] % n, -a[1] % m) not in S:
                return False
        for a in S:
            for b in S:
                if ((a[0] + b[0]) % n, (a[1] + b[1]) % m) not in S:
                    return False
        return True

    for r in range(len(G) + 1):
        for subset in combinations(G, r):
            if is_subgroup(list(subset)):
                subgroups.append(frozenset(subset))

    return subgroups

def solve_game_Z_nZ_m(n, m):
    """Solve game on Z_n × Z_m using minimax."""
    subgroups = generate_subgroups_Z_nZ_m(n, m)
    sub_dict = {s: i for i, s in enumerate(subgroups)}

    @lru_cache(maxsize=None)
    def can_first_player_win(idx):
        H = subgroups[idx]
        if H == set(((a, b) for a in range(n) for b in range(m))):
            return False  # No moves

        # Try all possible moves
        for g in ((a, b) for a in range(n) for b in range(m)):
            if g not in H:
                # Generate <H U {g}>
                # This is the subgroup generated by all elements in H plus g
                # For efficiency, use the fact that <H, g> = H + <g> + cross terms
                # Actually, just compute by BFS

                new_elements = set(H)
                new_elements.add(g)

                # Close under addition
                changed = True
                while changed:
                    changed = False
                    for x in list(new_elements):
                        for y in list(new_elements):
                            new_x = ((x[0] + y[0]) % n, (x[1] + y[1]) % m)
                            if new_x not in new_elements:
                                new_elements.add(new_x)
                                changed = True

                new_H = frozenset(new_elements)
                if new_H in sub_dict:
                    if not can_first_player_win(sub_dict[new_H]):
                        return True

        return False

    trivial = frozenset({(0, 0)})
    if trivial in sub_dict:
        return not can_first_player_win(sub_dict[trivial])  # Bob wins if Alice cannot
    return False

