    # Actually, need full vector space
    from itertools import product
    G = list(product(range(p), repeat=r))

    subgroups = []

    def is_subgroup(subset):
        S = set(subset)
        if tuple([0]*r) not in S:
            return False
        for a in S:
            # Check inverse
            inv = tuple((-x % p) for x in a)
            if inv not in S:
                return False
        for a in S:
            for b in S:
                # Check closure
                new = tuple((a[i] + b[i]) % p for i in range(r))
                if new not in S:
                    return False
        return True

    # Enumerate all subsets
    from itertools import combinations
    for k in range(len(G) + 1):
        for subset in combinations(G, k):
            if is_subgroup(list(subset)):
                subgroups.append(frozenset(subset))

    return subgroups

def solve_game_elementary_abelian(p, r):
    """Solve game on F_p^r."""
    subgroups = generate_subgroups_elementary_abelian(p, r)
    sub_dict = {s: i for i, s in enumerate(subgroups)}

    @lru_cache(maxsize=None)
    def can_first_player_win(idx):
        H = subgroups[idx]
        if len(H) == p**r:  # Full group
            return False

        for g in G:
            if g not in H:
                # Generate <H U {g}>
                new_elements = set(H)
                new_elements.add(g)

                changed = True
                while changed:
                    changed = False
                    for x in list(new_elements):
                        for y in list(new_elements):
                            new_x = tuple((x[i] + y[i]) % p for i in range(r))
                            if new_x not in new_elements:
                                new_elements.add(new_x)
                                changed = True

