                if new_H in sub_dict:
                    if not can_first_player_win(sub_dict[new_H]):
                        return True

        return False

    G = list(product(range(p), repeat=r))
    trivial = frozenset({tuple([0]*r)})
    if trivial in sub_dict:
        return not can_first_player_win(sub_dict[trivial])
    return False

