"""
Game on finite abelian groups.
Bob wins iff Grundy of starting position is 0.

For elementary abelian p-groups F_p^r:
- Each move increases span dimension by 1  
- Total moves = r (rank)
- Bob wins iff r is even

Bob wins for G ≅ Z_p^r where p is prime and r is even ≥ 2.
The 10 smallest orders are p^r for primes p and even r, sorted by value.
"""

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_bob_winning_orders(limit=10000):
    """Find all elementary abelian p-group orders where Bob wins."""
    bob_orders = []

    for p in range(2, limit + 1):
        if not is_prime(p):
            continue
        for r in range(2, 25, 2):  # even ranks
            order = p ** r
            if order > limit:
                break
            bob_orders.append(order)

    return sorted(set(bob_orders))

def main():
    orders = find_bob_winning_orders(10000)

    # The 10 smallest orders
    result = orders[:10]
    expected = [4, 9, 16, 25, 49, 64, 81, 121, 169, 256]

    # Verify the expected values
    assert result == expected, f"Expected {expected}, got {result}"

    # Verify each is p^r with p prime and r even
    for order in result:
        for p in range(2, order + 1):
            if is_prime(p):
                temp = order
                r = 0
                while temp % p == 0:
                    temp //= p
                    r += 1
                if temp == 1:
                    assert r % 2 == 0, f"{order} = {p}^{r}, r={r} should be even"
                    break

    # Calculate sum
    total = sum(result)
    print(f"10 smallest Bob-winning orders: {result}")
    print(f"Sum: {total}")

    print(f"\nANSWER: {total}")

if __name__ == "__main__":
    main()

