def brute_force_max(n):
    best = -float('inf')
    best_config = None

    races = list(itertools.permutations([1, 2, 3, 4]))[:n]  # All permutations
    if n == 1:
        races = [list(races[0])]

    # Generate all combinations
    if n == 1:
        for race1 in itertools.permutations([1]):
            matrix = [list(race1)]
            score = total_score(matrix)
            if score > best:
                best = score
                best_config = matrix
    elif n == 2:
        for race1 in itertools.permutations([1, 2]):
            for race2 in itertools.permutations([1, 2]):
                matrix = [list(race1), list(race2)]
                score = total_score(matrix)
                if score > best:
                    best = score
                    best_config = matrix
    elif n == 3:
        for race1 in itertools.permutations([1, 2, 3]):
            for race2 in itertools.permutations([1, 2, 3]):
                for race3 in itertools.permutations([1, 2, 3]):
                    matrix = [list(race1), list(race2), list(race3)]
                    score = total_score(matrix)
                    if score > best:
                        best = score
                        best_config = matrix
    elif n == 4:
        for race1 in itertools.permutations([1, 2, 3, 4]):
            for race2 in itertools.permutations([1, 2, 3, 4]):
                for race3 in itertools.permutations([1, 2, 3, 4]):
                    for race4 in itertools.permutations([1, 2, 3, 4]):
                        matrix = [list(race1), list(race2), list(race3), list(race4)]
                        score = total_score(matrix)
                        if score > best:
                            best = score
                            best_config = matrix

    return best, best_config

