from collections import Counter

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def gcd_sq_sum_abc(a, b, c):
    return gcd(a*a + b*b + c*c, a*b*c)

# Generate all triples with a <= b <= c to avoid duplicates
# and collect all gcd values
gcd_values = Counter()
