def check_f(n):
    """Check if f(n) = n satisfies the condition"""
    def f(x):
        return x

    for m in range(1, 21):
        for n in range(1, 21):
            lhs = f(m*n)**2
            rhs = f(m**2) * f(f(n)) * f(m*f(n))
            coprime = (m, n) == 1 or (m == 1 and n == 1)
            if (m == 1 and n == 1):
                # gcd(1,1) = 1, should hold
                if lhs != rhs:
                    print(f"FAIL at m=1, n=1: {lhs} != {rhs}")
                    return False
            elif (m, n) == 1:
                # coprime, should hold
                if lhs != rhs:
                    print(f"FAIL at m={m}, n={n} (coprime): {lhs} != {rhs}")
                    return False
            else:
                # not coprime, should NOT hold
                if lhs == rhs:
                    print(f"FAIL at m={m}, n={n} (not coprime): {lhs} == {rhs}")
                    return False
    return True

