        rem1 = (Q_val**2 + a * Q_val + 1) % P_val
        rem2 = (P_val**2 + b * P_val + 1) % Q_val

        if rem1 != 0 or rem2 != 0:
            return False, n, P_val, Q_val, rem1, rem2

    return True, None, None, None, None, None

