def check_polynomial_divisibility(P_coeffs, Q_coeffs, a, b):
    """Check if P(n) | Q(n)^2 + aQ(n) + 1 and Q(n) | P(n)^2 + bP(n) + 1 for n=1..20"""
    P = sum(c * n**i for i, c in enumerate(P_coeffs))
    Q = sum(c * n**i for i, c in enumerate(Q_coeffs))

    for n in range(1, 21):
        if P == 0 or Q == 0:
            continue
        if (Q**2 + a*Q + 1) % P != 0:
            return False
        if (P**2 + b*P + 1) % Q != 0:
            return False
    return True

