            # P(x) = x^deg_p + p_{deg_p-1}*x^{deg_p-1} + ... + p_0
            # Q(x) = x^deg_q + q_{deg_q-1}*x^{deg_q-1} + ... + q_0

            # Generate all coefficient combinations
            from itertools import product

            p_coeffs = [1] + list(product(range(-max_coeff, max_coeff+1), repeat=deg_p))
            q_coeffs = [1] + list(product(range(-max_coeff, max_coeff+1), repeat=deg_q))

            for P_list in p_coeffs:
                for Q_list in q_coeffs:
                    # Check if P and Q are distinct (leading terms already same)
