import numpy as np
from itertools import product

def eval_poly(coeffs, n):
    """Evaluate polynomial with coeffs in ascending order (constant term first) at x = n."""
    result = 0
    power = 1
    for c in coeffs:
        result += c * power
        power *= n
    return result

def check_solution(P_coeffs, Q_coeffs, a, b, max_n=100):
    """Check divisibility conditions for n = 1 to max_n."""
    for n in range(1, max_n + 1):
        P_val = eval_poly(P_coeffs, n)
        Q_val = eval_poly(Q_coeffs, n)

        if P_val == 0:
            if Q_val**2 + a * Q_val + 1 != 0:
                return False
        if Q_val == 0:
            if P_val**2 + b * P_val + 1 != 0:
                return False

        if P_val != 0 and (Q_val**2 + a * Q_val + 1) % P_val != 0:
            return False
        if Q_val != 0 and (P_val**2 + b * P_val + 1) % Q_val != 0:
            return False
    return True

def find_solutions(max_deg, coeff_range, max_n=100):
    """Find all solutions with polynomials of degree up to max_deg (non-constant)."""
    solutions = []

    for deg_P in range(1, max_deg + 1):
        for deg_Q in range(1, max_deg + 1):
            # Coefficients: [c0, c1, ..., c_{d-1}, 1] for monic polynomial
            # Vary non-leading coefficients
            for P_coeffs in product(*[range(-coeff_range, coeff_range + 1)] * (deg_P - 1)):
                P = list(P_coeffs) + [1]

                for Q_coeffs in product(*[range(-coeff_range, coeff_range + 1)] * (deg_Q - 1)):
                    Q = list(Q_coeffs) + [1]

                    # Skip constant polynomials (degree 0)
                    if len(P) == 1 or len(Q) == 1:
                        continue

                    # Try various a, b values
                    for a in range(-20, 21, 2):
                        for b in range(-20, 21, 2):
                            if abs(a) < 3 or abs(b) < 3:
                                continue

                            if check_solution(P, Q, a, b, max_n):
                                solutions.append((a, b, P, Q))

    return solutions

