Key insight: P(n) | Q(n)^2 + aQ(n) + 1 for all n implies P(x) | Q(x)^2 + aQ(x) + 1
"""
from sympy import symbols, Poly, gcd, factor
x = symbols('x')

def check_poly(P, Q, a, b, max_n=50):
    for n in range(1, max_n + 1):
        Pn = int(P.evalf(subs={x: n}))
        Qn = int(Q.evalf(subs={x: n}))
        if Pn == 0 or Qn == 0:
            return False
        if (Qn**2 + a*Qn + 1) % Pn != 0:
            return False
        if (Pn**2 + b*Pn + 1) % Qn != 0:
            return False
    return True

# Try P(x) = x^2, Q(x) = x^2 + k*x + c
