found = []
for k in range(-5, 6):
    for c in range(-5, 6):
        for a in [-10, -9, -8, -7, -6, -5, -4, -3, 3, 4, 5, 6, 7, 8, 9, 10]:
            for b in [-10, -9, -8, -7, -6, -5, -4, -3, 3, 4, 5, 6, 7, 8, 9, 10]:
                P = x**2
                Q = x**2 + k*x + c
                if check_poly(P, Q, a, b):
                    if abs(a) >= 3 and abs(b) >= 3:
                        found.append((k, c, a, b))
                        print(f"Found: k={k}, c={c}, a={a}, b={b}")

print(f"\nTotal: {len(found)}")

