print(f"\nTotal: {len(found2)}")

"""
Problem: P, Q are non-constant monic integer polynomials, |a|>=3, |b|>=3
P(n) | Q(n)^2 + aQ(n) + 1
Q(n) | P(n)^2 + bP(n) + 1
for all positive integers n.

Find sum of 10 smallest |a+b| and sum of 10 smallest |deg P|.
"""

import sympy as sp

n = sp.symbols('n', integer=True)

def check_polynomials(P, Q, a, b):
    """Check if P(n) | Q(n)^2 + aQ(n) + 1 and Q(n) | P(n)^2 + bP(n) + 1 for n up to 15."""
    for n_val in range(1, 16):
        P_val = int(P.subs(n, n_val))
        Q_val = int(Q.subs(n, n_val))
        if P_val == 0 or Q_val == 0:
            return False
        if (Q_val**2 + a*Q_val + 1) % P_val != 0:
            return False
        if (P_val**2 + b*P_val + 1) % Q_val != 0:
            return False
    return True

# We need to find:
# - All possible values of |a+b| that can occur
# - All possible values of |deg P| that can occur
# Then sum the 10 smallest of each

# Let's search for solutions and collect the distinct values
ab_values = set()
deg_values = set()
sample_solutions = []

# Search for quadratic polynomials
print("Searching for quadratic polynomial solutions...")
for c in range(-3, 4):
    for d in range(-3, 4):
        for e in range(-3, 4):
            for f in range(-3, 4):
                P = n**2 + c*n + d
                Q = n**2 + e*n + f
                if c == e and d == f:
                    continue
                for a in range(-8, 9):
                    for b in range(-8, 9):
                        if abs(a) >= 3 and abs(b) >= 3:
                            if check_polynomials(P, Q, a, b):
                                ab_values.add(abs(a + b))
                                deg_values.add(2)
                                sample_solutions.append((abs(a + b), 2, a, b, c, d, e, f))
                                if len(sample_solutions) < 50:
                                    print(f"Found: |a+b|={abs(a+b)}, a={a}, b={b}, P={P}, Q={Q}")

# Search for degree 1 polynomials
print("\nSearching for degree 1 polynomial solutions...")
for c in range(-5, 6):
    for d in range(-5, 6):
        if c == d:
            continue
        P = n + c
        Q = n + d
        for a in range(-8, 9):
            for b in range(-8, 9):
                if abs(a) >= 3 and abs(b) >= 3:
                    if check_polynomials(P, Q, a, b):
                        ab_values.add(abs(a + b))
                        deg_values.add(1)
                        sample_solutions.append((abs(a + b), 1, a, b, c, d))
                        if len(sample_solutions) < 50:
                            print(f"Found deg 1: |a+b|={abs(a+b)}, a={a}, b={b}, P={P}, Q={Q}")

# Search for degree 3 polynomials
print("\nSearching for degree 3 polynomial solutions...")
for c in range(-2, 3):
    for d in range(-2, 3):
        for e in range(-2, 3):
            for f in range(-2, 3):
                for g in range(-2, 3):
                    for h in range(-2, 3):
                        P = n**3 + c*n**2 + d*n + e
                        Q = n**3 + f*n**2 + g*n + h
                        if c == f and d == g and e == h:
                            continue
                        for a in range(-8, 9):
                            for b in range(-8, 9):
                                if abs(a) >= 3 and abs(b) >= 3:
                                    if check_polynomials(P, Q, a, b):
                                        ab_values.add(abs(a + b))
                                        deg_values.add(3)
                                        sample_solutions.append((abs(a + b), 3, a, b))
                                        if len(sample_solutions) < 50:
                                            print(f"Found deg 3: |a+b|={abs(a+b)}, a={a}, b={b}")

# Print results
print(f"\n\nDistinct |a+b| values found: {sorted(ab_values)}")
print(f"Distinct |deg P| values found: {sorted(deg_values)}")
print(f"Number of sample solutions: {len(sample_solutions)}")

# Get 10 smallest |a+b| values (distinct)
if len(ab_values) >= 10:
    sorted_ab = sorted(ab_values)
    print(f"\n10 smallest distinct |a+b|: {sorted_ab[:10]}")
    S1 = sum(sorted_ab[:10])
    print(f"S1 = {S1}")
else:
    print(f"\nOnly {len(ab_values)} distinct |a+b| values found: {sorted(ab_values)}")
    S1 = sum(sorted_ab) if (sorted_ab := sorted(ab_values)) else 0

# Get 10 smallest |deg P| values (distinct)
if len(deg_values) >= 10:
    sorted_deg = sorted(deg_values)
    print(f"\n10 smallest distinct |deg P|: {sorted_deg[:10]}")
    S2 = sum(sorted_deg[:10])
    print(f"S2 = {S2}")
else:
    print(f"\nOnly {len(deg_values)} distinct |deg P| values found: {sorted(deg_values)}")
    S2 = sum(sorted_deg) if (sorted_deg := sorted(deg_values)) else 0

print(f"\nS1 + S2 = {S1 + S2 if 'S1' in dir() and 'S2' in dir() else 'N/A'}")

