def eval_poly(coeffs, n):
    result = 0
    for i, c in enumerate(coeffs):
        result += c * (n ** i)
    return result

def check_numeric(P, Q, a, b, max_n=1000):
    for n in range(1, max_n + 1):
        p_val = eval_poly(P, n)
        q_val = eval_poly(Q, n)
        if p_val == 0 or q_val == 0:
            continue
        if (q_val**2 + a*q_val + 1) % p_val != 0:
            return False, f"Failed at n={n}: {q_val}^2+{a}{q_val}+1 = {q_val**2+a*q_val+1}, mod {p_val} = {(q_val**2+a*q_val+1)%p_val}"
        if (p_val**2 + b*p_val + 1) % q_val != 0:
            return False, f"Failed at n={n}: {p_val}^2+{b}{p_val}+1 = {p_val**2+b*p_val+1}, mod {q_val} = {(p_val**2+b*p_val+1)%q_val}"
