"""
Problem: P and Q are monic integer polynomials, non-constant.
|a| >= 3, |b| >= 3.
P(n) | Q(n)^2 + aQ(n) + 1
Q(n) | P(n)^2 + bP(n) + 1
for all positive integers n.

Find sum of 10 smallest |a+b| and sum of 10 smallest |deg P|.
"""

from sympy import symbols, Poly, rem

x = symbols('x')

def check_poly_divisibility(P, Q, a, b):
    """Check if P(x) divides Q(x)^2 + aQ(x) + 1 and Q(x) divides P(x)^2 + bP(x) + 1"""
    P_poly = Poly(P, x)
    Q_poly = Poly(Q, x)
    expr1 = Q_poly**2 + a*Q_poly + 1
    expr2 = P_poly**2 + b*P_poly + 1
    return rem(expr1, P_poly) == 0 and rem(expr2, Q_poly) == 0

def check_at_points(P, Q, a, b, max_n=50):
    """Check divisibility at integer points as additional verification"""
    for n in range(1, max_n + 1):
        p_val = P.subs(x, n)
        q_val = Q.subs(x, n)
        if p_val == 0 or q_val == 0:
            continue
        if (q_val**2 + a*q_val + 1) % p_val != 0:
            return False
        if (p_val**2 + b*p_val + 1) % q_val != 0:
            return False
    return True

solutions = []

# Case 1: deg(P) = 1, deg(Q) = 1
# P(x) = x + p, Q(x) = x + q
print("Searching deg(P)=1, deg(Q)=1...")
for p in range(-20, 21):
    for q in range(-20, 21):
        if p == q:
            continue
        for a in range(-20, 21):
            for b in range(-20, 21):
                if abs(a) < 3 or abs(b) < 3:
                    continue
                P = x + p
                Q = x + q
                if check_poly_divisibility(P, Q, a, b):
                    if check_at_points(P, Q, a, b):
                        solutions.append((p, q, a, b))

print(f"Found {len(solutions)} solutions for deg 1,1")
