def find_solutions(max_deg=3, max_coeff=10):
    """Find all solutions with polynomials of degree up to max_deg."""
    solutions = []

    for deg in range(1, max_deg + 1):
        # Generate all monic polynomials of given degree with coefficients in range
        from itertools import product

        # Coefficients from constant term up to x^(deg-1), with leading coeff = 1
        coeffs_range = list(range(-max_coeff, max_coeff + 1))

        for P_coeffs in product(coeffs_range, repeat=deg):
            P = list(P_coeffs) + [1]  # [c0, c1, ..., c_{deg-1}, 1]

            # Skip if P has all coefficients 0 (not possible with leading 1)

            for Q_coeffs in product(coeffs_range, repeat=deg):
                Q = list(Q_coeffs) + [1]

                if P == Q:
                    continue

                # Evaluate polynomials
                def eval_poly(coeffs, n):
                    return sum(c * n**i for i, c in enumerate(coeffs))

                # Search for (a, b) pairs
                for a in range(-20, 21):
                    if abs(a) < 3:
                        continue
                    for b in range(-20, 21):
                        if abs(b) < 3:
                            continue

                        valid = True
                        for n in range(1, 31):
                            Pn = eval_poly(P, n)
                            Qn = eval_poly(Q, n)
                            if Pn == 0 or Qn == 0:
                                continue
                            if (Qn**2 + a*Qn + 1) % Pn != 0:
                                valid = False
                                break
                            if (Pn**2 + b*Pn + 1) % Qn != 0:
                                valid = False
                                break

                        if valid:
