def compute_win_lose(state):
    """
    Compute whether current player wins or loses from state.
    Returns 'W' for winning, 'L' for losing.
    """
    state = tuple(sorted(state))
    memo = {}

    def can_win(s):
        if s in memo:
            return memo[s]
        if s == ():
            return False  # Previous player erased last number and lost

