def solve_game(N):
    """Solve game for N using bitmask representation."""
    initial = (1 << N) - 2  # bits 1 to N set (bit 0 is 0)

    # Memoize by bitmask
    memo = {}

    def can_win(mask):
        if mask == 0:
            return False
        if mask & 1:  # If only bit 0 is set, we lose (but this shouldn't happen normally)
            return False

        if mask in memo:
            return memo[mask]

        # Find all set bits
        temp = mask
        while temp:
            n = (temp & -temp).bit_length() - 1  # position of lowest set bit
            temp &= temp - 1  # clear lowest bit

            # Try all k >= 1
            for k in range(1, 15):
                power = 1 << k
                # Find all s in mask where s ≡ n (mod 2^k)
                # s = n + m*2^k for some m
                new_mask = mask
                for s in range(n, N + 1):
                    if s < n:
                        continue
                    if (s - n) % power == 0:
                        if (mask >> s) & 1:
                            new_mask &= ~(1 << s)

                if new_mask == 0:
                    continue

                if not can_win(new_mask):
                    memo[mask] = True
                    return True

        memo[mask] = False
        return False

    return can_win(initial)

