    queue.append(state)
    visited.add(state)

    step = 0
    while queue:
        current = queue.popleft()
        step += 1

        if len(current) == n * n:
            return True, step, len(visited)

        if len(visited) > max_states:
            return False, step, len(visited)

        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                black_count = sum(1 for cell in cells if cell in current)

                if black_count == 1:
                    white_cells = [cell for cell in cells if cell not in current]
                    new_state = current | set(white_cells)
                    new_state = frozenset(new_state)

                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)

    return False, step, len(visited)

