def count_attacks_immediate(rooks, rook_pos):
    """Count attacks for a rook (only immediate neighbors)."""
    row, col = rook_pos
    count = 0

    # Find immediate left/right neighbors in row
    row_rooks = sorted([c for r, c in rooks if r == row])
    for i, c in enumerate(row_rooks):
        if i > 0 and row_rooks[i-1] < c:
            count += 1  # left neighbor
        if i < len(row_rooks) - 1 and row_rooks[i+1] > c:
            count += 1  # right neighbor

    # Find immediate up/down neighbors in column
    col_rooks = sorted([r for r, c in rooks if c == col])
    for i, r in enumerate(col_rooks):
        if i > 0 and col_rooks[i-1] < r:
            count += 1  # up neighbor
        if i < len(col_rooks) - 1 and col_rooks[i+1] > r:
            count += 1  # down neighbor

    return count

