# Fix the counting bug
def count_attacks_immediate(rooks, rook_pos):
    """Count attacks for a rook (only immediate neighbors)."""
    row, col = rook_pos
    count = 0

    # Find immediate left/right neighbors in row
    row_rooks = sorted([c for r, c in rooks if r == row])
    for i, c in enumerate(row_rooks):
        if i > 0:
            count += 1  # left neighbor (row_rooks[i-1] < c is always true when sorted)
        if i < len(row_rooks) - 1:
            count += 1  # right neighbor (row_rooks[i+1] > c is always true when sorted)

    # Find immediate up/down neighbors in column
    col_rooks = sorted([r for r, c in rooks if c == col])
    for i, r in enumerate(col_rooks):
        if i > 0:
            count += 1  # up neighbor
        if i < len(col_rooks) - 1:
            count += 1  # down neighbor

    return count

def is_valid_immediate(rooks):
    for r, c in rooks:
        if count_attacks_immediate(rooks, (r, c)) == 4:
            return False, (r, c)
    return True, None

