def test_boundary(n):
    rooks = set()
    for i in range(n):
        rooks.add((i, 0))
        rooks.add((i, n-1))
    for j in range(1, n-1):
        rooks.add((0, j))
        rooks.add((n-1, j))
    return rooks

def test_3rank(n, k):
    rooks = set()
    for i in range(k):
        for j in range(3):
            rooks.add((i, j))
    for i in range(k, n):
        for j in range(2):
            rooks.add((i, j))
    return rooks

