def make_grid(n):
    """Create rook positions: even rows get 3 rooks, odd rows get 2 rooks."""
    positions = []
    for r in range(n):
        if r % 2 == 0:
            num_rooks = 3
        else:
            num_rooks = 2
        start_col = sum(3 if i % 2 == 0 else 2 for i in range(r))
        for c in range(start_col, start_col + num_rooks):
            positions.append((r, c))
    return positions

