from functools import lru_cache

@lru_cache(maxsize=None)
def can_win(n, b_a, b_b, turn):
    if n == 0:
        return False

    if turn == 0:  # Alice's turn
        # Operation A: pick 1, 2, or 3
        for pick in [1, 2, 3]:
            if pick <= n and not can_win(n - pick, b_a, b_b, 1):
                return True
        # Operation B: pick 4 (if available)
        if b_a > 0 and 4 <= n and not can_win(n - 4, b_a - 1, b_b, 1):
            return True
        return False

    else:  # Bob's turn
        for pick in [1, 2, 3]:
            if pick <= n and not can_win(n - pick, b_a, b_b, 0):
                return True
        if b_b > 0 and 4 <= n and not can_win(n - 4, b_a, b_b - 1, 0):
            return True
        return False

