"""
Game theory problem - trying both interpretations:

Interpretation 1: Total B-uses (both players combined) ≤ 5
Interpretation 2: Each player can use B up to 5 times independently

Let me compute both and see which makes sense.
"""

def solve_interpretation1():
    """Total B-uses across game ≤ 5"""
    MAX_N = 2025
    MAX_K = 5

    # dp[n][k] = 0 if losing, 1 if winning
    dp = [[0] * (MAX_K + 1) for _ in range(MAX_N + 1)]

    for k in range(MAX_K + 1):
        dp[0][k] = 0

    for n in range(1, MAX_N + 1):
        for k in range(MAX_K + 1):
            can_reach_losing = False

            # Operation A: pick 1, 2, or 3
            for pick in [1, 2, 3]:
                if n >= pick and dp[n - pick][k] == 0:
                    can_reach_losing = True
                    break

            # Operation B: pick 4
            if not can_reach_losing and n >= 4 and k < MAX_K:
                if dp[n - 4][k + 1] == 0:
                    can_reach_losing = True

            dp[n][k] = 1 if can_reach_losing else 0

    return sum(1 for n in range(1, MAX_N + 1) if dp[n][0] == 1)


def solve_interpretation2():
    """Each player can use B up to 5 times independently"""
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can_win(n, alice_b_left, bob_b_left, turn):
        """turn: 0 = Alice, 1 = Bob"""

        # Operation A: pick 1, 2, or 3
        for pick in [1, 2, 3]:
            if n >= pick:
                if n - pick == 0:
                    return True
                new_turn = 1 - turn
                if not can_win(n - pick, bob_b_left, alice_b_left, new_turn):
                    return True

        # Operation B: pick 4
        if n >= 4:
            if turn == 0 and alice_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, bob_b_left, alice_b_left - 1, 1):
                    return True
            elif turn == 1 and bob_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left, bob_b_left - 1, 0):
                    return True

        return False

    count = 0
    for n in range(1, 2026):
        if can_win(n, 5, 5, 0):
            count += 1

    return count


print("Interpretation 1 (total B-uses ≤ 5):", solve_interpretation1())
print("Interpretation 2 (each player B-uses ≤ 5):", solve_interpretation2())

