    # State: (n, alice_b_left, bob_b_left, turn)
    @lru_cache(maxsize=None)
    def can_win(n, alice_b_left, bob_b_left, turn):
        # Operation A: pick 1, 2, or 3
        for pick in [1, 2, 3]:
            if n - pick >= 0:
                if n - pick == 0:
                    return True
                new_turn = 1 - turn
                if not can_win(n - pick, alice_b_left, bob_b_left, new_turn):
                    return True

        # Operation B: pick 4 (at most 5 times per player)
        if n - 4 >= 0:
            if turn == 0 and alice_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left - 1, bob_b_left, 1):
                    return True
            elif turn == 1 and bob_b_left > 0:
                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left, bob_b_left - 1, 0):
                    return True

        return False

    # Verify specific values we know from manual analysis
    assert can_win(29, 5, 5, 0) == False, "n=29 should be losing for Alice"
    assert can_win(30, 5, 5, 0) == True, "n=30 should be winning for Alice"

    # Verify n=1..100 gives 77 wins
    wins_100 = sum(1 for n in range(1, 101) if can_win(n, 5, 5, 0))
    assert wins_100 == 77, f"Expected 77 wins for n=1..100, got {wins_100}"

    # Verify n=1..5: 4 wins (only n=5 is losing)
    wins_5 = sum(1 for n in range(1, 6) if can_win(n, 5, 5, 0))
    assert wins_5 == 4, f"Expected 4 wins for n=1..5, got {wins_5}"

    # Verify n=1..20: 16 wins (n=5,10,15,20 are losing)
    wins_20 = sum(1 for n in range(1, 21) if can_win(n, 5, 5, 0))
    assert wins_20 == 16, f"Expected 16 wins for n=1..20, got {wins_20}"

    # Count wins for n=1..2025
    count = sum(1 for n in range(1, 2026) if can_win(n, 5, 5, 0))

    print(f"ANSWER: {count}")
    assert count == 1520, f"Expected 1520, got {count}"

solve()

