    if n == 0:
        return False

    if turn == 0:  # Alice's turn
        for pick in [1, 2, 3]:
            if pick <= n and not can_win(n - pick, b_a, b_b, 1):
                return True
        if b_a > 0 and 4 <= n and not can_win(n - 4, b_a - 1, b_b, 1):
