        for i in range(start_idx, len(existing_edges)):
            u, v = existing_edges[i]
            if u not in matched and v not in matched:
                new_matched = matched | {u, v}
                if can_match(i + 1, new_matched, edge_count + 1):
                    return True
        return False
    return can_match(0, set(), 0)

def build_Knn(n):
    """Build K_{n,n} with partitions 0..n-1 and n..2n-1."""
    vertices = 2 * n
    edges = []
    for i in range(n):
        for j in range(n, 2*n):
            edges.append((i, j))
    return vertices, edges

def build_Knn_plus_edge(n, extra_edge):
    """Build K_{n,n} plus an extra edge."""
    vertices, edges = build_Knn(n)
    if extra_edge[0] < n and extra_edge[1] < n:
        edges.append(extra_edge)
    elif extra_edge[0] >= n and extra_edge[1] >= n:
        edges.append(extra_edge)
    return vertices, edges

def can_alice_evade(vertices, edges, max_rounds=100):
    """
    Check if Alice can evade Bob indefinitely.
    Alice chooses optimal starting positions.
    Both play optimally.
    """
    adj = {i: set() for i in range(vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Alice chooses starting positions
    for a_start in range(vertices):
        for b_start in range(vertices):
            if a_start == b_start:
                continue
            # Check if Alice can survive from this position
            if can_alice_survive(a_start, b_start, adj, max_rounds):
                return True
    return False

def can_alice_survive(a_pos, b_pos, adj, max_rounds):
    """
    Check if Alice can survive from current positions.
    Alice plays optimally to evade, Bob plays optimally to catch.
    """
    for _ in range(max_rounds):
        # Alice's turn
        neighbors = list(adj[a_pos])
        if not neighbors:
            return False
        # Alice chooses a move that survives
        a_next = None
        for n in neighbors:
            if can_alice_survive_after(n, b_pos, adj, max_rounds):
                a_next = n
                break
        if a_next is None:
            return False
        a_pos = a_next
        if a_pos == b_pos:
            return False

        # Bob's turn
        neighbors = list(adj[b_pos])
        if not neighbors:
            return True
        # Bob chooses a move that catches Alice
        b_next = None
        for n in neighbors:
            if n == a_pos:
                b_next = n
                break
            if can_alice_survive_after(a_pos, n, adj, max_rounds):
                b_next = n
                break
        if b_next is None:
            return True
        b_pos = b_next
        if b_pos == a_pos:
            return False
    return True

def can_alice_survive_after(a_pos, b_pos, adj, max_rounds):
    """Check if Alice can survive after she moves to a_pos (Bob at b_pos)."""
    for _ in range(max_rounds):
        neighbors = list(adj[b_pos])
        if not neighbors:
            return True
        b_next = None
        for n in neighbors:
            if n == a_pos:
                b_next = n
                break
            if can_alice_survive_after(a_pos, n, adj, max_rounds):
                b_next = n
                break
        if b_next is None:
            return True
        b_pos = b_next
        if b_pos == a_pos:
            return False
    return True

# Test K_{n,n}
print("Testing K_{n,n}:")
for n in [2, 3, 4]:
    vertices, edges = build_Knn(n)
    result = can_alice_evade(vertices, edges)
    print(f"  K_{{{n},{n}}}: {vertices} vertices, {len(edges)} edges, Alice evades: {result}")

# Test K_{n,n} plus extra edges
print("\nTesting K_{n,n} + extra edges:")
for n in [2, 3]:
