    """Simulate the game. Returns day when stabilization is first detected, or None if cycle."""
    adj = {i: set() for i in range(n)}
    for i, j in edges:
        adj[i].add(j)
        adj[j].add(i)

    values = list(initial_values)
    day = 1

    seen = {}
    state = tuple(values)

    while day <= max_steps:
        new_values = [mex([values[j] for j in adj[i]]) for i in range(n)]

        if new_values == values:
            return day + 1  # Stops on day (day+1)

        values = new_values
        day += 1

        state = tuple(values)
        if state in seen:
            return None  # Cycle detected

        seen[state] = day

    return None  # Max steps reached

def find_max_days(n):
