def verify_structure(a, b, c):
    """Verify the triangle constraint"""
    N = a + b + c
    colors = {}

    # Within V1: X, Within V2: Y, Within V3: Z
    for i in range(a):
        for j in range(i+1, a):
            colors[(i, j)] = 'X'
    for i in range(a, a+b):
        for j in range(i+1, a+b):
            colors[(i, j)] = 'Y'
    for i in range(a+b, a+b+c):
        for j in range(i+1, a+b+c):
            colors[(i, j)] = 'Z'

    # Between V1-V2: Z
    for i in range(a):
        for j in range(a, a+b):
            colors[(i, j)] = 'Z'

    # Between V2-V3: X
    for i in range(a, a+b):
        for j in range(a+b, a+b+c):
            colors[(i, j)] = 'X'

    # Between V3-V1: Y
    for i in range(a+b, a+b+c):
        for j in range(a, a+b):
            colors[(j, i)] = 'Y'

    # Check all triangles
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                c1 = colors[(i, j)]
