                c3 = colors[(i, k)]

                # Constraint: if two edges differ, third must be the third color
                if c1 != c2:
                    third = 'Y' if c1 == 'X' else ('X' if c1 == 'Z' else 'Z')
                    if c3 != third:
                        return False, (i, j, k, c1, c2, c3)
                if c2 != c3:
