"""
Bee path counting problem:
- 4 rows (A,B,C,D), 7 columns (1-7)
- Start at (A,4) = (0,3)
- Reach any cell in row D (row index 3)
- Max 6 moves
- Cannot revisit cells
- Count distinct paths
"""

def count_paths():
    rows = 4  # A=0, B=1, C=2, D=3
    cols = 7  # columns 1-7

    start = (0, 3)  # row A, column 4

    # DFS with memoization
    def dfs(r, c, visited, steps):
        # Check if reached row D
        if r == 3:
            return 1

        # Max steps is 6
        if steps >= 6:
            return 0

        total = 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

