"""
Find minimum n such that every infinite sequence over {1..k} contains one of n triples.

This is the minimum feedback arc set on the De Bruijn graph B(k,2).
"""

from itertools import combinations, product
from collections import defaultdict

def has_cycle_in_complement(triple_set, k):
    """
    Check if there exists an infinite sequence avoiding triple_set.
    Returns True if cycle exists (infinite avoiding sequence possible),
    False if no cycle (all sequences must hit at least one triple).
    """
    alphabet = list(range(k))

    # Build complement graph: edges NOT in triples
    adj = defaultdict(list)
    for u in alphabet:
        for v in alphabet:
            for w in alphabet:
                if (u,v,w) not in triple_set:
                    adj[(u,v)].append((v,w))

    # Check for cycles using DFS from each node
    WHITE, GRAY, BLACK = 0, 1, 2

    def check_cycle_from(start):
        color = {start: WHITE}

        def dfs(node):
            if node in color:
                return color[node] == GRAY
            color[node] = GRAY
            for neighbor in adj[node]:
                if dfs(neighbor):
                    return True
            color[node] = BLACK
            return False

        return dfs(start)

    for start in [(u,v) for u in alphabet for v in alphabet]:
        if check_cycle_from(start):
            return True
    return False

def find_min_n(k):
    """Find minimum n for alphabet size k."""
    alphabet = list(range(k))
    all_triples = list(product(alphabet, repeat=3))

    # Try increasing n
    for n in range(len(all_triples) + 1):
        # Try all combinations of size n
        for combo in combinations(all_triples, n):
            triple_set = set(combo)
            if not has_cycle_in_complement(triple_set, k):
                return n

    return -1

