"""
Problem: Find minimum n such that every infinite sequence over alphabet {1..k}
contains at least one of n triples.

This equals the minimum feedback edge set of De Bruijn graph B(k,2):
- Vertices: consecutive pairs (k^2 vertices)
- Edges: triples (k^3 edges)

Verified by brute force:
- k=1: min_removed=1 = 1^2 ✓
- k=2: min_removed=4 = 2^2 ✓

Pattern: answer = k^2

For k=100: answer = 100^2 = 10000
"""

def build_debruijn_graph(k):
    vertices = [(u, v) for u in range(k) for v in range(k)]
    edges = []
    for u in range(k):
        for v in range(k):
            for w in range(k):
                edges.append(((u, v), (v, w), (u, v, w)))
    return vertices, edges

def has_cycle_in_subgraph(kept_edge_indices, vertices, edges):
    adj = {}
    for idx in kept_edge_indices:
        u, v, _ = edges[idx]
        if u not in adj:
            adj[u] = []
        adj[u].append(v)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {v: WHITE for v in vertices}

    def dfs(node):
        color[node] = GRAY
        for neighbor in adj.get(node, []):
            if color[neighbor] == GRAY:
                return True
            if color[neighbor] == WHITE and dfs(neighbor):
                return True
        color[node] = BLACK
        return False

    for v in vertices:
        if color[v] == WHITE and dfs(v):
            return True
    return False

def min_feedback_edge_set(k):
    vertices, edges = build_debruijn_graph(k)
    num_edges = len(edges)

    for num_removed in range(num_edges + 1):
        for removed_subset in __import__('itertools').combinations(range(num_edges), num_removed):
            kept_indices = [i for i in range(num_edges) if i not in removed_subset]
            if not has_cycle_in_subgraph(kept_indices, vertices, edges):
                return num_removed
    return num_edges

