The key insight is that we need to find the minimum number of edges to remove
so that no cycle remains in the remaining graph.

Let me use a more efficient algorithm: find a maximum acyclic subgraph.
"""

from itertools import product

def build_debruijn_graph(k, m):
    """Build De Bruijn graph B(k, m)"""
    vertices = [tuple(s) for s in product(range(k), repeat=m)]
    edges = []
    for v in vertices:
        prefix = v[1:]
        for c in range(k):
            w = prefix + (c,)
            edges.append((v, w))
    return vertices, edges

def has_cycle(edges, vertices):
    """Check if there's a cycle using DFS"""
    adj = {v: [] for v in vertices}
    for u, v in edges:
        adj[u].append(v)

    def dfs(node, visited, rec_stack):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                if dfs(neighbor, visited, rec_stack):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    visited = set()
    for v in vertices:
        if v not in visited:
            if dfs(v, visited, set()):
                return True
    return False

def find_max_acyclic_subgraph(k, m):
    """
    Find maximum acyclic subgraph using a greedy approach with topological sort.
    """
    vertices, edges = build_debruijn_graph(k, m)
    num_edges = len(edges)

    # Try all orderings of edges and pick greedily
    # This gives an approximation, not necessarily optimal

    best = []
    best_size = 0

    # For small graphs, try all subsets
    if num_edges <= 12:
