            for subset in range(num_edges + 1):
                from itertools import combinations
                for subset in combinations(range(num_edges), r):
                    kept = [edges[i] for i in subset]
                    if not has_cycle(kept, vertices):
                        if r > best_size:
                            best_size = r
                            best = kept
                    if r == num_edges:
                        break
            if best_size == num_edges:
                break
        return num_edges - best_size
    else:
        # Use a smarter approach: try to find a topological ordering
        # and select edges consistent with it

        # For each possible topological ordering, count compatible edges
        # This is still expensive, so let's use a simpler greedy approach

        # Greedy: keep edges in an order that doesn't create cycles
        kept = []
        for i in range(num_edges):
            test = kept + [edges[i]]
            if not has_cycle(test, vertices):
                kept.append(edges[i])

        return num_edges - len(kept)

