    return vertices, edges

def has_cycle(edges, vertices):
    """Check if there's a cycle using correct DFS"""
    # Build adjacency list
    adj = {v: [] for v in vertices}
    for u, v in edges:
        adj[u].append(v)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {v: WHITE for v in vertices}

    def dfs(node):
        color[node] = GRAY
        for neighbor in adj[node]:
            if color[neighbor] == GRAY:
                return True
            if color[neighbor] == WHITE and dfs(neighbor):
                return True
        color[node] = BLACK
        return False

    for v in vertices:
        if color[v] == WHITE and dfs(v):
            return True
    return False

def min_feedback_edge_set_bruteforce(k, m):
    """Find minimum feedback edge set by brute force"""
    vertices, edges = build_debruijn_graph(k, m)
    num_edges = len(edges)

    # Try all subset sizes from 0 to num_edges
    for r in range(num_edges + 1):
        # Check if any subset of size r works (has no cycles)
        for subset in combinations(range(num_edges), r):
            kept_edges = [edges[i] for i in subset]
            if not has_cycle(kept_edges, vertices):
                return num_edges - r
    return num_edges

