    """Check if board satisfies cool condition for n."""
    proper_divisors = [d for d in range(2, n) if n % d == 0]

    if not proper_divisors:
        return True

    for d in proper_divisors:
        num_subboards = (n // d) ** 2

        for i in range(n // d):
            for j in range(n // d):
                subsum = 0
                for r in range(i*d, (i+1)*d):
                    for c in range(j*d, (j+1)*d):
                        subsum += board[r][c]
                if subsum % d == 0:
                    return False

    return True

