    # Pattern 2: Column-major
    board = [n*i + j + 1 for i in range(n) for j in range(n)]
    if check_board(board, n):
        return True

    # Pattern 3: Snake row
    board = []
    for i in range(n):
        for j in range(n):
            if i % 2 == 0:
                board.append(i*n + j + 1)
            else:
                board.append(i*n + (n-1-j) + 1)
    if check_board(board, n):
        return True

    # Pattern 4: Checkerboard parity
    flat = []
    for i in range(n):
        for j in range(n):
            if (i + j) % 2 == 0:
                flat.append(2 * (i*n + j) + 1)
            else:
                flat.append(2 * (i*n + j) + 2)
    if check_board(flat, n):
