"""
Game: Alice and Bob take turns adding elements to a box T.
When an element g is added, all elements of <T U {g}> are added to T.
Alice moves first. Last player to move wins (normal play).
Find all G where Bob has a winning strategy.
"""

import itertools

def group_elements(n):
    """Return elements of Z_n as range(n)"""
    return list(range(n))

def add(a, b, n):
    return (a + b) % n

def multiply(a, b, n):
    return (a * b) % n

def inverse(a, n):
    return (-a) % n

def generate_subgroup(generators, n):
    """Generate subgroup of Z_n from generators"""
    if not generators:
        return {0}
    subgroup = {0}
    changed = True
    while changed:
        changed = False
        for g in generators:
            for h in list(subgroup):
                new_elem = (g + h) % n
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
    return subgroup

def generate_subgroup_from_list(generators, n):
    """Generate subgroup from a list of generators"""
    if not generators:
        return {0}
    subgroup = set()
    changed = True
    while changed:
        changed = False
        for g in generators:
            for h in list(subgroup):
                new_elem = (g + h) % n
                if new_elem not in subgroup:
                    subgroup.add(new_elem)
                    changed = True
    return subgroup

def get_all_subgroups(n):
    """Get all subgroups of Z_n"""
    subgroups = []
    for r in range(1, n + 1):
        if n % r == 0:
            subgroup = set(range(0, n, r))
            subgroups.append(subgroup)
    return subgroups

def game_state_to_tuple(T, n):
    return tuple(sorted(T))

def can_move(T, n):
    """Check if there's any element not in T"""
    return len(T) < n

def get_new_elements(T, g, n):
    """Get elements added when g is added to T"""
    generators = list(T) + [g]
    new_subgroup = generate_subgroup_from_list(generators, n)
    return new_subgroup - T

def solve_game(n):
    """
    Solve the game for Z_n using minimax with memoization.
    Returns True if the first player (Alice) wins, False if Bob wins.
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def first_player_wins(T_tuple):
        T = set(T_tuple)

        if not can_move(T, n):
            return False  # Current player loses

        # Try all possible moves
        for g in range(n):
            if g not in T:
                new_elements = get_new_elements(T, g, n)
                if not new_elements:
                    continue  # This move adds nothing, shouldn't happen

                new_T = T | new_elements
                new_T_tuple = game_state_to_tuple(new_T, n)

                # If opponent loses from new state, this is a winning move
                if not first_player_wins(new_T_tuple):
                    return True

        return False  # All moves lead to opponent winning

    initial_T = {0}  # Identity element
    return first_player_wins(game_state_to_tuple(initial_T, n))

def solve_game_full(n):
    """Full game solver with detailed analysis"""
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def first_player_wins(T_tuple):
        T = set(T_tuple)

        if len(T) >= n:
            return False  # No moves possible, current player loses

        # Try all possible moves
        for g in range(n):
            if g not in T:
                generators = list(T) + [g]
                new_subgroup = set()
                changed = True
                while changed:
                    changed = False
                    for gen in generators:
                        for h in list(new_subgroup):
                            new_elem = (gen + h) % n
                            if new_elem not in new_subgroup:
                                new_subgroup.add(new_elem)
                                changed = True
                new_T = T | new_subgroup
                new_T_tuple = tuple(sorted(new_T))

                if not first_player_wins(new_T_tuple):
                    return True

        return False

    initial_T = {0}
    result = first_player_wins(tuple(sorted(initial_T)))
    return result

