    n = G[0]

    @lru_cache(None)
    def solve(H):
        # H is frozenset of current subgroup elements
        if H == set(range(n)):
            return 0  # No moves possible

        # Find all valid moves
        moves = []
        for g in range(n):
            if g not in H:
                new_H = subgroup_generated_by(H | {g}, n)
                moves.append(new_H)

        if not moves:
            return float('inf')

        # Min-max: we want to know if current player can force win
        # Actually for this game, all paths lead to same length?
        # Let's check if all moves lead to same remaining length

        lengths = []
        for new_H in moves:
            lengths.append(1 + solve(frozenset(new_H)))

        if not lengths:
