"""
Combinatorial game on subgroups of finite abelian group G.

Game: Start with T = {identity}. Players alternate adding elements from G\T.
When adding g, T becomes <T ∪ {g}>, and all new elements are moved in.
Player who cannot move loses (normal play).

We compute Grundy numbers (nimbers) for small groups.
Bob wins iff Grundy(trivial) = 0.
"""
from itertools import product, combinations

def generate_subgroup_Zp_n(generators, p, n):
    """Generate subgroup of Z_p^n from given generators (list of tuples)."""
    elements = set()
    elements.add(tuple([0]*n))

    # Add all linear combinations
    changed = True
    while changed:
        changed = False
        for g in list(generators):
            for c in range(1, p):
                new_g = tuple([(g[i] * c) % p for i in range(n)])
                if new_g not in elements:
                    elements.add(new_g)
                    changed = True

    return elements

def all_subgroups_Zp_n(n, p):
    """Find all subgroups of Z_p^n."""
    elements = list(product(range(p), repeat=n))
    subgroups = set()
    subgroups.add(frozenset([tuple([0]*n)]))

    # Try all possible generating sets
    for r in range(1, n+1):
        for gens in combinations(elements, r):
            H = frozenset(generate_subgroup_Zp_n(list(gens), p, n))
            subgroups.add(H)

    return sorted(subgroups, key=len)

def grundy_Zp_n(n, p):
    """Compute Grundy number for game on Z_p^n starting from trivial subgroup."""
    elements = list(product(range(p), repeat=n))
    all_subgroups = all_subgroups_Zp_n(n, p)
    subgroup_dict = {s: i for i, s in enumerate(all_subgroups)}

    # Memoization
    grundy_cache = {}

    def grundy_of(H):
        if H in grundy_cache:
            return grundy_cache[H]

        H_set = set(H)
        next_grundies = set()

        for g in elements:
            if g not in H_set:
                # Add g to generate new subgroup
                new_H = frozenset(generate_subgroup_Zp_n(list(H) + [g], p, n))
                next_grundies.add(grundy_of(new_H))

        # Compute mex
        mex = 0
        while mex in next_grundies:
            mex += 1
        return mex

    # Start from trivial subgroup
    trivial = frozenset([tuple([0]*n)])
    return grundy_of(trivial)

def is_bob_wins(n, p):
    """Bob wins if Grundy number is 0."""
    return grundy_Zp_n(n, p) == 0

