    group_structure: list of (n1, n2, ...) for each factor
    elements: set of tuples (e1, e2, ...)
    """
    if not elements:
        return frozenset((0,) * len(group_structure))

    # Compute subgroup by closure under addition
    subgroup = set(elements)
    changed = True
    while changed:
        changed = False
        for a in list(subgroup):
            for b in list(subgroup):
                c = tuple((a[i] + b[i]) % group_structure[i][0] for i in range(len(group_structure)))
                if c not in subgroup:
                    subgroup.add(c)
                    changed = True
    return frozenset(subgroup)

def solve_game_product(group_structure):
    """Solve game for product of cyclic groups. group_structure = [(n1,), (n2,), ...]"""
    num_factors = len(group_structure)
    sizes = [n for n, in group_structure]
    identity = tuple(0 for _ in group_structure)

    @lru_cache(maxsize=None)
    def can_win(H_tuple):
        H = frozenset(H_tuple)
        if H == frozenset(range(sizes[0] * sizes[1] * sizes[2] if num_factors > 2 else sizes[0] * sizes[1])):
            return False

        # Generate all possible next moves
        for g in range(sizes[0] * sizes[1] * sizes[2] if num_factors > 2 else sizes[0] * sizes[1]):
            if g not in H:
                # Convert linear index to tuple
                if num_factors == 1:
                    g_tuple = (g,)
                elif num_factors == 2:
                    g_tuple = (g % sizes[0], g // sizes[0])
                else:
                    # For more factors, use nested mod
                    g_tuple = []
                    temp = g
                    for n in sizes:
                        g_tuple.append(temp % n)
                        temp //= n
                    g_tuple = tuple(g_tuple)

                new_H = generate_subgroup_product(H | {g_tuple}, group_structure)
                if not can_win(tuple(sorted(new_H))):
                    return True
        return False

    return can_win(identity)

