"""
Game on finite abelian groups:
- T starts with {1_G}
- Players alternate adding element g not in T
- When g added, T becomes <T ∪ {g}>
- Last player to move wins

For proper game analysis, need to compute minimax with memoization.
"""
from functools import lru_cache
from itertools import product

def generate_subgroup(generators, order):
    """Generate subgroup of Z_n^k from given generators using BFS"""
    if not generators:
        return [tuple([0]*len(generators[0]))] if generators else []

    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        # Add g + all current elements (abelian group)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % order for i in range(len(g)))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return list(S)

def get_new_elements(current_T, new_element, order):
    """Return elements that get added when new_element is added to current_T"""
    new_T = current_T + [new_element]
    subgroup = generate_subgroup(new_T, order)
    return [x for x in subgroup if x not in current_T]

def game_state_to_tuple(T, order):
    return tuple(sorted(T))

def get_all_moves(T, order):
    """Get all possible moves from state T"""
    all_elements = set()
    for g in T:
        for i in range(len(g)):
            all_elements.add(g[i])
    all_elements = set(range(order))
    current = set(T)
    return [x for x in all_elements if x not in current]

def solve_game(order, num_dims, generators=None):
    """Solve the game using minimax with memoization"""
    if generators is None:
        generators = [1] * num_dims

    memo = {}

    def solve(T):
        T_tuple = tuple(sorted(T))
        if T_tuple in memo:
            return memo[T_tuple]

        possible_moves = get_all_moves(T, order)

        if not possible_moves:
            memo[T_tuple] = False
            return False

        # Current player wins if there exists a move that makes opponent lose
        for move in possible_moves:
            new_T = T + get_new_elements(T, move, order)
            if not solve(new_T):
                memo[T_tuple] = True
                return True

        memo[T_tuple] = False
        return False

    initial_T = [tuple([0]*num_dims)]
    alice_wins = solve(initial_T)
    return not alice_wins  # Bob wins if Alice doesn't win

def get_abelian_groups_info(max_order):
    """
    Get all abelian groups up to max_order.
    Returns list of (order, generators) tuples.
    Uses invariant factor decomposition.
    """
    groups = []

    # For each n, find all abelian groups of order n
    for n in range(2, max_order + 1):
        # Prime factorization
        factors = {}
        temp = n
        p = 2
        while p * p <= temp:
            while temp % p == 0:
                factors[p] = factors.get(p, 0) + 1
                temp //= p
            p += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1

        # For each prime power p^k, find all partitions of k
        def partitions(n):
            if n == 0:
                return [[]]
            result = []
            for i in range(1, n + 1):
                for rest in partitions(n - i):
                    result.append([i] + rest)
            return result

        # Generate all groups
        def generate_groups(factors):
            groups_list = [[]]
            for p, k in sorted(factors.items()):
                part = partitions(k)
                new_list = []
                for g in groups_list:
                    for p_part in part:
                        new_list.append(g + [p**x for x in p_part])
                groups_list = new_list
            return groups_list

        all_groups = generate_groups(factors)

        # Convert to generators (invariant factors)
        for group in all_groups:
            # Sort each component and take generators
            # For p^a, generator is p^a (or 1 for Z_p^a)
            gens = []
            for comp in group:
                if comp == [1]:
                    gens.append(1)
                else:
                    gens.append(comp[0])
            groups.append((n, gens))

    return groups

def main():
    # Test small groups
    print("Testing small abelian groups:")
    groups = get_abelian_groups_info(20)

    bob_winning = []
    for order, gens in groups:
        bob_wins = solve_game(order, len(gens), gens)
        print(f"Order {order}, gens {gens}: Bob wins = {bob_wins}")
        if bob_wins:
            bob_winning.append(order)

    print(f"\nBob wins for orders: {bob_winning}")
    print(f"Sum of 10 smallest: {sum(sorted(bob_winning)[:10])}")

if __name__ == "__main__":
    main()

"""
Game on finite abelian groups.
Bob wins iff Grundy value of starting position is 0.
"""
from functools import lru_cache
import math

def generate_subgroup_Zn_r(generators, n, r):
    """Generate subgroup of Z_n^r from given generators"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % n for i in range(r))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def grundy_Zn_r(n, r):
    """Compute Grundy value for Z_n^r"""

    @lru_cache(None)
    def g(T):
        if len(T) == n**r:
            return 0

        # Generate all elements of Z_n^r
        all_elements = set()
        for i in range(n**r):
            elem = tuple((i // (n**j)) % n for j in range(r-1, -1, -1))
            all_elements.add(elem)

        next_states = []
        for elem in all_elements:
            if elem not in T:
                new_T = generate_subgroup_Zn_r(list(T) + [elem], n, r)
                next_states.append(frozenset(new_T))

        if not next_states:
            return 0

        seen = set()
        for hs in next_states:
            seen.add(g(hs))

        mex = 0
        while mex in seen:
            mex += 1
        return mex

    identity = tuple([0]*r)
    return g(frozenset({identity}))

def is_bob_wins_Zn_r(n, r):
    return grundy_Zn_r(n, r) == 0

