from functools import lru_cache
import math

def generate_subgroup(generators, orders, r):
    """Generate subgroup of Z_{o1} x ... x Z_{or} from generators"""
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % orders[i] for i in range(r))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def grundy_for_group(orders):
    """Compute Grundy value for product of cyclic groups Z_{o1} x ... x Z_{ok}"""
    r = len(orders)

    # Generate all elements
    all_elements = set()
    for i in range(r):
        for val in range(orders[i]):
            all_elements.add(val)

    @lru_cache(None)
    def g(T):
        # T is frozenset of tuples
        if len(T) == len(all_elements):
            return 0

        next_states = []
        for elem in all_elements:
            if elem not in T:
                new_T = generate_subgroup(list(T) + [elem], orders, r)
                next_states.append(frozenset(new_T))

        if not next_states:
            return 0

        seen = set()
        for hs in next_states:
            seen.add(g(hs))

        mex = 0
        while mex in seen:
            mex += 1
        return mex

    identity = tuple([0]*r)
    return g(frozenset({identity}))

def is_bob_wins(orders):
    return grundy_for_group(orders) == 0

