"""
Game on finite abelian groups - find when Bob wins.

Key insight: For elementary abelian p-groups Z_p^n, each move increases dimension by 1.
Game length = n. Bob wins iff n is even.

For cyclic groups Z_n (n > 1), Alice can always win by picking a generator (unit).

For general groups, need to compute via minimax.
"""

from functools import lru_cache
from itertools import product

def generate_subgroup_Zp_n(generators, p, n):
    """Generate subgroup of Z_p^n from given generators."""
    elements = set()
    elements.add(tuple([0]*n))

    changed = True
    while changed:
        changed = False
        for g in list(generators):
            for c in range(1, p):
                new_g = tuple([(g[i] * c) % p for i in range(n)])
                if new_g not in elements:
                    elements.add(new_g)
                    changed = True

    return elements

def solve_game_Zp_n(n, p):
    """Solve game for Z_p^n."""
    elements = list(product(range(p), repeat=n))

    @lru_cache(maxsize=None)
    def can_win(state_frozen):
        state = set(state_frozen)
        if len(state) == p**n:
            return False  # No moves, lose

        for g in elements:
            if g not in state:
                new_H = frozenset(generate_subgroup_Zp_n(list(state) + [g], p, n))
                if not can_win(new_H):
                    return True
        return False

    trivial = frozenset([tuple([0]*n)])
    return can_win(trivial)

def solve_game_Z2xZk(k):
    """Solve game for Z_2 × Z_k."""
    n1, n2 = 2, k
    elements = [(i, j) for i in range(n1) for j in range(n2)]
    identity = (0, 0)

    @lru_cache(maxsize=None)
    def can_win(state_tuple):
        state = set(state_tuple)
        if len(state) == n1 * n2:
            return False

        for g in elements:
            if g not in state:
                # Generate subgroup: all linear combinations
                S = set()
                S.add((0, 0))
                for a in list(S):
                    for b in list(state):
                        c = ((a[0] + b[0]) % n1, (a[1] + b[1]) % n2)
                        if c not in S:
                            S.add(c)
                for b in list(state):
                    for c in list(S):
                        d = ((b[0] + c[0]) % n1, (b[1] + c[1]) % n2)
                        if d not in S:
                            S.add(d)

                new_state = tuple(sorted(S))
                if not can_win(new_state):
                    return True
        return False

    return can_win((0, 0,))

def solve_game_ZnxZm(n, m):
    """Solve game for Z_n × Z_m."""
    elements = [(i, j) for i in range(n) for j in range(m)]

    @lru_cache(maxsize=None)
    def can_win(state_tuple):
        state = set(state_tuple)
        if len(state) == n * m:
            return False

        for g in elements:
            if g not in state:
                # Generate subgroup
                S = set()
                S.add((0, 0))
                changed = True
                while changed:
                    changed = False
                    for a in list(S):
                        for b in list(state):
                            c = ((a[0] + b[0]) % n, (a[1] + b[1]) % m)
                            if c not in S:
                                S.add(c)
                                changed = True
                    for a in list(S):
                        for b in list(state):
                            c = ((a[0] + b[0]) % n, (a[1] + b[1]) % m)
                            if c not in S:
                                S.add(c)
                                changed = True

                new_state = tuple(sorted(S))
                if not can_win(new_state):
                    return True
        return False

    return can_win((0, 0,))

