"""
Verify that Bob wins for non-cyclic groups and Alice wins for cyclic groups.
"""
from functools import lru_cache
from math import gcd

def generate_subgroup_Zn(elements, n):
    """Generate subgroup of Z_n given a set of elements."""
    if not elements:
        return frozenset({0})

    g = 0
    for x in elements:
        g = gcd(g, x)
    if g == 0:
        return frozenset(range(n))
    return frozenset(range(0, n, g))

def solve_game_cyclic(n):
    """Solve game for cyclic group Z_n. Returns True if Alice wins."""
    @lru_cache(maxsize=None)
    def can_win(H_tuple):
        H = frozenset(H_tuple)
        if H == frozenset(range(n)):
            return False

        for g in range(n):
            if g not in H:
                new_H = generate_subgroup_Zn(H | {g}, n)
                if not can_win(tuple(sorted(new_H))):
                    return True
        return False

    return can_win((0,))

def generate_subgroup_product(elements, orders):
    """
    Generate subgroup of product of cyclic groups.
    orders: list of orders [n1, n2, ...]
    elements: set of tuples (e1, e2, ...)
    """
    if not elements:
        return frozenset(tuple(0 for _ in orders))

    subgroup = set(elements)
    changed = True
    while changed:
        changed = False
        for a in list(subgroup):
            for b in list(subgroup):
                c = tuple((a[i] + b[i]) % orders[i] for i in range(len(orders)))
                if c not in subgroup:
                    subgroup.add(c)
                    changed = True
    return frozenset(subgroup)

def solve_game_product(orders):
    """Solve game for product of cyclic groups. orders = [n1, n2, ...]"""
    num_factors = len(orders)
    identity = tuple(0 for _ in orders)

    total_size = 1
    for s in orders:
        total_size *= s

    @lru_cache(maxsize=None)
    def can_win(H_tuple):
        H = frozenset(H_tuple)
        if H == frozenset(range(total_size)):
            return False

        # Generate all elements as tuples
        def gen_elements(idx):
            if idx == num_factors:
                yield tuple()
                return
            for val in range(orders[idx]):
                for rest in gen_elements(idx + 1):
                    yield (val,) + rest

        for g_tuple in gen_elements(0):
            if g_tuple not in H:
                new_H = generate_subgroup_product(H | {g_tuple}, orders)
                if not can_win(tuple(sorted(new_H))):
                    return True
        return False

    return can_win(identity)

