    @lru_cache(maxsize=None)
    def can_win(H):
        if H == frozenset(range(n)):
            return False

        for g in range(n):
            if g not in H:
                new_H = generate_subgroup_Zn(H | {g}, n)
                if not can_win(new_H):
                    return True
        return False

    return can_win(frozenset({0}))

def grundy_Zn(n):
    """Compute Grundy value for Z_n."""
    @lru_cache(maxsize=None)
    def g(H):
        if H == frozenset(range(n)):
            return 0

        next_vals = set()
        for g in range(n):
            if g not in H:
                new_H = generate_subgroup_Zn(H | {g}, n)
                next_vals.add(g(new_H))

        mex = 0
        while mex in next_vals:
            mex += 1
        return mex

    return g(frozenset({0}))

