    return result

def abelian_groups_of_order(n):
    """Return list of invariant factor decompositions for abelian groups of order n."""
    if n == 1:
        return [[1]]

    factors = factorint(n)

    def prime_power_decomps(p, e):
        """Return all ways to decompose p^e as product of p^a1 * ... * p^ar with a1 | ... | ar"""
        results = []
        if e == 0:
            return [[1]]
        if e == 1:
            return [[p]]

        for a in range(1, e+1):
            rest = prime_power_decomps(p, e-a)
            for r in rest:
                results.append([p**a] + r)
        return results

    p_decomps = {}
    for p, e in factors.items():
        p_decomps[p] = prime_power_decomps(p, e)

    max_len = max(len(decomp) for decomp in p_decomps.values())
    for p in p_decomps:
        decomp = p_decomps[p]
        while len(decomp) < max_len:
            decomp.insert(0, 1)

    result = []
    for j in range(max_len):
        factor = 1
        for p in p_decomps:
            factor *= p_decomps[p][j]
        result.append(factor)

    # Remove leading 1s
    while result and result[0] == 1:
        result.pop(0)

    if not result:
        result = [1]

    return [result]

