"""
Find all orders n where there exists an abelian group G of order n where Bob wins.
Sum the 10 smallest such orders.
"""
from functools import lru_cache
from math import gcd

def partitions(n):
    """Generate all partitions of n"""
    if n == 0:
        return [[]]
    result = []
    for i in range(1, n+1):
        for rest in partitions(n-i):
            result.append([i] + rest)
    return result

def get_abelian_groups_of_order(n):
    """
    Get all abelian groups of order n.
    Returns list of lists of orders of cyclic factors.
    For example, Z_2 x Z_2 x Z_3 returns [[2,2,3]]
    """
    # Prime factorization
    factors = {}
    temp = n
    p = 2
    while p * p <= temp:
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p
        p += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # For each prime power p^e, get all group structures
    def get_groups_for_prime_power(p, e):
        """Get all abelian groups of order p^e as list of cyclic factor orders"""
        part = partitions(e)
        groups = []
        for part_list in part:
            # For partition [a1, a2, ..., ak], the group is Z_{p^a1} x ... x Z_{p^ak}
            # But we need to sort by divisibility for invariant factors
            # Actually, for the game, we just need the cyclic factor orders
            factors_list = [p**a for a in part_list]
            factors_list.sort()  # Sort for consistency
            groups.append(factors_list)
        return groups

    # Combine groups for each prime
    all_groups = [[]]
    for p, e in sorted(factors.items()):
        prime_groups = get_groups_for_prime_power(p, e)
        new_all = []
        for g in all_groups:
            for pg in prime_groups:
                new_all.append(g + pg)
        all_groups = new_all

    return all_groups

def generate_subgroup(generators, orders, r):
    S = set()
    queue = list(generators)
    while queue:
        g = queue.pop(0)
        if g in S:
            continue
        S.add(g)
        for h in list(S):
            new_elem = tuple((g[i] + h[i]) % orders[i] for i in range(r))
            if new_elem not in S and new_elem not in queue:
                queue.append(new_elem)
    return S

def grundy_for_group(orders):
    r = len(orders)

    # Generate all elements
    all_elements = set()
    def gen_all(idx, current):
        if idx == r:
            all_elements.add(tuple(current))
            return
        for val in range(orders[idx]):
            current.append(val)
            gen_all(idx + 1, current)
            current.pop()
    gen_all(0, [])

    @lru_cache(None)
    def g(T):
        if len(T) == len(all_elements):
            return 0

        next_states = []
        for elem in all_elements:
            if elem not in T:
                new_T = generate_subgroup(list(T) + [elem], orders, r)
                next_states.append(frozenset(new_T))

        if not next_states:
            return 0

        seen = set()
        for hs in next_states:
            seen.add(g(hs))

        mex = 0
        while mex in seen:
            mex += 1
        return mex

    identity = tuple([0]*r)
    return g(frozenset({identity}))

def is_bob_wins(orders):
    return grundy_for_group(orders) == 0

