                    changed = True
    return frozenset(S)

def grundy_Zn(n):
    """Compute Grundy value for Z_n."""
    @lru_cache(maxsize=None)
    def g(H):
        if H == frozenset(range(n)):
            return 0
        next_vals = set()
        for x in range(n):
            if x not in H:
                new_H = generate_subgroup_Zn(H | {x}, n)
                next_vals.add(g(new_H))
        mex = 0
        while mex in next_vals:
            mex += 1
        return mex
    return g(frozenset({0}))

