def prime_power_decomps(p, e):
    """Decompose p^e as p^a1 * ... * p^ar with a1 | ... | ar"""
    results = []
    if e == 0:
        return [[1]]
    if e == 1:
        return [[p]]
    for a in range(1, e+1):
        for r in prime_power_decomps(p, e-a):
            results.append([p**a] + r)
    return results

def abelian_groups_of_order(n):
    if n == 1:
        return [[1]]
    factors = factorint(n)
    p_decomps = {p: prime_power_decomps(p, e) for p, e in factors.items()}
    max_len = max(len(d) for d in p_decomps.values())
    for p in p_decomps:
        d = p_decomps[p]
        while len(d) < max_len:
            d.insert(0, 1)
    result = []
    for j in range(max_len):
        factor = 1
        for p in p_decomps:
            factor *= p_decomps[p][j]
        result.append(factor)
    while result and result[0] == 1:
        result.pop(0)
    if not result:
        result = [1]
    return [result]

