"""
Game on finite abelian groups - find when Bob wins.

Based on analysis:
- Elementary abelian p-groups Z_p^n: Bob wins iff n is even
- Z_n x Z_n: Need to verify Bob wins
- Cyclic groups Z_n: Alice always wins (for n > 1)
"""

from functools import lru_cache
from itertools import product

def span_Zp_n(generators, p, n):
    """Compute the subspace spanned by generators in Z_p^n."""
    S = set([tuple([0]*n)])
    changed = True
    while changed:
        changed = False
        for g in list(S):
            for h in list(generators):
                new_g = tuple([(g[i] + h[i]) % p for i in range(n)])
                if new_g not in S:
                    S.add(new_g)
                    changed = True
        for g in list(generators):
            for c in range(1, p):
                new_g = tuple([(g[i] * c) % p for i in range(n)])
                if new_g not in S:
                    S.add(new_g)
                    changed = True
    return S

def solve_game_Zp_n(n, p):
    """Solve game for Z_p^n."""
    elements = list(product(range(p), repeat=n))

    @lru_cache(maxsize=None)
    def can_win(state_frozen):
        state = set(state_frozen)
        if len(state) == p**n:
            return False
        for g in elements:
            if g not in state:
                new_H = frozenset(span_Zp_n(list(state) + [g], p, n))
                if not can_win(new_H):
                    return True
        return False

    trivial = frozenset([tuple([0]*n)])
    return can_win(trivial)

def span_Zm(generators, m):
    """Compute subgroup generated by generators in Z_m."""
    S = set([0])
    changed = True
    while changed:
        changed = False
        for g in list(S):
            for h in list(generators):
                new_g = (g + h) % m
                if new_g not in S:
                    S.add(new_g)
                    changed = True
    return S

def solve_game_Zn(n):
    """Solve game for cyclic group Z_n."""
    elements = list(range(n))

    @lru_cache(maxsize=None)
    def can_win(state_frozen):
        state = set(state_frozen)
        if len(state) == n:
            return False
        for g in elements:
            if g not in state:
                new_H = frozenset(span_Zm(list(state) + [g], n))
                if not can_win(new_H):
                    return True
        return False

    trivial = frozenset([0])
    return can_win(trivial)

def span_ZnxZm(generators, n, m):
    """Compute subgroup generated by generators in Z_n x Z_m."""
    S = set([(0, 0)])
    changed = True
    while changed:
        changed = False
        for g in list(S):
            for h in list(generators):
                new_g = ((g[0] + h[0]) % n, (g[1] + h[1]) % m)
                if new_g not in S:
                    S.add(new_g)
                    changed = True
    return S

def solve_game_ZnxZm(n, m):
    """Solve game for Z_n x Z_m."""
    elements = [(i, j) for i in range(n) for j in range(m)]

    @lru_cache(maxsize=None)
    def can_win(state_frozen):
        state = set(state_frozen)
        if len(state) == n * m:
            return False
        for g in elements:
            if g not in state:
                new_H = frozenset(span_ZnxZm(list(state) + [g], n, m))
                if not can_win(new_H):
                    return True
        return False

    trivial = frozenset([(0, 0)])
    return can_win(trivial)

