from functools import lru_cache

def solve_product(orders):
    """Solve game for product of cyclic groups. Returns True if Alice wins."""
    identity = tuple(0 for _ in orders)
    total = 1
    for s in orders:
        total *= s

    @lru_cache(maxsize=None)
    def can_win(H_tuple):
        H = frozenset(H_tuple)
        if H == frozenset(range(total)):
            return False

        def gen_elements():
            def helper(idx, current):
                if idx == len(orders):
                    yield current
                    return
                for val in range(orders[idx]):
                    yield from helper(idx + 1, current + (val,))
            yield from helper(0, tuple())

        for g_tuple in gen_elements():
            if g_tuple not in H:
                # Generate subgroup
                S = set(H | {g_tuple})
                changed = True
                while changed:
                    changed = False
                    for a in list(S):
                        for b in list(S):
                            c = tuple((a[i] + b[i]) % orders[i] for i in range(len(orders)))
                            if c not in S:
                                S.add(c)
                                changed = True
                new_H = tuple(sorted(S))
                if not can_win(new_H):
                    return True
        return False

    return can_win(identity)

