"""
Test the hypothesis: N(n) = n (only diagonal pairs guaranteed)
vs N(n) = C(n, ceil(n/2)) (my empirical result)
"""

from math import comb

def simulate(n, initial, max_steps=10000):
    """Simulate and return history of values."""
    values = list(initial)
    history = [values[:]]

    for _ in range(max_steps):
        new_values = values[:]
        for i in range(n):
            new_values[i] = values[i] + 1.0 / values[(i + 1) % n]
        values = new_values
        history.append(values[:])

    return history

def pair_crosses(n, i, j, initial, max_steps=10000):
    """Check if v_i ever >= v_j."""
    history = simulate(n, initial, max_steps)
    for h in history:
        if h[i] >= h[j]:
            return True
    return False

def compute_N(n, trials=5):
    """Compute N(n) by testing various initial conditions."""
    guaranteed = set()

    # Test diagonal pairs (should always be guaranteed)
    for i in range(n):
        guaranteed.add((i, i))

    # Test off-diagonal pairs with various initial conditions
    off_diagonal = set((i, j) for i in range(n) for j in range(n) if i != j)

    # Try many initial configurations
    configs = [
        # All equal
        [1.0] * n,
        # Alternating small/large
        [1e-6 if k % 2 == 0 else 1e6 for k in range(n)],
        # Concentrated at j
        [1e6 if k == j else 1e-6 for k in range(n)] for j in range(n)
    ]

    # Flatten the list comprehension
    for j in range(n):
        configs.append([1e6 if k == j else 1e-6 for k in range(n)])

    for config in configs:
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if pair_crosses(n, i, j, config, max_steps=1000):
                    guaranteed.add((i, j))

    return len(guaranteed)

# Test for small n
