"""
Final verification: Check if n-1 is indeed the answer by testing various trees.
"""

from sympy import symbols, solve, simplify, Eq

X, Y = symbols('X Y')

def test_tree(n, d, edges):
    """Test a specific tree with given edges"""
    z = symbols('z0:'+str(n))
    coeffs = symbols('c0:'+str((d+1)*(d+2)//2))

    # Build polynomial
    P = 0
    idx = 0
    for deg in range(d + 1):
        for d1 in range(deg + 1):
            d2 = deg - d1
            if d2 >= 0:
                P += coeffs[idx] * X**d1 * Y**d2
                idx += 1

    # Constraints for ALL ordered pairs
    eqs = []
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            is_edge = (i, j) in edges
            eqs.append(Eq(P.subs({X: z[i], Y: z[j]}), 0 if is_edge else 1))

    sol = solve(eqs, list(coeffs), dict=True)

    if sol:
        P_sub = simplify(P.subs(sol[0]))
        # Verify
        all_ok = True
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                is_edge = (i, j) in edges
                val = simplify(P_sub.subs({X: z[i], Y: z[j]}))
                expected = 0 if is_edge else 1
                if val != expected:
                    all_ok = False
                    break
            if not all_ok:
                break
        return all_ok
    else:
        return False

