from sympy import symbols, solve, simplify, Eq, Matrix

def test_exact(n, d, edges_set):
    """Test with exact symbolic solving."""
    z = symbols('z0:'+str(n))
    X, Y = symbols('X Y')

    # Build polynomial of degree d
    coeffs = symbols('c0:'+str((d+1)*(d+2)//2))
    P = 0
    idx = 0
    for deg in range(d + 1):
        for d1 in range(deg + 1):
            d2 = deg - d1
            if d2 >= 0:
                P += coeffs[idx] * X**d1 * Y**d2
                idx += 1

    # Constraints for ALL ordered pairs i ≠ j
    eqs = []
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            is_edge = (i, j) in edges_set
            eqs.append(Eq(P.subs({X: z[i], Y: z[j]}), 0 if is_edge else 1))

    # Solve
    sol = solve(eqs, list(coeffs), dict=True)

    if sol:
        P_sub = simplify(P.subs(sol[0]))
        # Verify
        all_ok = True
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                is_edge = (i, j) in edges_set
                val = simplify(P_sub.subs({X: z[i], Y: z[j]}))
                expected = 0 if is_edge else 1
                if val != expected:
                    all_ok = False
                    print(f"    Failed at ({i},{j}): got {val}, expected {expected}")
                    break
            if not all_ok:
                break
        return all_ok
    else:
        return False

