"""
Test if k = n-2 works for small cases with actual numeric values.
"""

import numpy as np

def test_symmetric_interpolation(n, d, seed=42):
    """Test if a symmetric polynomial of degree d can interpolate edge/non-edge values."""
    np.random.seed(seed)

    # Generate distinct random complex numbers
    z = np.random.randn(n) + 1j * np.random.randn(n)

    # Build linear system for SYMMETRIC polynomials
    # For symmetric P, we only need to specify values on unordered pairs {i,j} with i < j
    pairs = []
    for i in range(n):
        for j in range(i+1, n):
            pairs.append((i, j))

    num_pairs = len(pairs)
    num_params = (d+1)*(d+2)//2

    if num_params < num_pairs:
        return False, f"Underdetermined: {num_params} params < {num_pairs} pairs"

    # Build Vandermonde-like matrix for symmetric polynomials
    # We use standard monomial basis but will enforce symmetry in the solution
    A = np.zeros((num_pairs, num_params), dtype=complex)
    b = np.zeros(num_pairs, dtype=complex)

    idx = 0
    for i, j in pairs:
        # Fill row for (z_i, z_j)
        for a in range(d+1):
            for b_exp in range(d+1-a):
                A[idx, a + b_exp] = z[i]**a * z[j]**b_exp
        # Set target value (0 for edge, 1 for non-edge)
        b[idx] = 1.0

        idx += 1

    # Solve for coefficients
    try:
        coeffs, residuals, rank, s = np.linalg.lstsq(A, b, rcond=None)

        # Check if solution is exact (residuals should be ~0)
        if residuals[0] > 1e-10:
            return False, f"Residual {residuals[0]:.2e}"

        # Verify on ALL ordered pairs
        edges = [(i, i+1) for i in range(n-1)]  # Path graph
        all_ok = True

        for i in range(n):
            for j in range(n):
                if i == j:
                    continue

                # Compute P(z_i, z_j)
                val = 0
                for a in range(d+1):
                    for b_exp in range(d+1-a):
                        val += coeffs[a + b_exp] * z[i]**a * z[j]**b_exp

                is_edge = (i, j) in edges or (j, i) in edges

                if is_edge:
                    if abs(val) > 1e-6:
                        all_ok = False
                else:
                    if abs(val) < 1e-6:
                        all_ok = False

        return all_ok, "OK"
    except Exception as e:
        return False, str(e)

print("=== Testing k = n - 2 ===")
for n in range(3, 8):
    d = n - 2
    ok, msg = test_symmetric_interpolation(n, d)
    print(f"n={n}, k={d}: {'PASS' if ok else 'FAIL'} - {msg}")

