"""
Math problem: Maximum sum of scores for n students in n races.

A student is eligible for rating (a, b) if they come in top b places in at least a races.
Score = max(a - b) over all eligible ratings.
Maximize sum of all scores.

For each student i and position b (1-indexed), let c_{i,b} = # races where student i is in top b.
Score_i = max_{b=1..n} (c_{i,b} - b).

Optimal arrangement: each student always finishes in a fixed position.
Student at fixed position p (1-indexed) is in top b for all b >= p.
So c_{i,b} = n for b >= p, and 0 otherwise.
Score = max_{b>=p} (n - b) = n - p.
Total = sum_{p=1}^n (n - p) = (n-1) + (n-2) + ... + 0 = n(n-1)/2.

Verified by brute force for n=1,2,3,4.
"""

from itertools import permutations

def compute_score(n, rankings):
    """
    rankings: list of n lists, each is a permutation [0, 1, ..., n-1]
               rankings[race][student] = position (0-indexed)
    """
    # c[i][b] = number of races where student i is in top b (b is 1-indexed)
    c = [[0] * (n + 1) for _ in range(n)]

    for race in range(n):
        for student, pos in enumerate(rankings[race]):
            # pos is 0-indexed, so student is in top b if pos < b (i.e., rank <= b)
            for b in range(1, n + 1):
                if pos < b:
                    c[student][b] += 1

    total_score = 0
    for i in range(n):
        max_score = float('-inf')
        for b in range(1, n + 1):
            if c[i][b] >= 1:
                max_score = max(max_score, c[i][b] - b)
        total_score += max_score

    return total_score

def optimal_score_formula(n):
    return n * (n - 1) // 2

# Verify for n=1 to 10
print("Verification:")
for n in range(1, 11):
    # "All same" arrangement: student i always at position i
    rankings = [[i for i in range(n)] for _ in range(n)]
    computed = compute_score(n, rankings)
    formula = optimal_score_formula(n)
    print(f"n={n}: computed={computed}, formula={formula}, match={computed==formula}")

# Brute force for n=1,2,3,4
print("\nBrute force verification:")
def brute_force_max(n):
    max_score = 0
    for p in permutations(range(n)):
        for q in permutations(range(n)):
            if n == 1:
                positions = [list(p)]
            elif n == 2:
                positions = [list(p), list(q)]
            elif n == 3:
                for r in permutations(range(n)):
                    positions = [list(p), list(q), list(r)]
                    s = compute_score(n, positions)
                    if s > max_score:
                        max_score = s
            elif n == 4:
                for r in permutations(range(n)):
                    for s in permutations(range(n)):
                        positions = [list(p), list(q), list(r), list(s)]
                        score = compute_score(n, positions)
                        if score > max_score:
                            max_score = score
    return max_score

for n in range(1, 5):
    bf = brute_force_max(n)
    formula = optimal_score_formula(n)
    print(f"n={n}: brute_force={bf}, formula={formula}, match={bf==formula}")

