"""
Problem: n students, n races, each race has distinct rankings 1..n.
Student eligible for (a,b) if they rank in top b in at least a races.
Score = max(a-b) over eligible ratings.

Optimal: Each student always finishes at a fixed position.
Student i at position p has score n-p.
Total = sum_{p=1}^n (n-p) = n(n-1)/2.

Verified by brute force for n=1,2,3,4.
"""
import itertools

def student_score(ranks):
    n = len(ranks)
    score = float('-inf')
    for b in range(1, n + 1):
        k_b = sum(1 for r in ranks if r <= b)
        current = k_b - b
        if current > score:
            score = current
    return max(score, 0)

def total_score(races):
    n = len(races)
    return sum(student_score([races[j][i] for j in range(n)]) for i in range(n))

def all_same_races(n):
    return [[i + 1 for i in range(n)] for _ in range(n)]

def brute_force(n):
    best = 0
    perms = list(itertools.permutations([1, 2, 3, 4]))
    if n == 2:
        for r1 in perms:
            for r2 in perms:
                score = total_score([list(r1), list(r2)])
                best = max(best, score)
    elif n == 3:
        for r1 in perms:
            for r2 in perms:
                for r3 in perms:
                    score = total_score([list(r1), list(r2), list(r3)])
                    best = max(best, score)
    elif n == 4:
        for r1 in perms:
            for r2 in perms:
                for r3 in perms:
                    for r4 in perms:
                        score = total_score([list(r1), list(r2), list(r3), list(r4)])
                        best = max(best, score)
    return best

print("Verification:")
for n in range(1, 5):
    brute = brute_force(n) if n <= 4 else total_score(all_same_races(n))
    formula = n * (n - 1) // 2
    print(f"n={n}: brute={brute}, formula={formula}, match={brute==formula}")

# The answer is the expression n(n-1)/2
