def check_values(P_coeffs, Q_coeffs, a, b, num_points=100):
    """Check divisibility by evaluating at many points"""
    for n in range(1, num_points + 1):
        # Evaluate polynomials at n
        p_val = sum(c * n**i for i, c in enumerate(P_coeffs))
        q_val = sum(c * n**i for i, c in enumerate(Q_coeffs))

        if p_val == 0 or q_val == 0:
            continue

        # Check divisibility
        if (q_val**2 + a*q_val + 1) % p_val != 0:
            return False
        if (p_val**2 + b*p_val + 1) % q_val != 0:
            return False
    return True

def check_polynomial(P_poly, Q_poly, a, b):
    """Check polynomial divisibility"""
    Q_sq_aQ_1 = Q_poly**2 + a*Q_poly + 1
    P_sq_bP_1 = P_poly**2 + b*P_poly + 1

    _, rem1 = div(Q_sq_aQ_1, P_poly)
    _, rem2 = div(P_sq_bP_1, Q_poly)

    return rem1 == 0 and rem2 == 0

