For eval_poly([c0, c1, c2], n) = c0*n^2 + c1*n + c2
So [c0, c1, ..., ck] represents ck*x^k + ... + c1*x + c0
Monic means leading coefficient (last element) = 1.
Non-constant means degree >= 1 (at least 2 elements).
"""

def eval_poly(coeffs, n):
    result = 0
    for c in coeffs:
        result = result * n + c
    return result

def check_solution(P, Q, a, b, max_n=100):
    for n in range(1, max_n + 1):
        p_val = eval_poly(P, n)
        q_val = eval_poly(Q, n)

        if p_val == 0 or q_val == 0:
            continue

        if (q_val**2 + a*q_val + 1) % p_val != 0:
            return False
        if (p_val**2 + b*p_val + 1) % q_val != 0:
            return False
    return True

