Q(n) | P(n)^2 + bP(n) + 1
for all positive integers n.

Coefficients are stored in descending order: [leading, ..., constant]
For x: [1, 0], for x^2: [1, 0, 0], for x^2+1: [1, 0, 1], for x^2-8: [1, 0, -8]
"""

def eval_poly(coeffs, n):
    """Evaluate polynomial with coeffs in descending order at x = n"""
    result = 0
    for c in coeffs:
        result = result * n + c
    return result

def check_solution(P_coeffs, Q_coeffs, a, b):
    """Check if P(n) | Q(n)^2 + aQ(n) + 1 and Q(n) | P(n)^2 + bP(n) + 1 for n = 1, 2, ..., 10"""
    for n in range(1, 11):
        P_val = eval_poly(P_coeffs, n)
        Q_val = eval_poly(Q_coeffs, n)

        if P_val == 0:
            return False, f"P({n}) = 0"
        if Q_val == 0:
            return False, f"Q({n}) = 0"

        rem1 = (Q_val**2 + a*Q_val + 1) % P_val
        rem2 = (P_val**2 + b*P_val + 1) % Q_val

        if rem1 != 0:
            return False, f"P({n})={P_val} doesn't divide Q({n})^2 + aQ({n}) + 1, remainder = {rem1}"
        if rem2 != 0:
            return False, f"Q({n})={Q_val} doesn't divide P({n})^2 + bP({n}) + 1, remainder = {rem2}"

    return True, "OK"

