"""
Search for polynomial solutions with CORRECT coefficient ordering.
For eval_poly([c0, c1, c2], n) = c0 + c1*n + c2*n^2
So [r, p, 1] represents r + p*n + n^2 = n^2 + p*n + r (monic quadratic)
"""

def eval_poly(coeffs, n):
    """Evaluate polynomial: coeffs[0] + coeffs[1]*n + coeffs[2]*n^2 + ..."""
    result = 0
    power = 1
    for c in coeffs:
        result += c * power
        power *= n
    return result

def check_solution(P, Q, a, b, max_n=200):
    for n in range(1, max_n + 1):
        p_val = eval_poly(P, n)
        q_val = eval_poly(Q, n)

        if p_val == 0 or q_val == 0:
            continue

        if (q_val**2 + a*q_val + 1) % p_val != 0:
            return False
        if (p_val**2 + b*p_val + 1) % q_val != 0:
            return False
    return True

