def count_swaps(p, target):
    """Count minimum adjacent swaps to transform p to target."""
    # This is the number of inversions between p and target
    # Map p to identity and count inversions
    n = len(p)
    pos = {p[i]: i for i in range(n)}
    # Create sequence of positions
    seq = [pos[target[i]] for i in range(n)]
    # Count inversions
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            if seq[i] > seq[j]:
                count += 1
    return count

