    # BFS to explore reachable states
    # State: tuple of black cells as frozenset of (r,c)
    start = frozenset([(0, 0)])
    visited = {start}
    queue = deque([start])

    max_steps = 50000  # limit to avoid infinite loops
    steps = 0

    while queue and steps < max_steps:
        state = queue.popleft()
        steps += 1

        if len(state) == n * n:
            return True

        # Try all 2×2 squares
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                black_in_square = [cell for cell in cells if cell in state]

                if len(black_in_square) == 1:
                    # Can apply operation
                    new_cells = frozenset(state)
                    for cell in cells:
                        if cell not in state:
                            new_cells = new_cells | frozenset([cell])

                    if new_cells not in visited:
                        visited.add(new_cells)
                        queue.append(new_cells)

    return False

