# Systematic enumeration of all graphs for small n to find D(n)

from itertools import combinations, product

def mex(values):
    s = set(values)
    i = 0
    while i in s:
        i += 1
    return i

def simulate(n, edges, initial, max_days=200):
    """Simulate the game. Returns day when stabilized, or None if cycles."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    current = list(initial)

    for day in range(1, max_days + 1):
        next_state = []
        for i in range(n):
            neighbors = [current[j] for j in adj[i]]
            next_state.append(mex(neighbors))

        if next_state == current:
            return day

        current = next_state

    return None  # Cycles

def find_D_for_graph(n, edges):
    """Find max days over all starting configurations for a given graph."""
    max_d = 0
    for start_val in range(n + 2):
        for config in product(range(start_val + 1), repeat=n):
            d = simulate(n, edges, list(config), max_days=50)
            if d is not None:
                max_d = max(max_d, d)
    return max_d

def all_graphs(n):
    """Generate all graphs on n vertices (up to isomorphism would be better but we'll do all)."""
    edges = list(combinations(range(n), 2))
    for mask in range(1 << len(edges)):
        graph_edges = [edges[i] for i in range(len(edges)) if mask & (1 << i)]
        yield graph_edges

def find_D(n):
    """Find D(n) = maximum days over all graphs and starting configs."""
    max_days = 0
    best_graph = None
    best_config = None

    for edges in all_graphs(n):
        d = find_D_for_graph(n, edges)
        if d > max_days:
            max_days = d
            best_graph = edges

    return max_days, best_graph

