def solve_interp1():
    """Total B-uses across game ≤ 5"""
    MAX_N = 2025
    MAX_K = 5

    dp = [[0] * (MAX_K + 1) for _ in range(MAX_N + 1)]

    for k in range(MAX_K + 1):
        dp[0][k] = 0

    for n in range(1, MAX_N + 1):
        for k in range(MAX_K + 1):
            can_reach_losing = False

            for pick in [1, 2, 3]:
                if n >= pick and dp[n - pick][k] == 0:
                    can_reach_losing = True
                    break

            if not can_reach_losing and n >= 4 and k > 0:
                if dp[n - 4][k - 1] == 0:
                    can_reach_losing = True

            dp[n][k] = 1 if can_reach_losing else 0

    return sum(1 for n in range(1, MAX_N + 1) if dp[n][5] == 1)


def solve_interp2():
    """Each player can use B up to 5 times independently"""
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can_win(n, alice_b_left, bob_b_left, turn):
        """turn: 0 = Alice, 1 = Bob"""
        for pick in [1, 2, 3]:
            if n >= pick:
                if n - pick == 0:
                    return True
                new_turn = 1 - turn
                if not can_win(n - pick, alice_b_left, bob_b_left, new_turn):
                    return True

        if n >= 4:
            if turn == 0 and alice_b_left > 0:
