                if n - 4 == 0:
                    return True
                if not can_win(n - 4, alice_b_left, bob_b_left - 1, 0):
                    return True

        return False

    count = 0
    for n in range(1, 2026):
        if can_win(n, 5, 5, 0):
            count += 1
    return count


