    def dfs(r, c, visited, steps):
        # Check if reached row D
        if r == 3:
            return 1

        # Max steps is 6
        if steps >= 6:
            return 0

        total = 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check bounds
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    new_visited = visited | {(nr, nc)}
                    total += dfs(nr, nc, new_visited, steps + 1)

        return total

