Grid: 4 rows (A=0, B=1, C=2, D=3), 7 columns (0-6)
Start: (0, 3), Target: any cell in row 3
Constraints: no revisiting, max 6 moves, stop when reaching row D
"""

def count_paths():
    rows = 4
    cols = 7
    start = (0, 3)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 0

    def dfs(r, c, visited, moves):
        nonlocal count
        if r == 3:
            count += 1
            return
        if moves >= 6:
            return
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    dfs(nr, nc, visited, moves + 1)
                    visited.remove((nr, nc))

    visited = {start}
    dfs(start[0], start[1], visited, 0)
    return count

